/**
 * pages/AdminDashboard.js - admin shell + view router.
 *
 * Sidebar-driven single-page shell for admins. Each nav item maps to one view
 * rendered by the switch(activeView) in renderView(): switching views unmounts
 * the old one and mounts the new (state does not survive a view change here,
 * unlike the creator dashboard's always-mounted Campaigns). Active view is
 * persisted to localStorage so a reload returns to the same place.
 *
 * SystemHealthProvider wraps the shell so the always-on health poller, the
 * HealthBeacon, and the System Health nav dot all read one source.
 *
 * @gotcha ErrorBoundary uses key={activeView} so navigating away from a crashed
 *         view resets it.
 * @see docs/CODEBASE.md (routing, System Health)
 */
import React, { useState, useEffect, useCallback } from 'react';
import Sidebar from '../components/shared/Sidebar';
import AdminOverview from '../components/admin/AdminOverview';
import CampaignsView from '../components/admin/CampaignsView';
import AgenciesView from '../components/admin/AgenciesView';
import PaymentsView from '../components/admin/PaymentsView';
import UsersView from '../components/admin/UsersView';
import AnalyticsView from '../components/admin/AnalyticsView';
import PlatformSetupView from '../components/admin/PlatformSetupView';
import PaymentSetupView from '../components/admin/PaymentSetupView';
import CalendarView from '../components/admin/CalendarView';
import RewardsView from '../components/admin/RewardsView';
import AdminSharedDashboards from '../components/admin/AdminSharedDashboards';
import SystemHealthView from '../components/admin/SystemHealthView';
import WorkflowSetupView from '../components/admin/WorkflowSetupView';
import ExpensesView from '../components/admin/ExpensesView';
import BusinessProfileView from '../components/admin/BusinessProfileView';
import FinancialsView from '../components/admin/FinancialsView';
import PartnersView from '../components/admin/PartnersView';
import AdminHelp from '../components/admin/AdminHelp';
import SecurityPage from '../components/shared/SecurityPage';
import ErrorBoundary from '../components/shared/ErrorBoundary';
import HealthBeacon from '../components/shared/HealthBeacon';
import { SystemHealthProvider, useSystemHealth } from '../hooks/useSystemHealth';
import { useHelpOpen } from '../hooks/useHelpOpen';
import { AudienceProvider } from '../contexts/AudienceContext';
import { IC } from './navIcons';
import { hasUnsaved, DISCARD_PROMPT } from '../hooks/useUnsavedGuard';
import { useConfirm } from '../components/shared/ConfirmDialog';

const NAV = [
  {
    label: null,
    items: [
      { view: 'overview',      icon: IC.home,     label: 'Overview' },
      { view: 'campaigns',     icon: IC.campaign,  label: 'Campaigns' },
      { view: 'calendar',      icon: IC.calendar,  label: 'Calendar' },
      { view: 'payments',      icon: IC.dollar,    label: 'Payments' },
      { view: 'expenses',      icon: IC.receipt,   label: 'Expenses' },
      { view: 'rewards',       icon: IC.star,      label: 'Rewards' },
      { view: 'analytics',     icon: IC.chart,     label: 'Analytics' },
      { view: 'shared-dashboards', icon: IC.share, label: 'Shared Dashboards' },
    ]
  },
  {
    label: 'Accounting',
    items: [
      { view: 'financials',     icon: IC.ledger,   label: 'Financials' },
      { view: 'partners',       icon: IC.partners, label: 'Partners' },
    ]
  },
  {
    label: 'Setup',
    items: [
      { view: 'agencies',       icon: IC.building, label: 'Agency Setup' },
      { view: 'platform-setup', icon: IC.grid,     label: 'Platform Setup' },
      { view: 'payment-setup',  icon: IC.card,     label: 'Payment Setup' },
      { view: 'users',            icon: IC.users,     label: 'Creator Setup' },
      { view: 'workflow-setup',   icon: IC.sliders,   label: 'Workflow Setup' },
      { view: 'business-profile', icon: IC.briefcase, label: 'Business Profile' },
      { view: 'system-health',    icon: IC.pulse,     label: 'System Health' },
    ]
  },
  {
    label: 'Account',
    items: [
      { view: 'security', icon: IC.shield, label: 'Security' },
    ]
  },
  {
    label: 'Help',
    items: [
      { view: 'help', icon: IC.help, label: 'Help' },
    ]
  }
];

const ADMIN_VIEW_KEY = 'nys_admin_active_view';

/** Admin entry point: wraps the shell in the System Health context. */
export default function AdminDashboard() {
  return (
    <AudienceProvider audience="admin">
      <SystemHealthProvider>
        <AdminShell />
      </SystemHealthProvider>
    </AudienceProvider>
  );
}

/**
 * The sidebar + routed-content shell. Holds activeView plus the pending-* deep
 * link state (campaign / deliverable / payment / ledger filter / help slug) that
 * cross-view navigation and the nys:* CustomEvents stash for the target view to
 * consume on mount.
 */
function AdminShell() {
  const [activeView, setActiveView]               = useState(() => {
    try { return localStorage.getItem(ADMIN_VIEW_KEY) || 'overview'; }
    catch { return 'overview'; }
  });
  useEffect(() => {
    try { localStorage.setItem(ADMIN_VIEW_KEY, activeView); } catch {}
  }, [activeView]);

  const confirm = useConfirm();
  /**
   * Switching view unmounts whatever is on screen, and a detail panel has no close button of
   * its own, so navigating IS how a half-filled panel gets discarded. Everything else in the
   * hub leaves through Modal, which asks for itself.
   */
  const goToView = useCallback(async (next) => {
    if (hasUnsaved() && !(await confirm(DISCARD_PROMPT))) return;
    setActiveView(next);
  }, [confirm]);
  const [pendingCampaignId, setPendingCampaignId] = useState(null);
  const [pendingCampaignTab, setPendingCampaignTab] = useState(null);
  const [pendingDeliverableId, setPendingDeliverableId] = useState(null);
  const [pendingPaymentCampaignId, setPendingPaymentCampaignId] = useState(null);
  const [pendingRewardEntryId, setPendingRewardEntryId] = useState(null);
  const [pendingExpenseId, setPendingExpenseId] = useState(null);
  const [pendingUserId, setPendingUserId] = useState(null);
  const [pendingLedgerFilter, setPendingLedgerFilter] = useState(null);
  const [pendingHelpSlug, setPendingHelpSlug] = useState(null);
  const [helpReturnView,  setHelpReturnView]  = useState(null); // { view, label }

  useHelpOpen({
    audience: 'admin', nav: NAV, setActiveView, setHelpReturnView, setPendingHelpSlug,
  });

  // Deep-link into GL from anywhere (used by CancelCampaignDialog's blocked
  // states so the user can reverse the offending JE in place). Detail shape
  // matches LedgerPage initialFilter: { tab, source_type, source_id }.
  useEffect(() => {
    function handler(e) {
      const detail = e?.detail || {};
      // `month` rides along for the Payroll tab, which is addressed by a month rather than by a
      // source record. @see utils/ledgerSourceLink.js
      // `accountId` rides along for an entry the GL cannot address by source either: the payroll
      // tax remittance is source_type 'manual' with no source_id, so the only way to land on it
      // is its ACCOUNT, 2200, whose two lines for the month are the entry and what it discharged.
      // `entry_id` rides along for the entry a health check names directly. Source type and id
      // narrow the GL to a record's entries, which is right when the record is the subject; a
      // failing invariant's subject is ONE entry, and half of them (a lopsided pair, an
      // unclaimed reversal) carry no source id to be found by at all.
      setPendingLedgerFilter({
        tab: detail.tab || 'gl',
        source_type: detail.source_type,
        source_id: detail.source_id,
        entryId: detail.entry_id,
        accountId: detail.accountId,
        month: detail.month,
      });
      setActiveView('financials');
    }
    if (typeof window !== 'undefined') window.addEventListener('nys:open-ledger', handler);
    return () => { if (typeof window !== 'undefined') window.removeEventListener('nys:open-ledger', handler); };
  }, []);

  // Deep-link into Payments and auto-open a campaign's invoice panel. Dispatched
  // by the read-only InvoiceTab on the campaign slide-out so invoice editing
  // happens in one place (the Payments detail panel).
  useEffect(() => {
    function handler(e) {
      const detail = e?.detail || {};
      setPendingPaymentCampaignId(detail.campaign_id || null);
      setActiveView('payments');
    }
    if (typeof window !== 'undefined') window.addEventListener('nys:open-payment', handler);
    return () => { if (typeof window !== 'undefined') window.removeEventListener('nys:open-payment', handler); };
  }, []);

  // Deep-link into Campaigns and auto-open one campaign ON A NAMED TAB. Dispatched by a System
  // Health record whose fix is a control on a specific tab of the slide-out, which today means
  // the two Stripe payment-link checks: the Deactivate button lives on `paylink` and nowhere
  // else, so landing on the campaign alone would leave the reader hunting six tabs.
  useEffect(() => {
    function handler(e) {
      const detail = e?.detail || {};
      setPendingCampaignId(detail.campaign_id || null);
      setPendingCampaignTab(detail.tab || null);
      setPendingDeliverableId(null);
      setActiveView('campaigns');
    }
    if (typeof window !== 'undefined') window.addEventListener('nys:open-campaign', handler);
    return () => { if (typeof window !== 'undefined') window.removeEventListener('nys:open-campaign', handler); };
  }, []);

  // Deep-link into Rewards / Expenses and auto-open a record. Dispatched by a
  // ledger or reconciliation line (LedgerPage's LedgerSourceLink) so a cash line
  // can jump to the reward entry or expense that produced it. Mirrors
  // nys:open-payment above.
  useEffect(() => {
    function onReward(e) {
      setPendingRewardEntryId(e?.detail?.reward_entry_id || null);
      setActiveView('rewards');
    }
    function onExpense(e) {
      setPendingExpenseId(e?.detail?.expense_id || null);
      setActiveView('expenses');
    }
    if (typeof window !== 'undefined') {
      window.addEventListener('nys:open-reward', onReward);
      window.addEventListener('nys:open-expense', onExpense);
    }
    return () => {
      if (typeof window !== 'undefined') {
        window.removeEventListener('nys:open-reward', onReward);
        window.removeEventListener('nys:open-expense', onExpense);
      }
    };
  }, []);

  // Deep-link into Creator Setup and auto-open a person's Edit User modal.
  // Dispatched by a Tax Center Estimate row with no return figures on file, so
  // the report can point at the fix without becoming an editor itself.
  useEffect(() => {
    function handler(e) {
      setPendingUserId(e?.detail?.profile_id || null);
      setActiveView('users');
    }
    if (typeof window !== 'undefined') window.addEventListener('nys:open-user', handler);
    return () => { if (typeof window !== 'undefined') window.removeEventListener('nys:open-user', handler); };
  }, []);

  function backFromHelp() {
    if (!helpReturnView) return;
    const target = helpReturnView.view;
    setHelpReturnView(null);
    setPendingHelpSlug(null);
    setActiveView(target);
  }

  function navigateToCampaign(campaignId) {
    setPendingCampaignId(campaignId);
    setPendingCampaignTab(null);
    setPendingDeliverableId(null);
    setActiveView('campaigns');
  }

  function navigateToDeliverable(campaignId, deliverableId) {
    setPendingCampaignId(campaignId);
    setPendingCampaignTab(null);
    setPendingDeliverableId(deliverableId);
    setActiveView('campaigns');
  }

  function navigateToLedger(filter) {
    setPendingLedgerFilter(filter);
    setActiveView('financials');
  }

  function navigateToTaxCenter(year) {
    setPendingLedgerFilter({ tab: 'tax', year });
    setActiveView('financials');
  }

  function renderView() {
    switch (activeView) {
      case 'overview':         return <AdminOverview setActiveView={setActiveView} navigateToCampaign={navigateToCampaign} navigateToDeliverable={navigateToDeliverable} />;
      case 'campaigns':        return <CampaignsView pendingCampaignId={pendingCampaignId} pendingCampaignTab={pendingCampaignTab} pendingDeliverableId={pendingDeliverableId} />;
      case 'calendar':         return <CalendarView />;
      case 'payments':         return <PaymentsView onNavigateToLedger={navigateToLedger} pendingCampaignId={pendingPaymentCampaignId} onConsumed={() => setPendingPaymentCampaignId(null)} />;
      case 'expenses':         return <ExpensesView pendingExpenseId={pendingExpenseId} onConsumed={() => setPendingExpenseId(null)} />;
      case 'rewards':          return <RewardsView onNavigateToLedger={navigateToLedger} pendingEntryId={pendingRewardEntryId} onConsumed={() => setPendingRewardEntryId(null)} />;
      case 'analytics':        return <AnalyticsView navigateToCampaign={navigateToCampaign} />;
      case 'agencies':         return <AgenciesView />;
      case 'platform-setup':   return <PlatformSetupView />;
      case 'payment-setup':    return <PaymentSetupView onNavigateToLedger={navigateToLedger} />;
      case 'users':              return <UsersView pendingUserId={pendingUserId} onConsumed={() => setPendingUserId(null)} />;
      case 'shared-dashboards':  return <AdminSharedDashboards />;
      case 'system-health':      return <SystemHealthView />;
      case 'business-profile':   return <BusinessProfileView />;
      case 'financials':         return <FinancialsView initialFilter={pendingLedgerFilter} onFilterConsumed={() => setPendingLedgerFilter(null)} onNavigateToPaymentSetup={() => setActiveView('payment-setup')} />;
      case 'partners':           return <PartnersView onNavigateToTaxCenter={navigateToTaxCenter} />;
      case 'workflow-setup':     return <WorkflowSetupView />;
      case 'security':           return <SecurityPage />;
      case 'help':               return <AdminHelp initialSlug={pendingHelpSlug} returnView={helpReturnView} onBack={backFromHelp} />;
      default:                   return <AdminOverview setActiveView={setActiveView} />;
    }
  }

  const { overall } = useSystemHealth();
  const navStatus = overall && overall !== 'healthy' ? { 'system-health': overall } : null;

  return (
    <div className="app-layout">
      <Sidebar navItems={NAV} activeView={activeView} setActiveView={goToView} statusDots={navStatus} />
      <main className="main-content" id="main-content">
        <HealthBeacon onOpen={() => setActiveView('system-health')} />
        <ErrorBoundary key={activeView} sectionName={(NAV.flatMap(g => g.items).find(i => i.view === activeView) || {}).label}>
          {renderView()}
        </ErrorBoundary>
      </main>
    </div>
  );
}
