/**
 * components/admin/RewardsView.js: thin admin wrapper around components/shared/RewardsPage.
 *
 * Passes isAdmin=true, profileId=null, the ledger cross-link callback, and the
 * deep-link target (pendingEntryId) a ledger line uses to open a reward entry.
 * All logic lives in RewardsPage. Pass-through by design.
 */
import RewardsPage from '../shared/RewardsPage';

export default function RewardsView({ onNavigateToLedger, pendingEntryId, onConsumed }) {
  return <RewardsPage isAdmin={true} profileId={null} onNavigateToLedger={onNavigateToLedger} pendingEntryId={pendingEntryId} onConsumed={onConsumed} />;
}
