import Refreshing from '../shared/Refreshing';

/** Reject avatars below AVATAR_MIN_PX on either side before upload. */
function checkImageDimensions(file) {
  return new Promise((resolve, reject) => {
    const url = URL.createObjectURL(file);
    const img = new window.Image();
    img.onload = () => {
      URL.revokeObjectURL(url);
      if (img.naturalWidth < AVATAR_MIN_PX || img.naturalHeight < AVATAR_MIN_PX) {
        reject(new Error(`Must be at least ${AVATAR_MIN_PX}×${AVATAR_MIN_PX}px (got ${img.naturalWidth}×${img.naturalHeight}px).`));
      } else {
        resolve();
      }
    };
    img.onerror = () => { URL.revokeObjectURL(url); reject(new Error('Could not read image.')); };
    img.src = url;
  });
}

/**
 * @param {string} [props.pendingUserId] - open this person's edit modal on mount.
 *        Dispatched via nys:open-user by the Tax Center Estimate tab.
 * @param {Function} [props.onConsumed] - called once the deep link is applied.
 */
export default function UsersView({ pendingUserId, onConsumed } = {}) {
  const toast = useToast();
  const { user: currentUser, fetchProfile } = useAuth();
  const [users, setUsers]                   = useState([]);
  const [platformAccounts, setPlatformAccounts] = useState([]);
  const { loading, refreshing, begin, end } = useLoadState();
  // The third state. This list is the whole Creator Setup screen, and it sits beside an Add
  // button: a refused read rendered an empty roster and an invitation to re-create people who
  // are already there.
  const [loadError, setLoadError]           = useState(null);
  const [editingUser, setEditingUser]       = useState(null);
  const [lightboxUrl, setLightboxUrl]       = useState(null);
  const [avatarState, setAvatarState]       = useState({});   // { [userId]: { uploading, error } }
  const fileInputRef                        = useRef(null);
  const pendingUserRef                      = useRef(null);

  useEffect(() => { fetchUsers(); }, []);

  // Apply a nys:open-user deep link once the list has loaded. Guarded by
  // onConsumed so navigating away and back does not reopen the modal.
  useEffect(() => {
    if (!pendingUserId || !users.length) return;
    const target = users.find(u => u.id === pendingUserId);
    if (target) setEditingUser(target);
    if (onConsumed) onConsumed();
  }, [pendingUserId, users, onConsumed]);

  async function fetchUsers() {
    begin();
    setLoadError(null);
    // Inline fetch (not useCreators): this view lists BOTH admins and creators, so no role filter.
    const [uRes, aRes] = await Promise.all([
      // @security date_of_birth is deliberately NOT here. Selecting it reads every person's
      //           date of birth including the minor's, for a list that renders none of them:
      //           the one reader is the Edit User modal, which fetches it for the single user
      //           it is editing. @see EditUserModal
      supabase.from('profiles').select('id, email, full_name, role, creator_name, idle_timeout_minutes, last_login_at, avatar_url, partner_allocation_pct, spouse_profile_id, agency_bio').order('full_name'),
      supabase.from('platform_accounts').select('profile_id, platform').eq('is_active', true),
    ]);
    if (uRes.error || aRes.error) {
      setLoadError(uRes.error || aRes.error);
      setUsers([]);
      setPlatformAccounts([]);
      end();
      return;
    }
    setUsers(uRes.data || []);
    setPlatformAccounts(aRes.data || []);
    end();
  }

  function platformsForUser(userId) {
    return [...new Set(
      platformAccounts.filter(a => a.profile_id === userId).map(a => a.platform)
    )];
  }

  function setUserAvatarState(userId, patch) {
    setAvatarState(prev => ({ ...prev, [userId]: { ...(prev[userId] || {}), ...patch } }));
  }

  /**
   * @security THIS SENDS NO LINK, and it cannot. The hub runs the PKCE auth flow, so
   *           a reset link is redeemable only in the browser that generated the code verifier,
   *           which is the browser that CALLED resetPasswordForEmail. An admin sending one to
   *           somebody else produces a link that person can never open. That is not a
   *           limitation to work around, it is the property being bought: under the previous
   *           implicit flow the emailed link carried the tokens themselves and worked for
   *           anyone who read the message. Self-service Forgot password is the path that both
   *           works and is bound to the right person. @see lib/supabase.js, pages/LoginPage.js
   */
  function handleResetPassword(user) {
    toast.info({
      title: 'They reset it themselves',
      body: `Ask ${user.full_name || user.email} to open the hub sign-in page and use "Forgot password". A reset link only opens in the browser that asked for it, so one sent from here would not work for them.`,
    });
  }

  async function handleAvatarFile(file, user) {
    setUserAvatarState(user.id, { error: null, uploading: true });

    const sizeErr = await validateUploadFile(file, {
      maxMB: AVATAR_MAX_KB / 1024,
      allowedTypes: AVATAR_ALLOWED_TYPES,
    });
    if (sizeErr) {
      setUserAvatarState(user.id, { uploading: false, error: sizeErr });
      return;
    }

    try {
      await checkImageDimensions(file);
    } catch (e) {
      setUserAvatarState(user.id, { uploading: false, error: e.message });
      return;
    }

    const { error: uploadErr } = await supabase.storage
      .from('creator-avatars')
      .upload(user.id, file, { upsert: true, contentType: file.type });

    if (uploadErr) {
      setUserAvatarState(user.id, { uploading: false, error: uploadErr.message });
      return;
    }

    const { data: urlData } = supabase.storage.from('creator-avatars').getPublicUrl(user.id);
    const publicUrl = urlData.publicUrl + '?v=' + Date.now();

    const { error } = await mutate(supabase.from('profiles').update({ avatar_url: publicUrl }).eq('id', user.id));

    if (error) { toast.error(error); return; }

    setUserAvatarState(user.id, { uploading: false, error: null });
    fetchUsers();
  }

  function triggerFileInput(user) {
    pendingUserRef.current = user;
    fileInputRef.current.value = '';
    fileInputRef.current.click();
  }

  function onFileInputChange(e) {
    const file = e.target.files?.[0];
    const user = pendingUserRef.current;
    if (file && user) handleAvatarFile(file, user);
  }

  if (loading) return <div className="page"><Loading /></div>;
  if (loadError) return <div className="page"><ReadError error={loadError} onRetry={fetchUsers} /></div>;

  return (
    <div className="page">
      <div className="page-header">
        <div>
          <h1 className="page-title">CREATOR SETUP<HelpIcon slug="new-creator" /></h1>
          <div className="page-subtitle">Manage creator and admin accounts<Refreshing on={refreshing} /></div>
        </div>
      </div>

      <input
        ref={fileInputRef}
        type="file"
        aria-label="Choose a profile photo"
        accept="image/jpeg,image/png,image/webp"
        style={{ display: 'none' }}
        onChange={onFileInputChange}
      />

      <div className="table-wrap">
        <table className="pinned-actions" style={{ width: '100%' }}>
          <thead>
            <tr><th scope="col">Photo</th><th scope="col">Name</th><th scope="col">Email</th><th scope="col">Role</th><th scope="col">Creator Name</th><th scope="col">Platforms</th><th scope="col">Idle Timeout</th><th scope="col">Last Login</th><th scope="col"></th></tr>
          </thead>
          <tbody>
            {users.map(u => {
              const platforms = u.role === 'creator' ? platformsForUser(u.id) : [];
              const state     = avatarState[u.id] || {};
              return (
                <tr key={u.id}>
                  <td>
                    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 4 }}>
                      <AvatarThumb
                        url={u.avatar_url}
                        name={u.full_name}
                        onClick={() => u.avatar_url && setLightboxUrl(u.avatar_url)}
                      />
                      {u.role === 'creator' && (
                        <button
                          className="btn btn-ghost btn-sm"
                          style={{ fontSize: 10, padding: '1px 6px' }}
                          disabled={state.uploading}
                          onClick={() => triggerFileInput(u)}
                        >
                          {state.uploading ? '…' : 'Change'}
                        </button>
                      )}
                      {state.error && (
                        <div style={{ fontSize: 10, color: 'var(--red)', maxWidth: 60, textAlign: 'center', lineHeight: 1.3 }}>
                          {state.error}
                        </div>
                      )}
                    </div>
                  </td>
                  <td style={{ fontWeight: 500 }}>{u.full_name}</td>
                  <td style={{ color: 'var(--muted)', fontSize: 13 }}>{u.email}</td>
                  <td><span className={`badge ${u.role === 'admin' ? 'badge-orange' : 'badge-neutral'}`}>{u.role}</span></td>
                  <td>{u.creator_name || <span className="text-muted">—</span>}</td>
                  <td>
                    {platforms.length > 0 ? (
                      <div className="flex gap-8" style={{ flexWrap: 'wrap' }}>
                        {platforms.map(p => (
                          <span key={p} className="badge badge-neutral">
                            {p.toUpperCase()}
                          </span>
                        ))}
                      </div>
                    ) : (
                      <span className="text-muted">—</span>
                    )}
                  </td>
                  <td style={{ fontSize: 12, color: u.idle_timeout_minutes === 0 ? 'var(--muted)' : 'var(--white)' }}>
                    {u.idle_timeout_minutes === 0
                      ? 'Disabled'
                      : `${u.idle_timeout_minutes || DEFAULT_IDLE_MINUTES} min`}
                  </td>
                  <td style={{ fontSize: 12, color: u.last_login_at ? 'var(--white)' : 'var(--muted)' }}>
                    {u.last_login_at ? fmtDateTime(u.last_login_at) : '—'}
                  </td>
                  <td>
                    <div style={{ display: 'flex', gap: 6, alignItems: 'center' }}>
                      <button className="btn btn-ghost btn-sm" onClick={() => setEditingUser(u)}>Edit</button>
                      <button
                        className="btn btn-ghost btn-sm"
                        style={{ fontSize: 11, color: 'var(--muted)' }}
                        onClick={() => handleResetPassword(u)}
                      >
                        Reset password
                      </button>
                    </div>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      <div className="card mt-20" style={{ maxWidth: 520 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 14 }}>
          <svg width="16" height="16" viewBox="0 0 16 16" fill="none" style={{ color: 'var(--blue)', flexShrink: 0 }}>
            <circle cx="8" cy="8" r="7" stroke="currentColor" strokeWidth="1.5" />
            <path d="M8 7v5M8 5.5v.5" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
          </svg>
          <div style={{ fontSize: 9, fontWeight: 600, textTransform: 'uppercase', letterSpacing: 2, color: 'var(--muted)' }}>How to add users</div>
        </div>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
          {[
            <>Go to <strong>Supabase</strong> → Authentication → Users → <strong>Invite User</strong> and enter their email.</>,
            <>Once they accept and sign up, open the <code style={{ background: 'var(--surface3)', padding: '1px 6px', borderRadius: 3, fontSize: 12 }}>profiles</code> table and find their row.</>,
            <>Set <code style={{ background: 'var(--surface3)', padding: '1px 6px', borderRadius: 3, fontSize: 12 }}>role = 'creator'</code> and <code style={{ background: 'var(--surface3)', padding: '1px 6px', borderRadius: 3, fontSize: 12 }}>creator_name</code> to their display name.</>,
            <>They will log in and see only their own campaigns and payouts.</>,
          ].map((step, i) => (
            <div key={i} style={{ display: 'flex', gap: 12, alignItems: 'flex-start' }}>
              <div style={{ width: 20, height: 20, borderRadius: '50%', background: 'var(--surface3)', border: '1px solid var(--border)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 10, fontWeight: 700, color: 'var(--muted)', flexShrink: 0, marginTop: 1 }}>{i + 1}</div>
              <div style={{ fontSize: 13, color: 'var(--muted)', lineHeight: 1.6 }}>{step}</div>
            </div>
          ))}
        </div>
      </div>

      {lightboxUrl && (
        <AvatarLightbox url={lightboxUrl} onClose={() => setLightboxUrl(null)} />
      )}

      {editingUser && (
        <EditUserModal
          user={editingUser}
          allUsers={users}
          onClose={() => setEditingUser(null)}
          onSaved={() => {
            if (editingUser.id === currentUser?.id) fetchProfile();
            setEditingUser(null);
            fetchUsers();
          }}
        />
      )}
    </div>
  );
}

function AvatarLightbox({ url, onClose }) {
  const { overlayRef, dialogRef } = useModalA11y(onClose);
  const imgRef                    = useRef(null);
  const [overlay, setOverlay]     = useState(null);

  const onImgLoad = useCallback(() => {
    const el = imgRef.current;
    if (!el) return;
    const nw = el.naturalWidth;
    const nh = el.naturalHeight;
    const rw = el.offsetWidth;
    const rh = el.offsetHeight;
    const scale = rw / nw;

    // Simulate object-fit:cover object-position:top center in a 1:1 container
    let cropX, cropY, cropSize;
    if (nh >= nw) {
      // Portrait/square: full width, anchored to top
      cropSize = nw;
      cropX    = 0;
      cropY    = 0;
    } else {
      // Landscape: full height, centered horizontally
      cropSize = nh;
      cropX    = (nw - nh) / 2;
      cropY    = 0;
    }

    const rs = cropSize * scale;
    const rx = cropX    * scale;
    const ry = cropY    * scale;
    setOverlay({ cx: rx + rs / 2, cy: ry + rs / 2, r: rs / 2, w: rw, h: rh });
  }, []);

  return (
    // The ONE overlay in the hub that closes on a backdrop click, and it is not
    // an exception to the app-wide rule: that rule exists because a mousedown
    // inside a FORM releasing on the overlay discarded work. This is a lightbox
    // over an image; there is nothing to lose. It carries its own Escape rather
    // than relying on a global handler that closed modals by synthetically
    // clicking them, which is why that handler could be deleted.
    <div
      ref={overlayRef}
      className="modal-overlay"
      onClick={onClose}
      style={{ zIndex: 1100, flexDirection: 'column', gap: 12 }}
    >
      <div
        ref={dialogRef}
        role="dialog"
        aria-modal="true"
        aria-label="Creator photo, full size"
        tabIndex={-1}
        style={{ position: 'relative', display: 'inline-block' }}
        onClick={e => e.stopPropagation()}
      >
        <img
          ref={imgRef}
          src={url}
          alt="Creator"
          onLoad={onImgLoad}
          style={{ maxWidth: '70vw', maxHeight: '72vh', display: 'block', borderRadius: 4 }}
        />
        {overlay && (
          <svg
            style={{ position: 'absolute', top: 0, left: 0, pointerEvents: 'none' }}
            width={overlay.w}
            height={overlay.h}
          >
            <defs>
              <mask id="avatar-crop-mask">
                <rect width="100%" height="100%" fill="white" />
                <circle cx={overlay.cx} cy={overlay.cy} r={overlay.r} fill="black" />
              </mask>
            </defs>
            <rect width="100%" height="100%" fill="rgba(0,0,0,0.58)" mask="url(#avatar-crop-mask)" />
            <circle cx={overlay.cx} cy={overlay.cy} r={overlay.r} fill="none" stroke="var(--orange)" strokeWidth="2" strokeDasharray="6 3" />
          </svg>
        )}
        <div style={{ position: 'absolute', bottom: 12, right: 12, textAlign: 'center' }}>
          <div style={{ width: 64, height: 64, borderRadius: '50%', overflow: 'hidden', border: '2.5px solid var(--orange)', boxShadow: 'var(--shadow-sm)' }}>
            <img src={url} alt="preview" style={{ width: '100%', height: '100%', objectFit: 'cover', objectPosition: 'top center' }} />
          </div>
          <div style={{ fontSize: 9, color: 'rgba(255,255,255,0.45)', marginTop: 4, textTransform: 'uppercase', letterSpacing: 1 }}>On site</div>
        </div>
      </div>
      <div style={{ fontSize: 11, color: 'rgba(255,255,255,0.35)', textTransform: 'uppercase', letterSpacing: 1 }}>Click anywhere to close</div>
    </div>
  );
}

function AvatarThumb({ url, name, onClick }) {
  const initial = (name || '?').charAt(0).toUpperCase();
  const style = {
    width: 40, height: 40, borderRadius: '50%',
    border: '1.5px solid var(--border)',
    display: 'flex', alignItems: 'center', justifyContent: 'center',
    flexShrink: 0, overflow: 'hidden',
    cursor: url ? 'pointer' : 'default',
    background: 'var(--surface3)',
  };
  if (url) {
    return (
      <button type="button" className="thumb-btn" style={style} onClick={onClick} aria-label={`View ${name}'s photo full size`}>
        <img src={url} alt={name} style={{ width: '100%', height: '100%', objectFit: 'cover', objectPosition: 'top center' }} />
      </button>
    );
  }
  return (
    <div style={style}>
      <span style={{ fontSize: 16, fontWeight: 700, color: 'var(--muted)' }}>{initial}</span>
    </div>
  );
}

/**
 * The one bound on the idle window, as a rule the hook can read.
 *
 * @gotcha `max` on a number input only ADVISES: it fails constraint validation and nothing
 *         else, so 481 to 999 reached the write, and `profiles.idle_timeout_minutes` carries
 *         no CHECK to catch it. This is the only bound there is.
 */
const IDLE_RULES = {
  minutes: {
    required: true,
    number: true,
    min: 1,
    max: IDLE_MINUTES_MAX,
    custom: (val) => (/^\d+$/.test(String(val).trim()) ? null : 'whole numbers only'),
    message: `Enter a whole number of minutes from 1 to ${IDLE_MINUTES_MAX}.`,
  },
};

function EditUserModal({ user, allUsers = [], onClose, onSaved }) {
  const toast = useToast();
  // @security null means "nobody configured this", which useIdleTimeout now reads as
  //           DEFAULT_IDLE_MINUTES rather than as off. So the checkbox starts CHECKED on a
  //           never-configured account, matching what that account actually does, and
  //           turning it off writes 0. Writing null for off would put the account back on the
  //           default and silently undo the admin. @see hooks/useIdleTimeout.js
  const [enabled, setEnabled] = useState(user.idle_timeout_minutes !== 0);
  // The RAW string, not a number. Clamping inside onChange made the box uneditable: clearing
  // it to retype a two-digit number snapped it to 1 on the first keystroke, so the only way to
  // reach 45 was to select-all and type over.
  const [minutes, setMinutes] = useState(String(user.idle_timeout_minutes || DEFAULT_IDLE_MINUTES));
  const v = useFormValidation(IDLE_RULES);
  // Fetched here rather than carried on the list row, so the date of birth of everyone but the
  // person being edited is never read. @see fetchUsers. Null until it arrives, which is why
  // the field is disabled while dobLoading.
  const [dob, setDob]           = useState('');
  const [dobLoading, setDobLoading] = useState(true);
  const [spouseId, setSpouseId] = useState(user.spouse_profile_id || '');
  const [bio, setBio]         = useState(user.agency_bio || '');
  const [saving, setSaving]   = useState(false);

  /** The typed minutes as a number, or null when they are not a usable value. */
  const validMinutes = () => (v.validateField('minutes', minutes) ? null : parseInt(minutes, 10));

  // On BLUR, the shape RateCardEditor's commitQty uses: a half-typed number is not yet a value,
  // so nothing judges it until the field is left. A refusal restores the stored value rather
  // than inventing one, and reports through the hook so the message carries an id the field
  // points at.
  const commitMinutes = () => {
    const msg = v.validateField('minutes', minutes);
    if (msg) {
      setMinutes(String(user.idle_timeout_minutes || DEFAULT_IDLE_MINUTES));
      v.setErrors((e) => ({ ...e, minutes: msg }));
      return;
    }
    v.clear('minutes');
  };

  // Only creators appear on a shared agency dashboard, so only they have a bio
  // to write. Shown for creators only rather than for everyone, because an empty
  // field an admin can never use is the "earn every pixel" rule broken.
  const showBio = user.role === 'creator';

  // Tax ID section shows for anyone whose tax ID feeds a return:
  // creators (1099-NEC) and partners (K-1).
  const showTaxId =
    user.role === 'creator' ||
    (user.role === 'admin' && user.partner_allocation_pct != null);

  /**
   * @security the ONE date of birth this admin is about to edit, read at the moment they open
   *           the modal. The list behind this modal deliberately does not carry the column.
   * @gotcha a refused or failed read leaves dobLoading true rather than falling through to an
   *         empty field, because an empty field here saves NULL over a real date of birth and
   *         the tax estimate then silently stops applying the dependent deduction.
   */
  useEffect(() => {
    let alive = true;
    supabase.from('profiles').select('date_of_birth').eq('id', user.id).maybeSingle()
      .then(({ data, error }) => {
        if (!alive || error) return;
        setDob(data?.date_of_birth || '');
        setDobLoading(false);
      });
    return () => { alive = false; };
  }, [user.id]);

  /**
   * @gotcha the joint-return link is written on BOTH profiles, and any previous
   *         partner on either side is cleared first. A one-sided link would make
   *         the estimate collapse the pair from one direction and not the other,
   *         so the same couple would read as one taxpayer or two depending on
   *         whose row you looked at. A partial unique index rejects a third link.
   */
  async function save() {
    // Save can be reached without the field ever blurring, so the same bound runs again here
    // rather than trusting that it did.
    if (enabled && validMinutes() == null) { commitMinutes(); return; }
    setSaving(true);
    const prior = user.spouse_profile_id || null;

    const { error } = await supabase
      .from('profiles')
      .update({
        idle_timeout_minutes: enabled ? validMinutes() : 0,
        // Omitted entirely until the read lands. Sending `dob || null` while dobLoading is
        // true writes NULL over a real date of birth, which reads as an ordinary save and
        // silently drops the dependent deduction on that person's tax estimate.
        ...(dobLoading ? {} : { date_of_birth: dob || null }),
        spouse_profile_id: spouseId || null,
        // A blank bio is stored as NULL, not '', so the agency hero has one
        // absent case to test rather than two.
        ...(showBio ? { agency_bio: bio.trim() || null } : {}),
      })
      .eq('id', user.id);

    if (!error && (spouseId || null) !== prior) {
      // Detach whoever was linked before, on either side, then link both ways.
      const detach = [prior, spouseId].filter(Boolean);
      for (const id of detach) {
        await supabase.from('profiles').update({ spouse_profile_id: null })
          .eq('spouse_profile_id', id).neq('id', user.id);
      }
      if (prior) await supabase.from('profiles').update({ spouse_profile_id: null }).eq('id', prior);
      if (spouseId) await supabase.from('profiles').update({ spouse_profile_id: user.id }).eq('id', spouseId);
    }

    setSaving(false);
    if (error) {
      const h = humanizeError(error);
      toast.error({ title: h?.title || 'Could not save', body: h?.body });
      return;
    }
    toast.success('Creator saved');
    onSaved();
  }

  return (
    <Modal
      title={<>EDIT USER: {(user.full_name || '').toUpperCase()}</>}
      size="md"
      onClose={onClose}
    >
        <div className="modal-body">
          {/* The bio leads the modal because it is the one field here that is
              about who this person is rather than about how the app treats
              them, and it is the only one an agency ever reads. It saves with
              the modal rather than owning a button: agency_bio is a profiles
              column like date_of_birth, unlike the three sections below, which
              write other tables through their own RPCs. */}
          {showBio && (
            <div className="form-group">
              <label className="form-label" htmlFor="agency-bio">Agency bio</label>
              <textarea
                id="agency-bio"
                className="form-input form-textarea"
                value={bio}
                maxLength={AGENCY_BIO_MAX}
                rows={4}
                placeholder="Two or three sentences an agency reads first."
                onChange={e => setBio(e.target.value)}
              />
              <div style={{ display: 'flex', justifyContent: 'space-between', gap: 12, marginTop: 6 }}>
                <div style={{ fontSize: 11, color: 'var(--muted)' }}>
                  Shown under the name on every shared agency dashboard. Leave empty to show none.
                </div>
                {/* The counter earns its place only near the limit. A permanent
                    0/500 is chrome on a field that is normally 200 characters. */}
                {bio.length >= AGENCY_BIO_MAX * 0.8 && (
                  <div style={{
                    fontSize: 11,
                    whiteSpace: 'nowrap',
                    color: bio.length >= AGENCY_BIO_MAX * 0.96 ? 'var(--orange2)' : 'var(--muted)',
                  }}>
                    {bio.length} / {AGENCY_BIO_MAX}
                  </div>
                )}
              </div>
            </div>
          )}
          <div className="form-group">
            <label style={{ display: 'flex', alignItems: 'center', minHeight: 24, gap: 10, cursor: 'pointer', userSelect: 'none' }}>
              <input type="checkbox" checked={enabled} onChange={e => setEnabled(e.target.checked)} />
              <span style={{ fontSize: 13 }}>Enable idle timeout</span>
            </label>
            <div style={{ fontSize: 11, color: 'var(--dim)', marginTop: 6 }}>
              Disable for your own account during development.
            </div>
          </div>
          {enabled && (
            <Field label="Timeout (minutes)">{(id) => (<>
              <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                <input id={id}
                  className="form-input"
                  type="number"
                  min={1}
                  max={IDLE_MINUTES_MAX}
                  value={minutes}
                  {...v.fieldProps('minutes')}
                  onChange={e => { setMinutes(e.target.value); v.clear('minutes'); }}
                  onBlur={commitMinutes}
                  style={{ width: 90 }}
                />
                <span style={{ fontSize: 12, color: 'var(--muted)' }}>
                  60s warning before sign-out
                </span>
              </div>
              {v.errors.minutes && <div {...v.errorProps('minutes')}>{v.errors.minutes}</div>}
            </>)}</Field>
          )}
          {/* Birthday drives the dependent standard deduction in the tax
              estimate (age at Dec 31). Admin-only: the profiles self-update
              policy reverts any change a creator makes to their own row. */}
          <Field label="Birthday">{(id) => (<>
            <input id={id}
              className="form-input"
              type="date"
              value={dob}
              min={DOB_DATE_MIN}
              max={DOB_DATE_MAX}
              disabled={dobLoading}
              onChange={e => setDob(e.target.value)}
              style={{ width: 190 }}
            />
            <div style={{ fontSize: 11, color: 'var(--muted)', marginTop: 6 }}>
              Used by the tax estimate: under 18 at year end means a smaller standard deduction.
            </div>
          </>)}</Field>
          {showTaxId && (
            <>
              {/* Two people on one joint return are one taxpayer for income tax.
                  The estimate collapses a linked pair into a single row so the
                  outside income and standard deduction are not counted twice. */}
              <Field label="FILES JOINTLY WITH">{(id) => (<>
                <select id={id}
                  className="form-input"
                  value={spouseId}
                  onChange={e => setSpouseId(e.target.value)}
                  style={{ maxWidth: 280 }}
                >
                  <option value="">Nobody, files their own return</option>
                  {allUsers
                    .filter(u => u.id !== user.id)
                    .filter(u => !u.spouse_profile_id || u.spouse_profile_id === user.id)
                    .map(u => (
                      <option key={u.id} value={u.id}>{u.full_name}</option>
                    ))}
                </select>
                <div style={{ fontSize: 11, color: 'var(--muted)', marginTop: 6 }}>
                  Only for two people here who file one return together. The tax estimate
                  then shows them as a single taxpayer.
                </div>
              </>)}</Field>
              <TaxIdSection profileId={user.id} />
              <TaxBasisSection
                profileId={user.id}
                spouseId={spouseId || null}
                spouseName={allUsers.find(u => u.id === spouseId)?.full_name || null}
              />
            </>
          )}
          {/* A mailbox is the same kind of once-per-person credential as the tax
              ID above it, so it lives in the same modal. Not gated on showTaxId:
              a mailbox is useful for anyone here, not only people who get a
              1099 or a K-1. */}
          <MailboxSection profileId={user.id} profileName={user.full_name} />
        </div>
        <div className="modal-footer">
          <ModalClose className="btn btn-ghost">Cancel</ModalClose>
          <SubmitButton saving={saving} className="btn btn-primary" onClick={save} disabled={saving}>Save</SubmitButton>
        </div>
    </Modal>
  );
}

// ── TaxIdSection ────────────────────────────────────────────────────────────
// Vault-backed SSN/TIN editor. Default state is the masked last4. Reveal
// fetches plaintext via SECURITY DEFINER RPC for 30 seconds, then auto
// re-masks. Each set / view / remove writes to pii_access_log. The
// "Last viewed" line surfaces that log in-place so the audit trail is felt,
// not buried.
const REVEAL_SECONDS = 30;

function formatTaxIdMask(value) {
  // Accept anything; render as `XXX-XX-XXXX` to the extent we have digits.
  const d = String(value || '').replace(/\D/g, '').slice(0, 9);
  if (d.length <= 3) return d;
  if (d.length <= 5) return `${d.slice(0, 3)}-${d.slice(3)}`;
  return `${d.slice(0, 3)}-${d.slice(3, 5)}-${d.slice(5)}`;
}

/**
 * Per-user tax ID (SSN/TIN) panel: shows masked last4, reveals the full value for
 * REVEAL_SECONDS, and edits/clears it. Every read/write goes through the vault RPCs.
 *
 * @security The revealed cleartext is held in local state only for the countdown
 *           window, then cleared; the value is never persisted client-side.
 */
function TaxIdSection({ profileId }) {
  const askConfirm = useConfirm();
  const toast = useToast();

  // status: 'loading' | 'read_failed' | 'missing' | 'on_file' | 'revealed' | 'editing'
  const [status,  setStatus]  = useState('loading');
  const [readErr, setReadErr] = useState(null);
  const [last4,   setLast4]   = useState(null);
  const [lastViewedAt, setLastViewedAt] = useState(null);
  const [revealed, setRevealed] = useState('');
  const [remaining, setRemaining] = useState(0);
  const [editValue, setEditValue] = useState('');
  const [busy, setBusy] = useState(false);

  const refresh = useCallback(async () => {
    // `viewRes` is deliberately best-effort and `taxRes` is not: the audit stamp is a footnote
    // under a value that reports for itself below, so without it the panel omits one "Last
    // viewed" line and claims nothing.
    const [taxRes, viewRes] = await Promise.all([
      supabase.from('profile_tax_ids').select('last4').eq('profile_id', profileId).maybeSingle(),
      supabase.from('pii_access_log')
        .select('created_at')
        .eq('profile_id', profileId)
        .eq('event_type', 'tax_id_viewed')
        .order('created_at', { ascending: false })
        .limit(1)
        .maybeSingle(),
    ]);
    // 'missing' is a claim, and the button under it ROTATES THE VAULT SECRET: saving over a
    // tax ID that is on file destroys the old one. A refused read leaves data null, which is
    // indistinguishable from nothing on file, so it gets its own state.
    if (taxRes.error) {
      setReadErr(taxRes.error);
      setLast4(null);
      setStatus('read_failed');
      return;
    }
    setReadErr(null);
    if (taxRes.data) {
      setLast4(taxRes.data.last4);
      setStatus('on_file');
    } else {
      setLast4(null);
      setStatus('missing');
    }
    // The audit stamp is a footnote under a value that already read, so it reports nothing of
    // its own: without it the panel simply omits the "Last viewed" line.
    setLastViewedAt(viewRes.data?.created_at || null);
  }, [profileId]);

  useEffect(() => { refresh(); }, [refresh]);

  // Countdown effect for revealed state.
  useEffect(() => {
    if (status !== 'revealed') return undefined;
    if (remaining <= 0) { setRevealed(''); setStatus('on_file'); return undefined; }
    const t = setTimeout(() => setRemaining((s) => s - 1), 1000);
    return () => clearTimeout(t);
  }, [status, remaining]);

  async function onReveal() {
    setBusy(true);
    const { data, error } = await supabase.rpc('get_profile_tax_id', { p_profile_id: profileId });
    setBusy(false);
    if (error) { toast.error({ title: 'Could not reveal', body: humanizeError(error)?.body }); return; }
    setRevealed(data);
    setRemaining(REVEAL_SECONDS);
    setStatus('revealed');
    setLastViewedAt(new Date().toISOString());
  }

  function onStartEdit() {
    setEditValue('');
    setRevealed('');
    setStatus('editing');
  }

  function onCancelEdit() {
    setEditValue('');
    setStatus(last4 ? 'on_file' : 'missing');
  }

  async function onSave() {
    const digits = editValue.replace(/\D/g, '');
    if (digits.length !== 9) {
      toast.error({ title: 'Invalid tax ID', body: 'Enter exactly 9 digits.' });
      return;
    }
    setBusy(true);
    const { error } = await supabase.rpc('set_profile_tax_id', { p_profile_id: profileId, p_tax_id: digits });
    if (error) { setBusy(false); toast.error({ title: 'Could not save', body: humanizeError(error)?.body }); return; }
    setEditValue('');
    toast.success(last4 ? 'Tax ID updated' : 'Tax ID saved');
    await refresh();
    setBusy(false);
  }

  async function onRemove() {
    const ok = await askConfirm({
      title: 'Remove tax ID?',
      body: 'The encrypted secret is destroyed. You will need to enter it again to issue a 1099-NEC or K-1.',
      confirmLabel: 'Remove',
      danger: true,
      requireTyped: 'REMOVE',
    });
    if (!ok) return;
    setBusy(true);
    const { error } = await supabase.rpc('delete_profile_tax_id', { p_profile_id: profileId });
    if (error) { setBusy(false); toast.error({ title: 'Could not remove', body: humanizeError(error)?.body }); return; }
    toast.success('Tax ID removed');
    await refresh();
    setBusy(false);
  }

  return (
    <div className="form-group" style={{ marginTop: 18, paddingTop: 16, borderTop: '1px solid var(--border)' }}>
      <div style={{ display: 'flex', alignItems: 'baseline', justifyContent: 'space-between', marginBottom: 8 }}>
        <div className="form-label" style={{ margin: 0 }}>TAX ID</div>
        {status === 'on_file' && (
          <div style={{ display: 'flex', gap: 4 }}>
            <button className="btn btn-ghost btn-sm" disabled={busy} onClick={onReveal}>Reveal</button>
            <button className="btn btn-ghost btn-sm" disabled={busy} onClick={onStartEdit}>Edit</button>
            <button className="btn btn-ghost btn-sm" disabled={busy} onClick={onRemove}>Remove</button>
          </div>
        )}
        {status === 'revealed' && (
          <button className="btn btn-ghost btn-sm" onClick={() => { setRevealed(''); setRemaining(0); setStatus('on_file'); }}>
            Re-mask · {remaining}s
          </button>
        )}
        {status === 'editing' && (
          <button className="btn btn-ghost btn-sm" disabled={busy} onClick={onCancelEdit}>Cancel</button>
        )}
      </div>

      {status === 'loading' && <Loading style={{ fontSize: 12 }} />}

      {status === 'read_failed' && <ReadError error={readErr} onRetry={refresh} />}

      {status === 'missing' && (
        <div>
          <div style={{ fontSize: 13, color: 'var(--muted)', marginBottom: 10 }}>
            No tax ID on file. Required to issue a 1099-NEC or K-1.
          </div>
          <button className="btn btn-primary btn-sm" onClick={onStartEdit}>+ Add tax ID</button>
        </div>
      )}

      {status === 'on_file' && (
        <div>
          <div style={{
            fontFamily: 'var(--font-mono)',
            fontSize: 18, letterSpacing: 2, color: 'var(--muted)',
          }}>
            • • •  • •  {last4}
          </div>
          {lastViewedAt && (
            <div style={{ fontSize: 11, color: 'var(--dim)', marginTop: 8 }}>
              Last viewed {fmtDateTime(lastViewedAt)}
            </div>
          )}
        </div>
      )}

      {status === 'revealed' && (
        <div>
          <div style={{
            fontFamily: 'var(--font-mono)',
            fontSize: 18, letterSpacing: 2, color: 'var(--white)',
            fontWeight: 500,
          }}>
            {revealed}
          </div>
          <div style={{ fontSize: 11, color: 'var(--orange)', marginTop: 8 }}>
            being viewed · audit logged
          </div>
        </div>
      )}

      {status === 'editing' && (
        <div>
          <input
            className="form-input"
            type="text"
            inputMode="numeric"
            autoComplete="off"
            aria-label="Tax ID"
            placeholder="123-45-6789"
            value={editValue}
            maxLength={11}
            onChange={(e) => setEditValue(formatTaxIdMask(e.target.value))}
            style={{
              fontFamily: 'var(--font-mono)',
              letterSpacing: 2,
            }}
            autoFocus
          />
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: 10 }}>
            <div style={{ fontSize: 11, color: 'var(--muted)' }}>
              9 digits, encrypted at rest in vault
            </div>
            <SubmitButton saving={busy} className="btn btn-primary btn-sm" disabled={busy || editValue.replace(/\D/g, '').length !== 9} onClick={onSave}>Save</SubmitButton>
          </div>
        </div>
      )}
    </div>
  );
}

// ── TaxBasisSection ─────────────────────────────────────────────────────────
// Figures transcribed off a person's last filed federal return. Annual,
// once-per-person data, so it lives here with the birthday and the tax ID
// rather than inside the Tax Center report it feeds. The Estimate tab reads
// these and never writes them.
//
// @see utils/tax-estimate.js, docs/MONEY.md §10.1

/**
 * The only two figures the estimate needs, with their Form 1040 lines.
 *
 * @gotcha deliberately NOT total tax or withholding. The estimate reports only
 *         the tax the Nysterys income causes, so the rest of someone's return is
 *         none of its business; asking for those numbers implied it was
 *         predicting their whole bill. The columns still exist on
 *         profile_tax_basis, unused.
 */
const RETURN_FIELDS = [
  ['agi',   'Adjusted gross income', 'line 11 . finds the tax rate'],
  ['wages', 'Wages',                 'line 1z . Social Security base'],
];

const emptyBasisForm = (year) => ({
  tax_year: String(year), filing_status: 'single', agi: '', wages: '',
});

/**
 * Per-user "Last filed return" panel. Mirrors TaxIdSection's shape: a summary
 * when figures are on file, a single action when they are not, never a wall of
 * blank inputs.
 *
 * @gotcha tax_year is the year the RETURN covers, not the year being estimated.
 *         Upsert is keyed on (profile_id, tax_year), so entering a new year adds
 *         a row rather than overwriting last year's.
 */
function TaxBasisSection({ profileId, spouseId = null, spouseName = null }) {
  const toast = useToast();
  const lastFiledYear = new Date().getFullYear() - 1;

  // status: 'loading' | 'read_failed' | 'missing' | 'on_file' | 'editing'
  const [status, setStatus] = useState('loading');
  const [readErr, setReadErr] = useState(null);
  const [basis,  setBasis]  = useState(null);   // the return: own row, else the spouse's
  const [myWages, setMyWages] = useState(0);    // always this person's own line 1z
  const [fromSpouse, setFromSpouse] = useState(false);
  const [form,   setForm]   = useState(() => emptyBasisForm(lastFiledYear));
  const [busy,   setBusy]   = useState(false);

  const SELECT = 'id, tax_year, filing_status, agi, wages, total_tax, withholding';

  /**
   * @gotcha a linked couple has ONE return, so this falls back to the spouse's
   *         row when this person has none. Reading only the own row made the
   *         second person look like they had no return and offered to add a
   *         separate one, which cannot exist.
   */
  const refresh = useCallback(async () => {
    const own = await supabase
      .from('profile_tax_basis').select(SELECT)
      .eq('profile_id', profileId)
      .order('tax_year', { ascending: false }).limit(1).maybeSingle();
    // Logging it and carrying on is what made this the admin twin of the creator's own set-aside
    // bug: "No return on file" and "+ Add return figures" then upsert agi 0, wages 0, filing
    // status single OVER figures transcribed off a filed federal return, and the estimate that
    // reads them is a real number a real person acts on. @see docs/MONEY.md 10.1
    if (own.error) { setReadErr(own.error); setBasis(null); setMyWages(0); setStatus('read_failed'); return; }

    setMyWages(own.data?.wages ?? 0);

    if (own.data) { setReadErr(null); setBasis(own.data); setFromSpouse(false); setStatus('on_file'); return; }

    if (spouseId) {
      const theirs = await supabase
        .from('profile_tax_basis').select(SELECT)
        .eq('profile_id', spouseId)
        .order('tax_year', { ascending: false }).limit(1).maybeSingle();
      // The spouse's row is the other half of the same claim: a couple has ONE return, so a
      // refused read here says "no return on file for this couple" just as loudly.
      if (theirs.error) { setReadErr(theirs.error); setBasis(null); setStatus('read_failed'); return; }
      if (theirs.data) { setReadErr(null); setBasis(theirs.data); setFromSpouse(true); setStatus('on_file'); return; }
    }

    setReadErr(null); setBasis(null); setFromSpouse(false); setStatus('missing');
  }, [profileId, spouseId]);

  useEffect(() => { refresh(); }, [refresh]);

  function onStartEdit() {
    setForm(basis ? {
      tax_year:      String(basis.tax_year),
      filing_status: basis.filing_status,
      agi:           String(basis.agi ?? ''),
      // Wages are personal even when the rest of the return is shared, so never
      // prefill them from the spouse's row.
      wages:         fromSpouse ? '' : String(basis.wages ?? ''),
    } : emptyBasisForm(lastFiledYear));
    setStatus('editing');
  }

  /**
   * @gotcha on a joint return the shared figures (filing status, AGI, total tax,
   *         withholding) are mirrored onto the spouse's row for the same year, so
   *         they are entered once and cannot drift apart. Wages are NOT mirrored:
   *         the Social Security wage base is individual even on a joint return,
   *         so each person keeps their own line 1z.
   */
  async function onSave() {
    const year = parseInt(form.tax_year, 10);
    if (!Number.isFinite(year) || year < 2020 || year > 2040) {
      toast.error({ title: 'Check the return year', body: 'Enter the year the return covers, for example 2025.' });
      return;
    }
    const shared = {
      tax_year:      year,
      filing_status: form.filing_status,
      agi:           parseFloat(form.agi) || 0,
    };
    setBusy(true);
    const { error } = await supabase.from('profile_tax_basis').upsert({
      profile_id: profileId,
      wages:      parseFloat(form.wages) || 0,
      ...shared,
    }, { onConflict: 'profile_id,tax_year' });

    // The joint half. filing_status, AGI and the year are shared by both spouses; WAGES
    // are not, since each person's own wages set their own Social Security base.
    //
    // @gotcha Both the read and the write are checked, and the read matters most:
    //         `theirs?.wages ?? 0` reads a FAILED lookup as "they earned nothing" and
    //         upserts a zero over a figure transcribed off a filed federal return, with no
    //         message. @see docs/MONEY.md 10.1
    let spouseErr = null;
    if (!error && spouseId) {
      const { data: theirs, error: readErr } = await supabase
        .from('profile_tax_basis')
        .select('wages')
        .eq('profile_id', spouseId).eq('tax_year', year).maybeSingle();
      // Destructured on its own line on purpose. The compressed `(await...).error` form
      // is equally correct and invisible to check-unchecked-writes.mjs, and code that
      // satisfies a gate by dodging its regex is worse than code that satisfies it.
      const { error: writeErr } = await supabase.from('profile_tax_basis').upsert({
        profile_id: spouseId,
        wages:      theirs?.wages ?? 0,
        ...shared,
      }, { onConflict: 'profile_id,tax_year' });
      spouseErr = readErr || writeErr;
    }

    // Lowered on each path AFTER that path's last await, never once up here: a flag that goes
    // down while the handler is still awaiting hands the control back mid-write.
    // @see src/__tests__/savingBeforeAwait.test.js
    if (!error && spouseErr) {
      // This person's row saved. Say exactly that, so nobody re-enters the whole form.
      const h = humanizeError(spouseErr);
      toast.error({ title: h?.title || "Saved, but the spouse's row did not",
        body: `${h?.body || ''} This person's figures were saved. Open the spouse and save theirs.`.trim() });
      await refresh();
      setBusy(false);
      return;
    }
    if (error) {
      const h = humanizeError(error);
      toast.error({ title: h?.title || 'Could not save', body: h?.body });
      setBusy(false);
      return;
    }
    toast.success(basis ? 'Return figures updated' : 'Return figures saved');
    await refresh();
    setBusy(false);
  }

  const set = (k) => (e) => setForm(f => ({ ...f, [k]: e.target.value }));
  const money = (v) => `$${(Number(v) || 0).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

  return (
    <div className="form-group" style={{ marginTop: 18, paddingTop: 16, borderTop: '1px solid var(--border)' }}>
      <div style={{ display: 'flex', alignItems: 'baseline', justifyContent: 'space-between', marginBottom: 8 }}>
        <div className="form-label" style={{ margin: 0 }}>
          {spouseName ? 'LAST FILED RETURN, JOINT' : 'LAST FILED RETURN'}
        </div>
        {status === 'on_file' && (
          <button className="btn btn-ghost btn-sm" disabled={busy} onClick={onStartEdit}>Edit</button>
        )}
        {status === 'editing' && (
          <button className="btn btn-ghost btn-sm" disabled={busy} onClick={() => setStatus(basis ? 'on_file' : 'missing')}>
            Cancel
          </button>
        )}
      </div>

      {status === 'loading' && <Loading style={{ fontSize: 12 }} />}

      {status === 'read_failed' && <ReadError error={readErr} onRetry={refresh} />}

      {status === 'missing' && (
        <div>
          <div style={{ fontSize: 13, color: 'var(--muted)', marginBottom: 10 }}>
            {spouseName
              ? 'No return on file for this couple. Without it the estimate assumes Nysterys is their only income, so it may use too low a tax rate.'
              : 'No return on file. Without it the estimate assumes Nysterys is their only income, so it may use too low a tax rate.'}
          </div>
          <button className="btn btn-primary btn-sm" onClick={onStartEdit}>+ Add return figures</button>
        </div>
      )}

      {status === 'on_file' && basis && (
        <div style={{ fontSize: 13, color: 'var(--muted)', lineHeight: 1.7, fontVariantNumeric: 'tabular-nums' }}>
          <div style={{ color: 'var(--white)' }}>
            {basis.tax_year} · {filingStatusLabel(basis.filing_status)}
            {spouseName ? `, filed with ${spouseName}` : ''}
          </div>
          <div>AGI {money(basis.agi)}</div>
          {/* Wages are the one figure that stays personal: the Social Security
              wage base is individual even on a joint return. */}
          <div>
            Wages, theirs: {myWages ? money(myWages) : <span style={{ color: 'var(--orange)' }}>not set</span>}
          </div>
          {spouseName && (
            <div style={{ fontSize: 11, marginTop: 6, lineHeight: 1.5 }}>
              One return, shared with {spouseName}. Editing here updates it for both of you.
            </div>
          )}
        </div>
      )}

      {status === 'editing' && (
        <div>
          <div style={{ fontSize: 12, color: 'var(--muted)', marginBottom: 12 }}>
            Two figures off the filed return. They only locate the tax rate the Nysterys
            income lands at; the rest of the return is not used and no tax on it is estimated.
            {spouseId ? ' AGI is shared with the other person on the return; wages are theirs alone.' : ''}
          </div>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(150px, 1fr))', gap: '12px 14px' }}>
            <label>
              <span className="form-label" style={{ display: 'block' }}>Return year</span>
              <input className="form-input" type="number" inputMode="numeric" min={2020} max={2040}
                     value={form.tax_year} onChange={set('tax_year')} />
            </label>
            <label>
              <span className="form-label" style={{ display: 'block' }}>Filing status</span>
              <select className="form-input" value={form.filing_status} onChange={set('filing_status')}>
                {FILING_STATUSES.map(f => (
                  <option key={f.value} value={f.value}>{f.label}</option>
                ))}
              </select>
            </label>
            {RETURN_FIELDS.map(([key, label, hint]) => (
              <label key={key}>
                <span className="form-label" style={{ display: 'block' }}>
                  {key === 'wages' && spouseId ? `${label}, theirs only` : label}
                  <span style={{ display: 'block', fontSize: 9, letterSpacing: 1.2, color: 'var(--dim)', marginTop: 2 }}>
                    {hint}
                  </span>
                </span>
                <MoneyInput min={0}
                       placeholder="0.00" value={form[key]} onChange={set(key)} />
              </label>
            ))}
          </div>
          <div style={{ display: 'flex', justifyContent: 'flex-end', marginTop: 14 }}>
            {/* Named, not a bare "Save": the modal footer has its own primary
                Save for the fields above, and two identical buttons on screen
                at once is a coin toss. */}
            <SubmitButton saving={busy} className="btn btn-primary btn-sm" disabled={busy} onClick={onSave}>Save return figures</SubmitButton>
          </div>
        </div>
      )}
    </div>
  );
}
