/**
 * components/admin/PartnersView.js: admin Financials view for LLC partners.
 *
 * Lists partner admin profiles (those with partner_allocation_pct set) showing current capital
 * balance from their 30x0 equity account, allocation %, K-1 cross-links for closed years, and a
 * transaction log. Records contributions (Pattern I) and distributions (Pattern J) by inserting
 * into `partner_transactions`; the forward trigger posts the JE. Partner out-of-pocket entries
 * (Pattern Q) are read-only, shown as synthesized rows.
 *
 * @invariant capital balance is credit-normal (credits minus debits on the 30x0 account).
 * @invariant allocations must sum to 100% before year-end close, asserted by close_fiscal_year;
 *            the header warns when they do not.
 * @gotcha partner_allocation_pct self-update is locked by RLS, so allocation changes go through
 *         AllocationModal's profiles update plus write_audit_log, never a raw self-update.
 * @see docs/MONEY.md Patterns I, J, Q
 */
import React, { useEffect, useMemo, useState, useCallback } from 'react';
import { supabase } from '../../lib/supabase';
import { fetchAllRows } from '../../utils/fetchAllRows';
import { fmtDate, fmtMoney, todayYMD } from '../../utils/format';
import HelpIcon from '../shared/HelpIcon';
import Feedback from '../shared/Feedback';
import ReadError from '../shared/ReadError';
import EmptyState from '../shared/EmptyState';
import { ReceiptIcon } from '../shared/Icon';
import { useToast } from '../shared/Toast';
import { humanizeError } from '../../utils/errors';
import { viewStoredFile, downloadStoredFile } from '../../utils/storage';
import { DB_DATE_MIN, PARTNER_TXN_NOTES_MAX, AUDIT_REASON_MAX } from '../../utils/dbLimits';
import Modal, { ModalClose } from '../shared/Modal';
import Field from '../shared/Field';
import Loading from '../shared/Loading';
import SubmitButton from '../shared/SubmitButton';
import MoneyInput from '../shared/MoneyInput';
import { useLoadState } from '../../hooks/useLoadState';
import Refreshing from '../shared/Refreshing';

const log = (...args) => {
  if (process.env.NODE_ENV !== 'production') console.error('[PartnersView]', ...args);
};

export default function PartnersView({ onNavigateToTaxCenter } = {}) {
  const [partners,    setPartners]    = useState([]);
  const [accounts,    setAccounts]    = useState([]);
  const [balances,    setBalances]    = useState({});  // profile_id -> balance
  const [transactions,setTransactions]= useState([]);
  const { loading, refreshing, begin, end } = useLoadState();
  // Holds the RAW error: ReadError humanizes, and a second pass over a humanized object
  // collapses it to the fallback.
  const [loadErr,     setLoadErr]     = useState(null);
  const [allocEditFor,setAllocEditFor]= useState(null); // partner row
  const [showTxnFor,  setShowTxnFor]  = useState(null); // partner row
  const [closedYears, setClosedYears] = useState([]);   // [{fiscal_year, status}, ...]
  const [oopRows, setOopRows] = useState([]); // expanded synthetic txn rows for partner OOP entries

  const fetchAll = useCallback(async () => {
    begin();
    setLoadErr(null);
    const [profRes, acctRes, txnRes, perRes] = await Promise.all([
      supabase.from('profiles').select('id, full_name, email, partner_allocation_pct').eq('role', 'admin').order('full_name'),
      supabase.from('ledger_accounts').select('*').eq('source_type', 'partner'),
      // Read to exhaustion, not `.limit(500)`: the rows are grouped per partner below, so a
      // prefix silently empties whichever partner sorts late. `id` is the paging tiebreak.
      // @see utils/fetchAllRows.js
      fetchAllRows(() => supabase.from('partner_transactions').select('*')
        .order('txn_date', { ascending: false }).order('id'))
        .then((data) => ({ data, error: null }), (error) => ({ data: null, error })),
      supabase.from('ledger_periods').select('fiscal_year, status').in('status', ['closed', 'locked']).order('fiscal_year', { ascending: false }),
    ]);
    // Four reads, one answer. Each partner's capital balance is built from the accounts and
    // the lines below, so a refused one prints a partner's capital short by whatever it held.
    const headErr = profRes.error || acctRes.error || txnRes.error || perRes.error;
    if (headErr) { setLoadErr(headErr); setPartners([]); end(); return; }
    const { data: profs } = profRes;
    const { data: accts } = acctRes;
    const { data: txns } = txnRes;
    const { data: pers } = perRes;
    const partnerOnly = (profs || []).filter((p) => p.partner_allocation_pct != null);
    setPartners(partnerOnly);
    setAccounts(accts || []);

    // Compute capital balance per partner from their 30x0 account.
    const accIdsByProfile = new Map();
    for (const a of accts || []) accIdsByProfile.set(a.profile_id, a.id);
    const allAccountIds = [...accIdsByProfile.values()];
    let bal = {};
    if (allAccountIds.length) {
      const { data: lines, error: lErr } = await supabase
        .from('ledger_entry_lines').select('account_id, debit, credit').in('account_id', allAccountIds);
      if (lErr) { log('lines', lErr); setLoadErr(lErr); setPartners([]); end(); return; }
      const sumByAcc = new Map();
      for (const l of lines || []) {
        const cur = sumByAcc.get(l.account_id) || { d: 0, c: 0 };
        cur.d += Number(l.debit || 0);
        cur.c += Number(l.credit || 0);
        sumByAcc.set(l.account_id, cur);
      }
      for (const [pid, accId] of accIdsByProfile.entries()) {
        const t = sumByAcc.get(accId) || { d: 0, c: 0 };
        bal[pid] = Math.round((t.c - t.d) * 100) / 100; // credit-normal
      }
    }
    setBalances(bal);
    setTransactions(txns || []);
    setClosedYears(pers || []);

    // Fetch every partner-OOP entry and synthesize one row per partner per entry
    // weighted by their `partner_allocation_pct` at fetch time. Filtered to posted,
    // non-reversed JEs only so reversed entries do not appear in the log.
    const { data: oopData, error: oopErr } = await supabase
      .from('expense_oop_payments')
      .select('id, expense_id, period_key, amount, paid_at, notes, payer_type, expense:expenses(name), je:ledger_journal_entries!journal_entry_id(is_posted, reversed_by_je_id)')
      .eq('payer_type', 'partners')
      .order('paid_at', { ascending: false });
    if (oopErr) { setLoadErr(oopErr); end(); return; }

    // The supporting document for an OOP contribution is the expense receipt
    // (bucket expense-receipts), keyed by (expense_id, period_key). Fetch the
    // receipt for each referenced expense so the row can offer a preview link.
    const oopExpenseIds = [...new Set((oopData || []).map(o => o.expense_id).filter(Boolean))];
    const receiptByKey = new Map();
    if (oopExpenseIds.length > 0) {
      // Best-effort: receipts DECORATE the out-of-pocket rows above, which have
      // already reported their own failure. A missing receipt link is visible.
      const { data: recData } = await supabase
        .from('expense_receipts')
        .select('expense_id, period_key, file_path, file_name')
        .in('expense_id', oopExpenseIds);
      for (const r of recData || []) {
        // Match the OOP entry's period: a one-time entry stores period_key NULL
        // on both sides; keep the first receipt found for that bucket.
        const key = `${r.expense_id}:${r.period_key ?? 'one-time'}`;
        if (!receiptByKey.has(key)) receiptByKey.set(key, { path: r.file_path, name: r.file_name });
      }
    }

    const expanded = [];
    for (const o of oopData || []) {
      if (!o.je?.is_posted || o.je.reversed_by_je_id) continue;
      const totalAlloc = partnerOnly.reduce((s, p) => s + Number(p.partner_allocation_pct || 0), 0) || 100;
      const receipt = receiptByKey.get(`${o.expense_id}:${o.period_key ?? 'one-time'}`) || null;
      for (const p of partnerOnly) {
        const pct = Number(p.partner_allocation_pct || 0);
        if (pct <= 0) continue;
        const share = (parseFloat(o.amount) || 0) * (pct / totalAlloc);
        expanded.push({
          id: `oop:${o.id}:${p.id}`,
          profile_id: p.id,
          txn_date: o.paid_at,
          txn_type: 'oop_contrib',
          amount: Math.round(share * 100) / 100,
          notes: `${o.expense?.name || 'Expense'}, ${o.period_key || 'one-time'}`,
          receiptPath: receipt?.path || null,
          receiptName: receipt?.name || null,
        });
      }
    }
    setOopRows(expanded);

    end();
  }, [begin, end]);

  useEffect(() => { fetchAll(); }, [fetchAll]);

  const totalAlloc = useMemo(() => partners.reduce((s, p) => s + Number(p.partner_allocation_pct || 0), 0), [partners]);
  const txnsByPartner = useMemo(() => {
    const m = new Map();
    const all = [...transactions, ...oopRows];
    // Sort desc by date; oopRows ids are strings so ties break naturally.
    all.sort((a, b) => (a.txn_date < b.txn_date ? 1 : a.txn_date > b.txn_date ? -1 : 0));
    for (const t of all) {
      if (!m.has(t.profile_id)) m.set(t.profile_id, []);
      m.get(t.profile_id).push(t);
    }
    return m;
  }, [transactions, oopRows]);

  if (loading) return <div className="page"><Loading /></div>;
  // Error before Empty: this page lists partner capital and out-of-pocket money.
  if (loadErr) return <div className="page"><ReadError error={loadErr} onRetry={fetchAll} /></div>;

  return (
    <div className="page">
      <div className="page-header">
        <div>
          <h1 className="page-title">PARTNERS<HelpIcon slug="partner-txns" /></h1>
          <div className="page-subtitle">Capital balances, contributions, and distributions<Refreshing on={refreshing} /></div>
        </div>
        <div style={{ fontSize: 12, color: totalAlloc === 100 ? 'var(--muted)' : 'var(--orange)' }}>
          Allocation total: <strong>{totalAlloc.toFixed(2)}%</strong>
          {totalAlloc !== 100 ? ', must equal 100% before year-end close' : ''}
        </div>
      </div>

      {partners.length === 0 ? (
        /* The old copy named a database column, in a code block, to a non-developer, and
           the one control that writes it (Edit allocation) renders per partner row, so it
           cannot exist before the first partner does. */
        <EmptyState
          title="No partners yet"
          text="A partner is an admin whose profile carries a capital allocation percentage. Nothing in the hub sets the first one, so it has to go on the profile directly. Every change after that is made here." />
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
          {partners.map((p) => {
            const ledgerAcct = accounts.find((a) => a.profile_id === p.id);
            const myTxns = txnsByPartner.get(p.id) || [];
            return (
              <div key={p.id} className="card">
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', flexWrap: 'wrap', gap: 12 }}>
                  <div>
                    <div style={{ fontSize: 18, fontWeight: 700 }}>{p.full_name || p.email}</div>
                    <div style={{ color: 'var(--muted)', fontSize: 12 }}>
                      {ledgerAcct ? `${ledgerAcct.code} ${ledgerAcct.name}` : 'No ledger account yet'}
                    </div>
                  </div>
                  <div style={{ display: 'flex', gap: 24 }}>
                    <div>
                      <div style={{ fontSize: 11, color: 'var(--muted)', textTransform: 'uppercase', letterSpacing: 1 }}>Capital</div>
                      <div style={{ fontFamily: 'var(--font-display)', fontSize: 22, color: 'var(--orange)' }}>{fmtMoney(balances[p.id] || 0)}</div>
                    </div>
                    <div>
                      <div style={{ fontSize: 11, color: 'var(--muted)', textTransform: 'uppercase', letterSpacing: 1 }}>Allocation</div>
                      <div style={{ fontSize: 22, fontWeight: 700 }}>{Number(p.partner_allocation_pct).toFixed(2)}%</div>
                    </div>
                  </div>
                  <div style={{ display: 'flex', gap: 8 }}>
                    <button className="btn btn-ghost btn-sm" onClick={() => setAllocEditFor(p)}>Edit allocation</button>
                    <HelpIcon slug="change-allocation" />
                    <button className="btn btn-secondary btn-sm" onClick={() => setShowTxnFor(p)}>+ Transaction</button>
                    <HelpIcon slug="partner-txns" />
                  </div>
                </div>

                {closedYears.length && onNavigateToTaxCenter ? (
                  <div style={{ marginTop: 10, display: 'flex', gap: 8, flexWrap: 'wrap', alignItems: 'center' }}>
                    <span style={{ fontSize: 11, color: 'var(--muted)', textTransform: 'uppercase', letterSpacing: 1 }}>K-1</span>
                    {closedYears.map((y) => (
                      <button key={y.fiscal_year} className="btn btn-ghost btn-sm"
                        onClick={() => onNavigateToTaxCenter(y.fiscal_year)}
                        title={`Open K-1 for FY ${y.fiscal_year} in Tax Center`}>
                        View K-1 for FY {y.fiscal_year} →
                      </button>
                    ))}
                  </div>
                ) : null}

                {myTxns.length > 0 ? (
                  <div className="table-wrap" style={{ marginTop: 16 }}>
                    <table style={{ width: '100%' }}>
                      <thead>
                        <tr>
                          <th scope="col" style={{ width: 110 }}>Date</th>
                          <th scope="col" style={{ width: 120 }}>Type</th>
                          <th scope="col" style={{ textAlign: 'right', width: 120 }}>Amount</th>
                          <th scope="col">Notes</th>
                        </tr>
                      </thead>
                      <tbody>
                        {myTxns.map((t) => (
                          <tr key={t.id}>
                            <td style={{ fontVariantNumeric: 'tabular-nums' }}>{fmtDate(t.txn_date)}</td>
                            <td>
                              {(() => {
                                const styleByType = {
                                  contribution: { bg: 'color-mix(in oklab, var(--green) 12%, transparent)', fg: 'var(--green)' },
                                  distribution: { bg: 'color-mix(in oklab, var(--orange) 12%, transparent)', fg: 'var(--orange)' },
                                  oop_contrib:  { bg: 'color-mix(in oklab, var(--orange) 18%, transparent)', fg: 'var(--orange)' },
                                };
                                const s = styleByType[t.txn_type] || styleByType.distribution;
                                const label = t.txn_type === 'oop_contrib' ? 'oop contrib' : t.txn_type;
                                return <span className="badge" style={{ background: s.bg, color: s.fg }}>{label}</span>;
                              })()}
                            </td>
                            <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>{fmtMoney(t.amount)}</td>
                            <td style={{ fontSize: 12 }}>
                              <div style={{ display: 'flex', alignItems: 'center', gap: 12, justifyContent: 'space-between' }}>
                                <span style={{ color: t.notes ? undefined : 'var(--muted)', minWidth: 0 }}>{t.notes || '—'}</span>
                                {t.receiptPath && (<>
                                  <button type="button" className="txn-receipt-link"
                                    title={t.receiptName ? `View receipt: ${t.receiptName}` : 'View receipt'}
                                    aria-label={t.receiptName ? `View receipt ${t.receiptName}` : 'View receipt'}
                                    onClick={() => viewStoredFile('expense-receipts', t.receiptPath)}>
                                    <ReceiptIcon size={14} />
                                  </button>
                                  {/* View opens a popup after an await, which a blocker eats. This one always works. */}
                                  <button type="button" className="txn-receipt-link"
                                    title={t.receiptName ? `Download receipt: ${t.receiptName}` : 'Download receipt'}
                                    aria-label={t.receiptName ? `Download receipt ${t.receiptName}` : 'Download receipt'}
                                    onClick={() => downloadStoredFile('expense-receipts', t.receiptPath, t.receiptName)}>
                                    ↓
                                  </button>
                                </>)}
                              </div>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                ) : (
                  <EmptyState variant="note" text="No transactions yet." style={{ paddingTop: 12 }} />
                )}
              </div>
            );
          })}
        </div>
      )}

      {allocEditFor ? (
        <AllocationModal partner={allocEditFor} onClose={() => setAllocEditFor(null)} onSaved={() => { setAllocEditFor(null); fetchAll(); }} />
      ) : null}

      {showTxnFor ? (
        <PartnerTxnModal partner={showTxnFor} onClose={() => setShowTxnFor(null)} onSaved={() => { setShowTxnFor(null); fetchAll(); }} />
      ) : null}
    </div>
  );
}

/**
 * Edit a partner's allocation %. Writes profiles.partner_allocation_pct then logs
 * the change via write_audit_log (reason required).
 *
 * @gotcha The audit log write is best-effort: if it fails the allocation still
 *         saved, so a warning toast fires rather than rolling back.
 */
// ── Allocation edit modal ─────────────────────────────────────────────────────
function AllocationModal({ partner, onClose, onSaved }) {
  const toast = useToast();
  const [pct, setPct]       = useState(String(partner.partner_allocation_pct ?? ''));
  const [reason, setReason] = useState('');
  const [saving, setSaving] = useState(false);
  const [error, setError]   = useState('');

  async function handleSave() {
    const value = parseFloat(pct);
    if (!Number.isFinite(value) || value < 0 || value > 100) { setError('Allocation must be between 0 and 100.'); return; }
    if (!reason.trim()) { setError('A reason is required (audit log).'); return; }
    setSaving(true);
    const { error: upErr } = await supabase
      .from('profiles').update({ partner_allocation_pct: value }).eq('id', partner.id);
    if (upErr) { setError(humanizeError(upErr)); setSaving(false); return; }

    const { error: auditErr } = await supabase.rpc('write_audit_log', {
      p_event_type: 'partner_allocation_changed',
      p_je_id: null,
      p_period_id: null,
      p_reason: reason.trim().slice(0, AUDIT_REASON_MAX),
      p_meta: { profile_id: partner.id, from_pct: partner.partner_allocation_pct, to_pct: value },
    });
    if (auditErr) {
      toast.warn({ title: 'Allocation saved, but audit log failed', body: humanizeError(auditErr).body });
    }

    setSaving(false);
    toast.success('Allocation updated');
    onSaved();
  }

  return (
    <Modal
      title="EDIT ALLOCATION"
      size="sm"
      onClose={onClose}
      closeDisabled={saving}
    >
        <div className="modal-body">
          <div style={{ marginBottom: 12, fontSize: 13 }}><strong>{partner.full_name || partner.email}</strong></div>
          <Field label="Allocation (%) *">{(id) => (<>
            <input id={id} className="form-input" type="number" step="0.01" min="0" max="100" value={pct} onChange={(e) => setPct(e.target.value)} />
          </>)}</Field>
          <Field label="Reason *">{(id) => (<>
            <textarea id={id} className="form-textarea" rows={3} maxLength={AUDIT_REASON_MAX} value={reason} onChange={(e) => setReason(e.target.value)} placeholder="Recorded in the audit log." />
          </>)}</Field>
          {error ? <Feedback value={error} /> : null}
          <div style={{ marginTop: 12, fontSize: 11, color: 'var(--muted)' }}>
            All partner allocations must sum to 100% before year-end close (the DB asserts at <code>close_fiscal_year</code>).
          </div>
        </div>
        <div className="modal-footer">
          <ModalClose className="btn btn-ghost" disabled={saving}>Cancel</ModalClose>
          <SubmitButton saving={saving} className="btn btn-primary" onClick={handleSave} disabled={saving || !reason.trim()}>Save</SubmitButton>
        </div>
    </Modal>
  );
}

/**
 * Record a partner contribution or distribution by inserting a partner_transactions
 * row; the forward trigger posts the JE (Pattern I / J). No direct JE write here.
 *
 * @invariant txn_date capped at today so a typo cannot date the JE into the future.
 */
// ── Contribution / distribution modal ─────────────────────────────────────────
function PartnerTxnModal({ partner, onClose, onSaved }) {
  const toast = useToast();
  const today = todayYMD();
  const [txnType, setTxnType] = useState('contribution');
  const [amount, setAmount]   = useState('');
  const [txnDate, setTxnDate] = useState(today);
  const [notes, setNotes]     = useState('');
  const [saving, setSaving]   = useState(false);
  const [error, setError]     = useState('');

  async function handleSave() {
    const value = parseFloat(amount);
    if (!Number.isFinite(value) || value <= 0) { setError('Amount must be greater than zero.'); return; }
    if (txnDate > today) { setError('Transaction date cannot be in the future.'); return; }
    setSaving(true);
    const { data: { user } = {} } = await supabase.auth.getUser();
    const { error: insErr } = await supabase.from('partner_transactions').insert({
      profile_id: partner.id,
      txn_type: txnType,
      amount: value,
      txn_date: txnDate,
      notes: notes.trim().slice(0, PARTNER_TXN_NOTES_MAX) || null,
      created_by: user?.id || null,
    });
    if (insErr) { setError(humanizeError(insErr)); setSaving(false); return; }
    setSaving(false);
    toast.success('Transaction recorded');
    onSaved();
  }

  return (
    <Modal
      title={txnType === 'contribution' ? 'PARTNER CONTRIBUTION' : 'PARTNER DISTRIBUTION'}
      size="sm"
      onClose={onClose}
      closeDisabled={saving}
    >
        <div className="modal-body">
          <div style={{ marginBottom: 12, fontSize: 13 }}><strong>{partner.full_name || partner.email}</strong></div>
          <div style={{ display: 'flex', gap: 8, marginBottom: 16 }}>
            {['contribution', 'distribution'].map((t) => (
              <button key={t} className="btn btn-ghost btn-sm"
                onClick={() => setTxnType(t)}
                style={{
                  borderRadius: 999, border: '1px solid var(--border)',
                  background: txnType === t ? 'var(--orange-glow)' : 'transparent',
                  color: txnType === t ? 'var(--orange)' : 'var(--muted)',
                  textTransform: 'capitalize',
                }}>{t}</button>
            ))}
          </div>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
            <Field label="Amount ($) *">{(id) => (<>
              <MoneyInput id={id} min="0" value={amount} onChange={(e) => setAmount(e.target.value)} />
            </>)}</Field>
            <Field label="Date *">{(id) => (<>
              <input id={id} className="form-input" type="date" min={DB_DATE_MIN} max={today} value={txnDate} onChange={(e) => setTxnDate(e.target.value)} />
            </>)}</Field>
          </div>
          <Field label="Notes">{(id) => (<>
            <textarea id={id} className="form-textarea" rows={2} maxLength={PARTNER_TXN_NOTES_MAX} value={notes} onChange={(e) => setNotes(e.target.value)} />
          </>)}</Field>
          {error ? <Feedback value={error} /> : null}
          <div style={{ marginTop: 8, fontSize: 11, color: 'var(--muted)' }}>
            The journal entry is posted automatically by the partner-transaction trigger
            (Pattern {txnType === 'contribution' ? 'I' : 'J'}).
          </div>
        </div>
        <div className="modal-footer">
          <ModalClose className="btn btn-ghost" disabled={saving}>Cancel</ModalClose>
          <SubmitButton saving={saving} className="btn btn-primary" onClick={handleSave} disabled={saving || !amount}>Save</SubmitButton>
        </div>
    </Modal>
  );
}
