/**
 * components/admin/AdminOverview.js: thin admin wrapper around components/shared/OverviewPage.
 *
 * Passes isAdmin=true and profileId=null (admin sees all creators); threads the
 * navigation callbacks. All logic lives in OverviewPage. Pass-through by design.
 */
import React from 'react';
import OverviewPage from '../shared/OverviewPage';

export default function AdminOverview({ setActiveView, navigateToCampaign, navigateToDeliverable }) {
  return <OverviewPage isAdmin={true} profileId={null} setActiveView={setActiveView} navigateToCampaign={navigateToCampaign} navigateToDeliverable={navigateToDeliverable} />;
}
