/**
 * components/shared/TaxCenter.js: admin Financials tab for year-end tax forms.
 *
 * Four sub-tabs: Form 1065 (partnership return, one per FY), K-1s (per-partner Schedule K-1),
 * 1099-NECs (per-creator Nonemployee Compensation), and Estimate (live current-year liability).
 * The numbers are computed by utils/ledger-tax.js; filing status persists in `tax_filings`,
 * upserted on (fiscal_year, form_type, subject_id).
 *
 * @gotcha the year selector lists only closed or locked ledger_periods so filed figures cannot
 *         drift. Estimate is the deliberate exception: it runs on the OPEN current year, hides
 *         the selector and self-fetches, so it stays reachable before the first year closes.
 * @gotcha SSNs and TINs are fetched per-download via the audit-logged get_profile_tax_id RPC,
 *         never preloaded.
 * @perf the PDF documents are dynamic-imported via usePdfDoc so @react-pdf/renderer stays out
 *       of the eager admin chunk.
 * @see utils/ledger-tax.js, docs/MONEY.md (tax)
 */
import React, { useEffect, useMemo, useState, useCallback } from 'react';
import { supabase } from '../../lib/supabase';
import { fetchAllRows } from '../../utils/fetchAllRows';
import { fmtDate, fmtMoney, todayYMD } from '../../utils/format';
import { parseLocalDate } from '../../utils/expenses';
import { DB_DATE_MIN, TAX_FILING_NOTES_MAX } from '../../utils/dbLimits';
// @react-pdf/renderer's `pdf` is dynamic-imported at click time below; the
// previous PDFDownloadLink JSX was replaced with imperative onClick handlers
// so the runtime stays out of the eager admin chunk.
import { useToast } from './Toast';
import { humanizeError } from '../../utils/errors';
import {
  buildForm1065,
  buildK1,
  build1099NEC, compYearBreakdown, necBasis,
  formatTaxAmount,
  NEC_THRESHOLD,
} from '../../utils/ledger-tax';
import { PAYROLL_SPLIT_SELECT } from '../../utils/payroll';
import { fetchCompBases } from '../../utils/compBasis';
import Feedback from './Feedback';
import ReadError from './ReadError';
import EmptyState from './EmptyState';
import HelpIcon from './HelpIcon';
import TaxEstimate from './TaxEstimate';
import { downloadBlob } from '../../utils/download';
import Modal, { ModalClose } from './Modal';
import Field from './Field';
import Loading from './Loading';
import SubmitButton from './SubmitButton';

// React.lazy can't be used for components passed as PDFDownloadLink's
// `document` prop: react-pdf renders that tree with its own reconciler in
// a worker, which doesn't honor React Suspense, so the lazy suspender
// leaks as a thrown `undefined`. Load the modules with plain dynamic
// import into state instead. Bundle splitting is preserved.
function usePdfDoc(loader) {
  const [Comp, setComp] = useState(null);
  useEffect(() => {
    let alive = true;
    loader().then((m) => { if (alive) setComp(() => m.default); }).catch(() => {});
    return () => { alive = false; };
  }, [loader]);
  return Comp;
}
const loadForm1065    = () => import('./pdf/Form1065');
const loadK1          = () => import('./pdf/K1');
const loadForm1099NEC = () => import('./pdf/Form1099NEC');

const log = (...args) => {
  if (process.env.NODE_ENV !== 'production') console.error('[TaxCenter]', ...args);
};

// `estimate` is the odd one out: it runs on the OPEN current year, so it hides
// the closed-year selector and loads its own data. @see components/shared/TaxEstimate.js
const SUB_TABS = [
  { id: 'f1065',    label: 'Form 1065', helpSlug: 'form-1065' },
  { id: 'k1',       label: 'K-1s',      helpSlug: 'k1' },
  { id: 'nec',      label: '1099-NECs', helpSlug: '1099-nec' },
  { id: 'estimate', label: 'Estimate',  helpSlug: 'tax-estimate' },
];

/**
 * The Tax Center shell: fiscal-year selector + sub-tab bar. Loads year-scoped +
 * global ledger/profile/filing data and hands each tab its slice.
 *
 * @param {number} [props.initialYear] - preselect this FY if it is closed.
 * @param {Function} [props.onConsumed] - called once initialYear is applied.
 */
export default function TaxCenter({ initialYear, onConsumed } = {}) {
  const [periods,  setPeriods]  = useState([]);
  const [year,     setYear]     = useState(null);
  const [accounts, setAccounts] = useState([]);
  const [entries,  setEntries]  = useState([]);
  const [lines,    setLines]    = useState([]);
  const [partners, setPartners] = useState([]);
  const [partnerTxns, setPartnerTxns] = useState([]);
  const [creators, setCreators] = useState([]);
  const [splits,   setSplits]   = useState([]);
  const [business, setBusiness] = useState(null);
  const [filings,  setFilings]  = useState([]);
  const [filingsError, setFilingsError] = useState(null);
  const [taxIds,   setTaxIds]   = useState({});   // { [profileId]: { last4 } }
  const [compBases, setCompBases] = useState([]); // creator_comp_basis rows
  const [tab,      setTab]      = useState('f1065');
  const [loading,  setLoading]  = useState(true);
  // @security a failing read below must REPLACE the forms, never log and fall through to
  //           `data || []`. Form 1065, the K-1s and the 1099-NEC basis are pure functions of
  //           these arrays, which makes a missing array a ZERO rather than an error, on the
  //           one surface whose output is a filing.
  //           @see.claude/rules/hub-ui.md (four data states)
  const [loadError, setLoadError] = useState(null);

  // Load closed fiscal years for the year selector.
  useEffect(() => {
    let alive = true;
    (async () => {
      const { data, error } = await supabase
        .from('ledger_periods').select('*')
        .in('status', ['closed', 'locked'])
        .order('fiscal_year', { ascending: false });
      if (!alive) return;
      if (error) { log('periods', error); setLoadError(error); setLoading(false); return; }
      const list = data || [];
      setPeriods(list);
      setYear((cur) => {
        if (cur != null) return cur;
        if (!list.length) return null;
        return initialYear && list.find((p) => p.fiscal_year === initialYear)
          ? initialYear
          : list[0].fiscal_year;
      });
      if (!list.length) setLoading(false);
      if (onConsumed) onConsumed();
    })();
    return () => { alive = false; };
  }, [initialYear, onConsumed]);

  // Load year-scoped + global data.
  useEffect(() => {
    if (year == null) return;
    let alive = true;
    setLoading(true);
    (async () => {
      const yStart = `${year}-01-01`;
      const yEnd   = `${year}-12-31`;
      const priorEnd = `${year - 1}-12-31`;

      const [
        accRes, entRes, lineRes, profRes, txnRes, splitRes, bizRes, filRes, tidRes, compRes,
      ] = await Promise.all([
        supabase.from('ledger_accounts').select('*').order('code', { ascending: true }),
        // Need this year + prior history for Schedule L beginning-of-year balance sheet.
        // Both of these read to exhaustion. limit(N) cannot: PostgREST caps any
        // single response at 1,000 rows, so the entry-line select returned 1,000
        // of 1,498 and every figure on this screen (Form 1065, the K-1s, the
        // 1099 basis, Schedule L) was computed on two thirds of the ledger.
        // @see utils/fetchAllRows.js
        fetchAllRows(() => supabase.from('ledger_journal_entries').select('id, entry_date, description, source_type, source_id, is_posted, reversed_by_je_id').lte('entry_date', yEnd).eq('is_posted', true).order('id'))
          .then((data) => ({ data, error: null }), (error) => ({ data: null, error })),
        fetchAllRows(() => supabase.from('ledger_entry_lines').select('id, journal_entry_id, account_id, debit, credit').order('id'))
          .then((data) => ({ data, error: null }), (error) => ({ data: null, error })),
        // Inline fetch (not useCreators): single query feeds BOTH partners (admins with partner_allocation_pct) and creators, plus extra address columns for 1099-NEC / K-1 forms.
        supabase.from('profiles').select('id, role, full_name, creator_name, email, partner_allocation_pct, street_address, city, state_province, postal_code, country').order('full_name'),
        supabase.from('partner_transactions').select('*').gte('txn_date', yStart).lte('txn_date', yEnd),
        supabase.from('payout_splits')
          .select(PAYROLL_SPLIT_SELECT)
          .gte('cleared_date', yStart).lte('cleared_date', yEnd)
          .not('destination_id', 'is', null),
        supabase.from('business_profile').select('*').eq('is_active', true).limit(1).maybeSingle(),
        supabase.from('tax_filings').select('*').eq('fiscal_year', year),
        supabase.from('profile_tax_ids').select('profile_id, last4'),
        // Which days of the year each creator was on a 1099. Without it Box 1 cannot be told
        // from her whole year, so it gates the render like every other read here.
        fetchCompBases(supabase),
      ]);
      if (!alive) return;
      const failures = [
        ['accounts', accRes], ['entries', entRes], ['lines', lineRes], ['profiles', profRes],
        ['partnerTxns', txnRes], ['splits', splitRes], ['business', bizRes],
        ['filings', filRes], ['taxIds', tidRes], ['compBases', compRes],
      ].filter(([, res]) => res.error);
      for (const [name, res] of failures) log(name, res.error);
      if (failures.length) { setLoadError(failures[0][1].error); setLoading(false); return; }
      setLoadError(null);

      const profs = profRes.data || [];
      const tidMap = {};
      for (const r of tidRes.data || []) tidMap[r.profile_id] = { last4: r.last4 };
      setAccounts(accRes.data || []);
      setEntries(entRes.data || []);
      setLines(lineRes.data || []);
      setPartners(profs.filter((p) => p.role === 'admin' && p.partner_allocation_pct != null));
      setCreators(profs.filter((p) => p.role === 'creator'));
      setPartnerTxns(txnRes.data || []);
      setSplits(splitRes.data || []);
      setBusiness(bizRes.data || null);
      setFilings(filRes.data || []);
      setFilingsError(null);
      setTaxIds(tidMap);
      setCompBases(compRes.data);
      setLoading(false);
      void priorEnd;  // referenced in buildForm1065 internals
    })();
    return () => { alive = false; };
  }, [year]);

  const f1065 = useMemo(() => {
    if (!year || !accounts.length) return null;
    return buildForm1065(accounts, entries, lines, year, { partners, partnerTxns, compBases });
  }, [year, accounts, entries, lines, partners, partnerTxns, compBases]);

  /**
   * Re-read this year's filings after a Mark as Filed or an Unfile.
   *
   * @gotcha a refused refetch is not a filing that reverted. Defaulting the null to `[]` made
   *         every strip's lookup miss, and `filing?.status || 'draft'` then printed DRAFT
   *         seconds after the confirmation number was typed, over a return that IS filed. A
   *         status nobody could read is unknown, and both one-way-door buttons go with it.
   *         @see .claude/rules/hub-ui.md (the four data states)
   */
  const refreshFilings = useCallback(async () => {
    if (!year) return;
    const { data, error } = await supabase.from('tax_filings').select('*').eq('fiscal_year', year);
    if (error) { log('refreshFilings', error); setFilings([]); setFilingsError(error); return; }
    setFilings(data || []);
    setFilingsError(null);
  }, [year]);

  // The year's cleared splits, grouped by creator. Kept as ROWS rather than summed, because a
  // year can now hold a wage half and a contractor half and only the split's own cleared_date
  // says which side it falls on. What counts as pay is still decided downstream, by
  // sumTaxableComp inside necBasis, so an out-of-pocket payback never reaches Box 1.
  const creatorCleared = useMemo(() => {
    const m = new Map();
    for (const s of splits) {
      const pid = s.payout?.profile_id;
      if (!pid) continue;
      if (!m.has(pid)) m.set(pid, []);
      m.get(pid).push(s);
    }
    return m;
  }, [splits]);

  // The Estimate tab runs on the open current year, so the closed-year selector
  // is meaningless there and the "no closed years" wall must not hide it.
  const isEstimate = tab === 'estimate';
  const noClosedYears = periods.length === 0;

  return (
    <div>
      {!isEstimate && (
        <div style={{ display: 'flex', alignItems: 'center', gap: 16, marginBottom: 18, flexWrap: 'wrap' }}>
          <div className="form-label" style={{ margin: 0 }}>Fiscal Year</div>
          <select aria-label="Fiscal year" className="form-select" style={{ width: 140 }} value={year ?? ''} onChange={(e) => setYear(parseInt(e.target.value, 10))}>
            {periods.map((p) => (
              <option key={p.id} value={p.fiscal_year}>FY {p.fiscal_year} ({p.status})</option>
            ))}
          </select>
          <div style={{ color: 'var(--muted)', fontSize: 12 }}>
            Tax Center shows only closed years so the numbers can't drift.
          </div>
          {(() => {
            const t = SUB_TABS.find((x) => x.id === tab);
            return t?.helpSlug ? <HelpIcon slug={t.helpSlug} /> : null;
          })()}
        </div>
      )}

      <div className="tab-bar" style={{ display: 'flex', gap: 4, borderBottom: '1px solid var(--border)', marginBottom: 20, flexWrap: 'wrap' }}>
        {SUB_TABS.map((t) => (
          <button key={t.id} className="btn btn-ghost"
            onClick={() => setTab(t.id)}
            style={{
              borderRadius: 0,
              borderBottom: tab === t.id ? '2px solid var(--orange)' : '2px solid transparent',
              color: tab === t.id ? 'var(--orange)' : 'var(--muted)',
              padding: '8px 14px',
              fontWeight: tab === t.id ? 700 : 400,
            }}
          >{t.label}</button>
        ))}
      </div>

      {isEstimate && <TaxEstimate />}

      {!isEstimate && loadError && (
        <Feedback value={{
          ...humanizeError(loadError),
          title: 'The tax forms could not be loaded',
        }} />
      )}

      {!isEstimate && !loadError && noClosedYears && (
        <div className="card">
          <EmptyState
            title="No closed fiscal years yet"
            text={<>Close a fiscal year from the P&amp;L tab to unlock the tax forms.</>} />
        </div>
      )}

      {!isEstimate && !loadError && !noClosedYears && (loading ? <Loading /> : (
        <>
          {tab === 'f1065' && (
            <Form1065Tab f1065={f1065} business={business} year={year} filings={filings} filingsError={filingsError} onFiled={refreshFilings} />
          )}
          {tab === 'k1' && (
            <K1Tab f1065={f1065} business={business} year={year} partners={partners} taxIds={taxIds} filings={filings} filingsError={filingsError} onFiled={refreshFilings} />
          )}
          {tab === 'nec' && (
            <NECTab year={year} business={business} creators={creators} creatorCleared={creatorCleared} compBases={compBases} taxIds={taxIds} filings={filings} filingsError={filingsError} onFiled={refreshFilings} />
          )}
        </>
      ))}
    </div>
  );
}

// ── Status header strip ─────────────────────────────────────────────────────

/**
 * @param {*} [props.error] the RAW error from the filings read. Set means the status is
 *        UNKNOWN, which is not draft: both controls are one-way doors into `upsertFiling`,
 *        whose update branch overwrites a `filed_at` and an `irs_confirmation` that may
 *        already be the real ones.
 */
function FilingStatusStrip({ filing, error, onMarkFiled, onUnfile, onRetry, busy, label }) {
  const status = error ? 'unknown' : (filing?.status || 'draft');
  const color = error ? 'var(--muted)'
    : status === 'filed' ? 'var(--green)'
    : status === 'ready' ? 'var(--orange)' : 'var(--muted)';
  return (
    <div style={{ display: 'flex', alignItems: 'center', gap: 16, padding: '10px 14px', background: 'rgba(255,255,255,0.03)', borderRadius: 6, marginBottom: 14, flexWrap: 'wrap' }}>
      <div style={{ fontSize: 11, color: 'var(--muted)', textTransform: 'uppercase', letterSpacing: 1 }}>{label || 'Status'}</div>
      <div style={{ fontSize: 13, color, fontWeight: 700, textTransform: 'uppercase' }}>{status}</div>
      {!error && filing?.filed_at ? (
        <div style={{ fontSize: 12, color: 'var(--muted)' }}>
          Filed {fmtDate(filing.filed_at)}{filing.irs_confirmation ? ` · IRS # ${filing.irs_confirmation}` : ''}
        </div>
      ) : null}
      <div style={{ flex: 1 }} />
      {error ? (
        <div style={{ flexBasis: '100%' }}><ReadError error={error} onRetry={onRetry} /></div>
      ) : status !== 'filed' ? (
        <SubmitButton saving={busy} className="btn btn-secondary btn-sm" onClick={onMarkFiled} disabled={busy}>Mark as Filed…</SubmitButton>
      ) : (
        <SubmitButton saving={busy} className="btn btn-ghost btn-sm" onClick={onUnfile} disabled={busy}>Unfile…</SubmitButton>
      )}
    </div>
  );
}

function MarkFiledModal({ onConfirm, onClose, busy }) {
  const [conf, setConf]       = useState('');
  const [notes, setNotes]     = useState('');
  // Defaults to today because that is the common case, and is editable because the
  // documented workflow is to tick this AFTER the return went to the IRS.
  const [filedOn, setFiledOn] = useState(todayYMD);
  const [error, setError]     = useState('');
  return (
    <Modal
      title="MARK AS FILED"
      size="sm"
      onClose={onClose}
      closeDisabled={busy}
    >
        <div className="modal-body">
          <Feedback value={error} />
          <Field label="Filing date">{(id) => (<>
            <input id={id} className="form-input" type="date" value={filedOn}
              min={DB_DATE_MIN} max={todayYMD()}
              onChange={(e) => setFiledOn(e.target.value)} />
          </>)}</Field>
          <Field label="IRS confirmation #">{(id) => (<>
            <input id={id} className="form-input" maxLength={100} value={conf} onChange={(e) => setConf(e.target.value)} />
          </>)}</Field>
          <Field label="Notes">{(id) => (<>
            <textarea id={id} className="form-textarea" rows={3} maxLength={TAX_FILING_NOTES_MAX} value={notes} onChange={(e) => setNotes(e.target.value)} />
          </>)}</Field>
          <div style={{ fontSize: 11, color: 'var(--muted)' }}>
            Records the date you filed, not the date you tick this. You can unfile it again from the same strip.
          </div>
        </div>
        <div className="modal-footer">
          <ModalClose className="btn btn-ghost" disabled={busy}>Cancel</ModalClose>
          <SubmitButton saving={busy} className="btn btn-primary" disabled={busy} onClick={() => {
            if (!filedOn || filedOn > todayYMD()) { setError('Pick the date the return was filed. It cannot be in the future.'); return; }
            onConfirm({ filedOn, irs_confirmation: conf.trim() || null, notes: notes.trim() || null });
          }}>Save</SubmitButton>
        </div>
    </Modal>
  );
}

/**
 * The way back out of the one-way door.
 *
 * Unfiling clears `filed_at` and the IRS number, and the row is the only copy of either,
 * so the reason and what was cleared are appended to `notes` in the same write. The
 * reason is required for the same purpose it is required on an allocation change.
 */
function UnfileModal({ filing, onConfirm, onClose, busy }) {
  const [reason, setReason] = useState('');
  const [error, setError]   = useState('');
  return (
    <Modal title="UNFILE" size="sm" onClose={onClose} closeDisabled={busy}>
      <div className="modal-body">
        <Feedback value={error} />
        <div style={{ fontSize: 13, marginBottom: 12 }}>
          This clears the filing date{filing?.filed_at ? ` (${fmtDate(filing.filed_at)})` : ''}
          {filing?.irs_confirmation ? ` and the IRS confirmation number (${filing.irs_confirmation})` : ''} and
          puts the return back to Ready. Both are kept in the notes.
        </div>
        <Field label="Reason">{(id) => (<>
          <textarea id={id} className="form-textarea" rows={3} maxLength={TAX_FILING_NOTES_MAX}
            value={reason} onChange={(e) => setReason(e.target.value)} />
        </>)}</Field>
      </div>
      <div className="modal-footer">
        <ModalClose className="btn btn-ghost" disabled={busy}>Cancel</ModalClose>
        <SubmitButton saving={busy} className="btn btn-danger" disabled={busy} onClick={() => {
          if (!reason.trim()) { setError('Say why this is being unfiled. It goes in the notes.'); return; }
          onConfirm({ reason: reason.trim() });
        }}>Unfile</SubmitButton>
      </div>
    </Modal>
  );
}

/**
 * What an unfile leaves behind, appended to whatever the notes already said.
 * Clearing `filed_at` and `irs_confirmation` destroys the only record of either.
 */
function unfileNotes(filing, reason) {
  const cleared = [
    `Unfiled ${fmtDate(todayYMD())}`,
    filing?.filed_at ? `filed ${fmtDate(filing.filed_at)}` : null,
    filing?.irs_confirmation ? `IRS # ${filing.irs_confirmation}` : null,
  ].filter(Boolean).join(', ');
  return [filing?.notes, `${cleared}. ${reason}`].filter(Boolean).join('\n').slice(-TAX_FILING_NOTES_MAX);
}

/**
 * The audit row a filing transition leaves behind, written after the filing itself saved.
 *
 * `tax_filings.notes` is a plain editable column that the next Mark as Filed overwrites
 * wholesale, so what an unfile clears cannot live only there. `ledger_audit_log` is append
 * only and is the trail the rest of the money system already has.
 *
 * @gotcha `write_audit_log` requires a non-empty reason for this event, and Mark as Filed's
 *         Notes field is optional. The reason is synthesised from the transition itself so the
 *         mandate cannot be violated by an admin who leaves the box empty.
 * @gotcha best effort, not transactional, which is the decision PartnersView already took for
 *         `partner_allocation_changed`: the filing has saved, and rolling it back because its
 *         audit row failed would be worse than a thinner trail.
 * @see schemas/SCHEMA.sql `write_audit_log`, components/admin/PartnersView.js
 */
async function logFilingChange({ year, formType, subjectId, status, filedOn, irs_confirmation, reason, prior }) {
  const filed = status === 'filed';
  const said = (reason || '').trim();
  return supabase.rpc('write_audit_log', {
    p_event_type: 'filing_status_changed',
    p_je_id: null,
    p_period_id: null,
    p_reason: said || `${formType} for ${year} marked ${filed ? `filed on ${filedOn}` : status}.`,
    p_meta: {
      form_type: formType,
      fiscal_year: year,
      subject_id: subjectId || null,
      status,
      filed_at: filed ? filedOn : null,
      irs_confirmation: filed ? (irs_confirmation || null) : null,
      // What an unfile destroys. Without these the append-only copy says less than the
      // mutable one it exists to back up.
      cleared_filed_at: filed ? null : (prior?.filed_at || null),
      cleared_irs_confirmation: filed ? null : (prior?.irs_confirmation || null),
    },
  });
}

/** The filing saved and its audit row did not, so the person is told rather than rolled back. */
const warnAudit = (toast, err) => {
  if (err) toast.warn({ title: 'Filing saved, but the audit log failed', body: humanizeError(err).body });
};

async function upsertFiling({ year, formType, subjectId, status, filedOn, irs_confirmation, notes, reason, prior }) {
  // Find existing filing first (NULL subject_id needs `is`).
  let q = supabase.from('tax_filings').select('id').eq('fiscal_year', year).eq('form_type', formType);
  q = subjectId ? q.eq('subject_id', subjectId) : q.is('subject_id', null);
  // Deciding UPDATE vs INSERT for a filing record. A refused read read as "no
  // filing exists" and inserted a second one.
  const { data: existing, error: existErr } = await q.maybeSingle();
  if (existErr) return { error: existErr };
  const payload = {
    fiscal_year: year,
    form_type: formType,
    subject_id: subjectId || null,
    status,
    // Local midnight, never `new Date(filedOn)`: a UTC-midnight timestamp renders as the
    // PREVIOUS day everywhere in the US, so a 1065 filed on the 14th reads as the 13th.
    filed_at: status === 'filed' ? parseLocalDate(filedOn).toISOString() : null,
    irs_confirmation: status === 'filed' ? (irs_confirmation || null) : null,
    notes: notes || null,
  };
  // Awaited rather than returned, so the audit row is written only for a filing that saved.
  // Every form type reaches the log through this one writer: 1065, K-1 and 1099-NEC.
  const res = existing?.id
    ? await supabase.from('tax_filings').update(payload).eq('id', existing.id)
    : await supabase.from('tax_filings').insert(payload);
  if (res.error) return res;
  const { error: auditErr } = await logFilingChange({ year, formType, subjectId, status, filedOn, irs_confirmation, reason, prior });
  return { ...res, auditErr };
}

// ── Tab 1: Form 1065 ────────────────────────────────────────────────────────

function Form1065Tab({ f1065, business, year, filings, filingsError, onFiled }) {
  const toast = useToast();
  const filing = filings.find((f) => f.form_type === 'form_1065' && !f.subject_id) || null;
  const [showFile, setShowFile] = useState(false);
  const [showUnfile, setShowUnfile] = useState(false);
  const [busy, setBusy] = useState(false);
  const Form1065Document = usePdfDoc(loadForm1065);
  if (!f1065) return <Loading>Loading numbers…</Loading>;
  const p = f1065.page1;

  async function handleFile({ filedOn, irs_confirmation, notes }) {
    setBusy(true);
    const { error, auditErr } = await upsertFiling({ year, formType: 'form_1065', subjectId: null, status: 'filed', filedOn, irs_confirmation, notes });
    setBusy(false);
    if (error) { log('mark filed', error); toast.error({ title: 'Could not mark filed', body: humanizeError(error).body }); return; }
    warnAudit(toast, auditErr);
    setShowFile(false);
    onFiled();
  }

  async function handleUnfile({ reason }) {
    setBusy(true);
    const { error, auditErr } = await upsertFiling({ year, formType: 'form_1065', subjectId: null, status: 'ready', notes: unfileNotes(filing, reason), reason, prior: filing });
    setBusy(false);
    if (error) { log('unfile', error); toast.error({ title: 'Could not unfile', body: humanizeError(error).body }); return; }
    warnAudit(toast, auditErr);
    setShowUnfile(false);
    onFiled();
  }

  return (
    <div>
      <FilingStatusStrip filing={filing} error={filingsError} onRetry={onFiled} onMarkFiled={() => setShowFile(true)} onUnfile={() => setShowUnfile(true)} busy={busy} label="Form 1065 status" />

      <div className="card">
        <h2 className="card-title">Form 1065: FY {year}</h2>
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 140px', gap: 8, fontSize: 13 }}>
          <div>1a · Gross receipts (incl. in-kind, excl. returns)</div><div style={{ textAlign: 'right' }}>{fmtMoney(p.line1a)}</div>
          <div>1b · Returns and allowances</div>                       <div style={{ textAlign: 'right' }}>{fmtMoney(p.line1b)}</div>
          <div>1c · Net receipts</div>                                  <div style={{ textAlign: 'right' }}>{fmtMoney(p.line1c)}</div>
          <div>2  · Cost of revenue (5xxx)</div>                        <div style={{ textAlign: 'right' }}>{fmtMoney(p.line2)}</div>
          <div>3  · Gross profit</div>                                  <div style={{ textAlign: 'right' }}>{fmtMoney(p.line3)}</div>
          <div>20 · Other deductions</div>                              <div style={{ textAlign: 'right' }}>{fmtMoney(p.line20)}</div>
          <div>21 · Total deductions</div>                              <div style={{ textAlign: 'right' }}>{fmtMoney(p.line21)}</div>
          <div style={{ fontWeight: 700, paddingTop: 6, borderTop: '1px solid var(--border)' }}>22 · Ordinary business income</div>
          <div style={{ fontWeight: 700, paddingTop: 6, borderTop: '1px solid var(--border)', textAlign: 'right', color: 'var(--orange)' }}>{fmtMoney(p.line22)}</div>
        </div>
        <div style={{ marginTop: 14, fontSize: 11, color: 'var(--muted)' }}>
          Audit: cash revenue {fmtMoney(p.cashRevenue)} · in-kind revenue {fmtMoney(p.inKindRevenue)} · in-kind comp 5210x {fmtMoney(p.inKindComp)}.
        </div>
      </div>

      <div style={{ display: 'flex', gap: 10, marginTop: 14 }}>
        {Form1065Document ? (
          <button className="btn btn-primary" onClick={async () => {
            try {
              const { pdf } = await import('@react-pdf/renderer');
              const blob = await pdf(<Form1065Document form1065={f1065} businessProfile={business} />).toBlob();
              downloadBlob(blob, `form-1065-fy${year}.pdf`);
            } catch (e) {
              toast.error({ title: 'Could not build PDF', body: humanizeError(e).body });
            }
          }}>Download Form 1065 PDF</button>
        ) : <button className="btn btn-secondary" disabled>Preparing PDF…</button>}
      </div>

      {showFile ? <MarkFiledModal busy={busy} onClose={() => setShowFile(false)} onConfirm={handleFile} /> : null}
      {showUnfile ? <UnfileModal filing={filing} busy={busy} onClose={() => setShowUnfile(false)} onConfirm={handleUnfile} /> : null}
    </div>
  );
}

// ── Tab 2: K-1s ─────────────────────────────────────────────────────────────

function K1Tab({ f1065, business, year, partners, taxIds, filings, filingsError, onFiled }) {
  const [busyId, setBusyId] = useState(null);
  const [downloadingId, setDownloadingId] = useState(null);
  const [showFor, setShowFor] = useState(null);
  const [unfileFor, setUnfileFor] = useState(null);
  const K1Document = usePdfDoc(loadK1);
  const toast = useToast();
  if (!f1065) return <Loading>Loading numbers…</Loading>;
  if (!partners.length) {
    return <EmptyState
      title="No K-1s to issue"
      text="A K-1 goes to each partner, and no admin profile carries a capital allocation yet. Set one up under Accounting, Partners first." />;
  }
  const m2ByPartner = new Map(f1065.schedM2.perPartner.map((r) => [r.partner.id, r]));

  async function handleFile(partner, { filedOn, irs_confirmation, notes }) {
    setBusyId(partner.id);
    const { error, auditErr } = await upsertFiling({ year, formType: 'k1', subjectId: partner.id, status: 'filed', filedOn, irs_confirmation, notes });
    setBusyId(null);
    if (error) { log('mark filed k1', error); toast.error({ title: 'Could not mark filed', body: humanizeError(error).body }); return; }
    warnAudit(toast, auditErr);
    setShowFor(null);
    onFiled();
  }

  async function handleUnfile(partner, filing, { reason }) {
    setBusyId(partner.id);
    const { error, auditErr } = await upsertFiling({ year, formType: 'k1', subjectId: partner.id, status: 'ready', notes: unfileNotes(filing, reason), reason, prior: filing });
    setBusyId(null);
    if (error) { log('unfile k1', error); toast.error({ title: 'Could not unfile', body: humanizeError(error).body }); return; }
    warnAudit(toast, auditErr);
    setUnfileFor(null);
    onFiled();
  }

  async function handleDownload(p, k1) {
    if (!K1Document) return;
    setDownloadingId(p.id);
    const { data: taxId, error } = await supabase.rpc('get_profile_tax_id', { p_profile_id: p.id });
    if (error) {
      setDownloadingId(null);
      toast.error({ title: 'Could not fetch tax ID', body: humanizeError(error)?.body });
      return;
    }
    const k1WithTaxId = { ...k1, partB: { ...k1.partB, tax_id: taxId } };
    try {
      const { pdf } = await import('@react-pdf/renderer');
      const blob = await pdf(<K1Document k1={k1WithTaxId} />).toBlob();
      downloadBlob(blob, `k1-${(p.full_name || 'partner').replace(/\s+/g, '-').toLowerCase()}-fy${year}.pdf`);
    } catch (e) {
      toast.error({ title: 'Could not build PDF', body: humanizeError(e).body });
    } finally {
      setDownloadingId(null);
    }
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
      {partners.map((p) => {
        const m2 = m2ByPartner.get(p.id) || null;
        const k1 = buildK1(p, year, f1065.schedK, m2, business);
        const filing = filings.find((f) => f.form_type === 'k1' && f.subject_id === p.id) || null;
        const last4 = taxIds?.[p.id]?.last4 || null;
        const missingTin = !last4;
        return (
          <div key={p.id} className="card">
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 12 }}>
              <div>
                <div style={{ fontSize: 18, fontWeight: 700 }}>{p.full_name}</div>
                <div style={{ color: 'var(--muted)', fontSize: 12 }}>
                  Allocation {Number(p.partner_allocation_pct).toFixed(2)}%
                  {' · '}
                  {missingTin
                    ? <span style={{ color: 'var(--orange)' }}>Missing TIN: add in Creator Setup</span>
                    : <span>Ending in {last4}</span>}
                </div>
              </div>
              <div style={{ display: 'flex', gap: 28 }}>
                <Stat label="Box 1: Income"    value={`$${formatTaxAmount(k1.partC.box1)}`} highlight />
                <Stat label="Box 19A: Distribs" value={`$${formatTaxAmount(k1.partC.box19A)}`} />
                <Stat label="Capital ending"     value={k1.partC.capital ? `$${formatTaxAmount(k1.partC.capital.ending)}` : '—'} />
              </div>
            </div>

            <FilingStatusStrip filing={filing} error={filingsError} onRetry={onFiled} onMarkFiled={() => setShowFor(p)} onUnfile={() => setUnfileFor(p)} busy={busyId === p.id} label="K-1 status" />

            <div style={{ display: 'flex', gap: 10 }}>
              <button
                className="btn btn-primary"
                disabled={!K1Document || missingTin || downloadingId === p.id}
                onClick={() => handleDownload(p, k1)}
              >
                {!K1Document ? 'Preparing PDF…'
                  : downloadingId === p.id ? 'Building PDF…'
                  : 'Download K-1 PDF'}
              </button>
            </div>

            {showFor?.id === p.id ? (
              <MarkFiledModal busy={busyId === p.id} onClose={() => setShowFor(null)} onConfirm={(args) => handleFile(p, args)} />
            ) : null}
            {unfileFor?.id === p.id ? (
              <UnfileModal filing={filing} busy={busyId === p.id} onClose={() => setUnfileFor(null)} onConfirm={(args) => handleUnfile(p, filing, args)} />
            ) : null}
          </div>
        );
      })}
    </div>
  );
}

// ── Tab 3: 1099-NECs ────────────────────────────────────────────────────────

/**
 * One creator's year, split into the periods she spent on each basis, with the money that
 * landed in each. Shown whenever the year is not wholly contract work, because a Box 1 figure
 * smaller than her year is otherwise a number the reader has to leave the screen to reconcile.
 *
 * @gotcha deliberately NOT shown for a wholly-1099 year, where the single row would just repeat
 *         Box 1 back at the reader under a different name.
 */
function YearSplit({ breakdown }) {
  return (
    <div style={{ marginTop: 12, borderTop: '1px solid var(--border)', paddingTop: 10 }}>
      {breakdown.slices.map((slice) => (
        <div key={slice.from} style={{ display: 'flex', alignItems: 'baseline', gap: 12, fontSize: 12, padding: '3px 0' }}>
          <span style={{ color: 'var(--white)', minWidth: 76 }}>
            {slice.basis === 'w2' ? 'W-2 wages' : '1099-NEC'}
          </span>
          <span style={{ color: 'var(--dim)', flex: 1 }}>
            {fmtDate(slice.from, 'MMM d')} to {fmtDate(slice.to, 'MMM d')}
          </span>
          <span style={{ color: 'var(--muted)', fontVariantNumeric: 'tabular-nums' }}>
            {fmtMoney(slice.amount)}
          </span>
        </div>
      ))}
      <div style={{ display: 'flex', alignItems: 'baseline', gap: 12, fontSize: 12, marginTop: 6, paddingTop: 6, borderTop: '1px solid var(--border)' }}>
        <span style={{ color: 'var(--muted)', flex: 1 }}>Year total</span>
        <span style={{ color: 'var(--white)', fontVariantNumeric: 'tabular-nums' }}>
          {fmtMoney(breakdown.total)}
        </span>
      </div>
    </div>
  );
}

function NECTab({ year, business, creators, creatorCleared, compBases, taxIds, filings, filingsError, onFiled }) {
  const [busyId, setBusyId] = useState(null);
  const [downloadingId, setDownloadingId] = useState(null);
  const [showFor, setShowFor] = useState(null);
  const [unfileFor, setUnfileFor] = useState(null);
  const Form1099NECDocument = usePdfDoc(loadForm1099NEC);
  const toast = useToast();

  async function handleFile(creator, { filedOn, irs_confirmation, notes }) {
    setBusyId(creator.id);
    const { error, auditErr } = await upsertFiling({ year, formType: 'form_1099_nec', subjectId: creator.id, status: 'filed', filedOn, irs_confirmation, notes });
    setBusyId(null);
    if (error) { log('mark filed nec', error); toast.error({ title: 'Could not mark filed', body: humanizeError(error).body }); return; }
    warnAudit(toast, auditErr);
    setShowFor(null);
    onFiled();
  }

  async function handleUnfile(creator, filing, { reason }) {
    setBusyId(creator.id);
    const { error, auditErr } = await upsertFiling({ year, formType: 'form_1099_nec', subjectId: creator.id, status: 'ready', notes: unfileNotes(filing, reason), reason, prior: filing });
    setBusyId(null);
    if (error) { log('unfile nec', error); toast.error({ title: 'Could not unfile', body: humanizeError(error).body }); return; }
    warnAudit(toast, auditErr);
    setUnfileFor(null);
    onFiled();
  }

  async function handleDownload(c, form) {
    if (!Form1099NECDocument) return;
    setDownloadingId(c.id);
    const { data: taxId, error } = await supabase.rpc('get_profile_tax_id', { p_profile_id: c.id });
    if (error) {
      setDownloadingId(null);
      toast.error({ title: 'Could not fetch tax ID', body: humanizeError(error)?.body });
      return;
    }
    const formWithTaxId = { ...form, payeeInfo: { ...form.payeeInfo, tax_id: taxId } };
    try {
      const { pdf } = await import('@react-pdf/renderer');
      const blob = await pdf(<Form1099NECDocument form={formWithTaxId} />).toBlob();
      downloadBlob(blob, `form-1099-nec-${(c.full_name || c.creator_name || 'creator').replace(/\s+/g, '-').toLowerCase()}-fy${year}.pdf`);
    } catch (e) {
      toast.error({ title: 'Could not build PDF', body: humanizeError(e).body });
    } finally {
      setDownloadingId(null);
    }
  }

  if (!creators.length) {
    return <EmptyState
      title="No creators"
      text="Add a creator profile to enable 1099-NEC generation." />;
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
      <div style={{ fontSize: 12, color: 'var(--muted)', marginBottom: -4 }}>
        Box 1 holds only pay from the days a creator was on a 1099. Wage days are on a W-2 the
        payroll provider files, and an out-of-pocket payback is not income. Issued above ${NEC_THRESHOLD} for FY {year}.
      </div>
      {creators.map((c) => {
        const mine = creatorCleared.get(c.id) || [];
        const breakdown = compYearBreakdown(mine, compBases, c.id, year);
        // The form decides the threshold, so the card and the PDF can never disagree about
        // whether exactly $600 is reportable. It is: the IRS rule is "$600 or more".
        const form  = build1099NEC(c, mine, year, business, compBases);
        const total = form ? form.box1 : necBasis(mine, compBases, c.id);
        const filing = filings.find((f) => f.form_type === 'form_1099_nec' && f.subject_id === c.id) || null;
        const last4 = taxIds?.[c.id]?.last4 || null;
        const missingTin = !last4;
        // Three reasons there is no form, and they are not the same sentence. A year with no
        // contractor days at all is not "below the threshold"; saying so would send the reader
        // looking for missing money.
        const noContractorDays = !!breakdown && breakdown.slices.every((sl) => sl.basis === 'w2');
        const belowThreshold = !form && !noContractorDays;
        return (
          <div key={c.id} className="card" style={{ opacity: form ? 1 : 0.55 }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 12 }}>
              <div>
                <div style={{ fontSize: 18, fontWeight: 700 }}>{c.full_name || c.creator_name}</div>
                <div style={{ color: 'var(--muted)', fontSize: 12 }}>
                  {missingTin
                    ? <span style={{ color: 'var(--orange)' }}>Missing TIN: add in Creator Setup to enable</span>
                    : <span>Ending in {last4}</span>}
                </div>
              </div>
              <Stat label="Box 1: NEC" value={`$${formatTaxAmount(total)}`} highlight={!belowThreshold} />
            </div>

            {breakdown && !(breakdown.slices.length === 1 && breakdown.slices[0].basis === '1099') && (
              <YearSplit breakdown={breakdown} />
            )}

            {noContractorDays ? (
              <div style={{ fontSize: 12, color: 'var(--muted)', marginTop: 8 }}>
                On wages all year. That pay is on a W-2 filed by the payroll provider, and Form 1065
                carries it on line 9. Nothing to issue here.
              </div>
            ) : belowThreshold ? (
              <div style={{ fontSize: 12, color: 'var(--muted)', marginTop: 8 }}>
                Below ${NEC_THRESHOLD} threshold for FY {year}: no 1099 required.
              </div>
            ) : missingTin ? (
              <div style={{ fontSize: 12, color: 'var(--orange)', marginTop: 8 }}>
                Add the creator's tax ID in Creator Setup before generating the 1099.
              </div>
            ) : (
              <>
                <FilingStatusStrip filing={filing} error={filingsError} onRetry={onFiled} onMarkFiled={() => setShowFor(c)} onUnfile={() => setUnfileFor(c)} busy={busyId === c.id} label="1099-NEC status" />
                <div style={{ display: 'flex', gap: 10 }}>
                  <button
                    className="btn btn-primary"
                    disabled={!Form1099NECDocument || downloadingId === c.id}
                    onClick={() => handleDownload(c, form)}
                  >
                    {!Form1099NECDocument ? 'Preparing PDF…'
                      : downloadingId === c.id ? 'Building PDF…'
                      : 'Download 1099-NEC PDF'}
                  </button>
                </div>
                {showFor?.id === c.id ? (
                  <MarkFiledModal busy={busyId === c.id} onClose={() => setShowFor(null)} onConfirm={(args) => handleFile(c, args)} />
                ) : null}
                {unfileFor?.id === c.id ? (
                  <UnfileModal filing={filing} busy={busyId === c.id} onClose={() => setUnfileFor(null)} onConfirm={(args) => handleUnfile(c, filing, args)} />
                ) : null}
              </>
            )}
          </div>
        );
      })}
    </div>
  );
}


function Stat({ label, value, highlight }) {
  return (
    <div>
      <div style={{ fontSize: 11, color: 'var(--muted)', textTransform: 'uppercase', letterSpacing: 1 }}>{label}</div>
      <div style={{ fontSize: 22, fontWeight: 700, color: highlight ? 'var(--orange)' : undefined, fontVariantNumeric: 'tabular-nums' }}>{value}</div>
    </div>
  );
}
