/**
 * components/admin/AgenciesView.js: admin CRUD view for brand/talent agencies.
 *
 * Lists agencies with per-agency campaign stats, their agents, and an add/edit
 * modal. Joins agency_types, contact_methods, and payment_terms for the dropdowns.
 * Substantial view (self-contained data + modal), not a wrapper.
 *
 * An agency has MANY agents (agency_contacts), edited here as a repeating list.
 * Row 0 is the primary: the contact an invoice bills when its campaign never
 * named an agent. Campaigns pick their own agent in CampaignsPage.
 *
 * @see schemas/SCHEMA.sql (agencies, agency_contacts, agency_types)
 * @see utils/invoicePdfModel.js (how the agent reaches the invoice Bill To)
 */
import React, { useState, useEffect, useRef } from 'react';
import { supabase } from '../../lib/supabase';
import { BuildingIcon, ChevronIcon, contactMethodIcon } from '../shared/Icon';
import { isValidEmail } from '../../utils/format';
import { humanizeError } from '../../utils/errors';
import { sortContacts, removedAgents } from '../../utils/agencyContacts';
import HelpIcon from '../shared/HelpIcon';
import Feedback from '../shared/Feedback';
import { useConfirm } from '../shared/ConfirmDialog';
import { useToast } from '../shared/Toast';
import RateCardEditor from '../shared/RateCardEditor';
import { mutate } from '../../utils/mutate';
import ReadError from '../shared/ReadError';
import EmptyState from '../shared/EmptyState';
import Modal, { ModalClose } from '../shared/Modal';
import Field from '../shared/Field';
import Loading from '../shared/Loading';
import SubmitButton from '../shared/SubmitButton';


/**
 * The preferred-contact glyph, shown only when it adds something.
 *
 * @gotcha an envelope next to a visible email address is decoration: it repeats
 *         what the address already says. The mark earns its place only when the
 *         method is NOT email, or when no email is on screen to imply it.
 * @param {string} method contact_methods.name
 * @param {boolean} [emailShown] whether the row already renders the address
 */
function MethodMark({ method, emailShown }) {
  if (emailShown && (method || '').toLowerCase() === 'email') return null;
  return contactMethodIcon(method, { size: 13, title: method ? `Preferred: ${method}` : undefined });
}

function IconLink({ href, title, children }) {
  return (
    <a href={href} target="_blank" rel="noreferrer" title={title} aria-label={title}
      style={{ display: 'flex', alignItems: 'center', color: 'var(--muted)', transition: 'color 0.15s' }}
      onMouseEnter={e => e.currentTarget.style.color = 'var(--white)'}
      onMouseLeave={e => e.currentTarget.style.color = 'var(--muted)'}>
      {children}
    </a>
  );
}

export default function AgenciesView() {
  const toast = useToast();
  const [agencies, setAgencies]             = useState([]);
  const [agencyTypes, setAgencyTypes]       = useState([]);
  const [contactMethods, setContactMethods] = useState([]);
  const [statsMap, setStatsMap]             = useState({});
  const [paymentTerms, setPaymentTerms]     = useState([]);
  const [loading, setLoading]               = useState(true);
  // The third state. The campaigns read is not decoration: it builds the per-creator campaign
  // and post counts each agency card states, so a refused one prints an agency with no work
  // beside a full history of it.
  const [loadError, setLoadError] = useState(null);
  const [showModal, setShowModal]           = useState(false);
  const [editing, setEditing]               = useState(null);
  // {id, name} for the open rate card panel; id null = the creator default card.
  const [ratesFor, setRatesFor]             = useState(null);

  useEffect(() => { fetchAll(); }, []);

  async function fetchAll() {
    setLoadError(null);
    const [aRes, cRes, tRes, atRes, cmRes] = await Promise.all([
      // @security not a table read. The contact and billing columns on `agencies` are revoked
      //           from `authenticated`, because both creators could read every
      //           agency's contact email, phone, billing address and VAT number, and an admin
      //           holds that same role so a column GRANT could not tell the two apart. This
      //           RPC asserts admin + AAL2 and returns the whole row with contacts embedded.
      //           @see schemas/SCHEMA.sql, get_agencies_admin
      supabase.rpc('get_agencies_admin'),
      supabase.from('campaigns').select(
        'id, agency_id, creator_profile_id, ' +
        'creator:profiles!campaigns_creator_profile_id_fkey(creator_name, full_name), ' +
        'campaign_deliverables(id)'
      ),
      supabase.from('payment_terms').select('id, name').eq('is_active', true).order('sort_order').order('name'),
      supabase.from('agency_types').select('id, name, requires_music_brief').order('sort_order').order('name'),
      supabase.from('contact_methods').select('id, name').eq('is_active', true).order('sort_order').order('name'),
    ]);
    const readError = aRes.error || cRes.error || tRes.error || atRes.error || cmRes.error;
    if (readError) {
      setLoadError(readError);
      setAgencies([]);
      setStatsMap({});
      setLoading(false);
      return;
    }
    setAgencies((aRes.data || []).map(a => ({ ...a, contacts: sortContacts(a.contacts) })));
    setPaymentTerms(tRes.data || []);
    setAgencyTypes(atRes.data || []);
    setContactMethods(cmRes.data || []);

    const map = {};
    for (const c of (cRes.data || [])) {
      if (!c.agency_id) continue;
      if (!map[c.agency_id]) map[c.agency_id] = {};
      const cid = c.creator_profile_id || 'unknown';
      if (!map[c.agency_id][cid]) {
        map[c.agency_id][cid] = {
          name: c.creator?.creator_name || c.creator?.full_name || 'Unknown',
          campaigns: 0,
          posts: 0,
        };
      }
      map[c.agency_id][cid].campaigns += 1;
      map[c.agency_id][cid].posts += (c.campaign_deliverables || []).length;
    }
    setStatsMap(map);
    setLoading(false);
  }

  async function toggleActive(a) {
    const { error } = await mutate(supabase.from('agencies').update({ is_active: !a.is_active }).eq('id', a.id));
    if (error) { toast.error(error); return; }
    fetchAll();
  }

  if (loading) return <div className="page"><Loading /></div>;
  if (loadError) return <div className="page"><ReadError error={loadError} onRetry={fetchAll} /></div>;

  return (
    <div className="page">
      <div className="page-header">
        <div>
          <h1 className="page-title">AGENCY SETUP<HelpIcon slug="agency-setup" /></h1>
          <div className="page-subtitle">Set up once, reuse across all campaigns</div>
        </div>
        <div className="flex items-center gap-8">
          {/* agencyId null opens the creator DEFAULT card: the one prospects
              see and the fallback for any dashboard that opts in. */}
          <button className="btn btn-ghost" onClick={() => setRatesFor({ id: null, name: 'Default rates' })}>Default rates</button>
          <button className="btn btn-primary" onClick={() => { setEditing(null); setShowModal(true); }}>+ New Agency</button>
        </div>
      </div>

      {agencies.length === 0 ? (
        <EmptyState icon={<BuildingIcon size={32} />}
                    title="No agencies yet"
                    text="Add your first agency or label" />
      ) : (
        <div className="table-wrap">
          <table className="pinned-actions" style={{ width: '100%' }}>
            <thead>
              <tr><th scope="col"></th><th scope="col">Name</th><th scope="col">Agents</th><th scope="col">Terms</th><th scope="col">Type</th><th scope="col">Activity</th><th scope="col">Status</th><th scope="col"></th></tr>
            </thead>
            <tbody>
              {agencies.map(a => {
                const creatorStats = Object.values(statsMap[a.id] || {});
                const hasStats = creatorStats.length > 0;
                const typeName = agencyTypes.find(t => t.id === a.agency_type_id)?.name;
                return (
                  <tr key={a.id} style={{ opacity: a.is_active ? 1 : 0.5 }}>
                    <td style={{ paddingRight: 0 }}>
                      <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                        {a.website ? (
                          <IconLink href={a.website} title={a.website}>
                            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                              <circle cx="12" cy="12" r="10"/><line x1="2" y1="12" x2="22" y2="12"/>
                              <path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"/>
                            </svg>
                          </IconLink>
                        ) : <span style={{ width: 14 }} />}
                        {a.portal_url ? (
                          <IconLink href={a.portal_url} title={`Portal: ${a.portal_url}`}>
                            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                              <path d="M15 3h4a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-4"/>
                              <polyline points="10 17 15 12 10 7"/>
                              <line x1="15" y1="12" x2="3" y2="12"/>
                            </svg>
                          </IconLink>
                        ) : <span style={{ width: 14 }} />}
                      </div>
                    </td>
                    <td style={{ fontWeight: 500 }}>{a.name}</td>
                    {/* Every agent listed, not just the primary: with several
                        people at one agency, "who do I email" is the question
                        this column exists to answer. */}
                    <td>
                      {a.contacts.length === 0 ? <span className="text-muted">—</span> : (
                        <div className="agent-cell">
                          {a.contacts.map(c => (
                            <div key={c.id} className="agent-cell-line">
                              {c.email ? (
                                <a href={`mailto:${c.email}`} className="link" style={{ fontWeight: 400 }}
                                  title={[c.email, c.phone].filter(Boolean).join('\n')}>{c.name}</a>
                              ) : <span>{c.name}</span>}
                              <MethodMark method={methodName(contactMethods, c.contact_method_id)} emailShown={!!c.email} />
                            </div>
                          ))}
                        </div>
                      )}
                    </td>
                    <td style={{ fontSize: 12, color: 'var(--muted)', whiteSpace: 'nowrap' }}>
                      {paymentTerms.find(t => t.id === a.payment_term_id)?.name || <span className="text-muted">—</span>}
                    </td>
                    <td style={{ fontSize: 12, color: 'var(--muted)' }}>
                      {typeName || <span className="text-muted">—</span>}
                    </td>
                    <td>
                      {hasStats ? (
                        <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
                          {creatorStats.map(s => (
                            <div key={s.name} style={{ fontSize: 12 }}>
                              <span style={{ fontWeight: 600, color: 'var(--muted)', marginRight: 6 }}>{s.name}</span>
                              <span style={{ color: 'var(--muted)' }}>
                                {s.campaigns} campaign{s.campaigns !== 1 ? 's' : ''} · {s.posts} post{s.posts !== 1 ? 's' : ''}
                              </span>
                            </div>
                          ))}
                        </div>
                      ) : (
                        <span className="text-muted">—</span>
                      )}
                    </td>
                    <td>
                      <div style={{ display: 'flex', flexDirection: 'column', gap: 4, alignItems: 'flex-start' }}>
                        <span className={`badge ${a.is_active ? 'badge-orange' : 'badge-red-soft'}`}>
                          {a.is_active ? 'Active' : 'Inactive'}
                        </span>
                        {isInvoiceReady(a)
                          ? <span style={{ fontSize: 9, color: 'var(--green)', fontWeight: 600, letterSpacing: 0.5 }}>● Invoice ready</span>
                          : <span style={{ fontSize: 9, color: 'var(--dim)' }}>No billing address</span>}
                      </div>
                    </td>
                    <td>
                      <div className="flex gap-8">
                        <button className="btn btn-ghost btn-sm" onClick={() => setRatesFor({ id: a.id, name: a.name })}>Rates</button>
                        <button className="btn btn-ghost btn-sm" onClick={() => { setEditing(a); setShowModal(true); }}>Edit</button>
                        <button className="btn btn-ghost btn-sm" onClick={() => toggleActive(a)}>{a.is_active ? 'Deactivate' : 'Activate'}</button>
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}

      {showModal && (
        <AgencyModal
          agency={editing}
          paymentTerms={paymentTerms}
          agencyTypes={agencyTypes}
          contactMethods={contactMethods}
          onClose={() => setShowModal(false)}
          onSaved={() => { setShowModal(false); fetchAll(); }}
        />
      )}

      {ratesFor && (
        <>
          {/* Click-away closes the rate panel. This is a .detail-panel-overlay,
              deliberately NOT a.modal-overlay: the app-wide backdrop-close ban
              applies to modals holding unsaved form state, and this editor saves
              on blur, so there is nothing to discard. */}
          <div className="detail-panel-overlay" onClick={() => setRatesFor(null)} />
          <RateCardEditor
            agencyId={ratesFor.id}
            agencyName={ratesFor.name}
            onClose={() => setRatesFor(null)}
          />
        </>
      )}

      <AgencyTypesSection types={agencyTypes} onChanged={fetchAll} />
      <ContactMethodsSection methods={contactMethods} onChanged={fetchAll} />
    </div>
  );
}

/** An empty agent row for a new agency or a freshly added line. */
function blankAgent() {
  return { name: '', email: '', phone: '', contact_method_id: '', is_primary: false };
}

/**
 * Trim the agent rows and drop the ones never typed into.
 *
 * @gotcha an appended-but-untouched row must not block the save with "every
 *         agent needs a name": clicking "+ Add agent" and changing your mind is
 *         not an error. Only rows carrying SOME content are validated.
 * @param {object[]} rows editor rows
 * @returns {object[]} trimmed rows worth persisting
 */
function cleanAgents(rows) {
  return rows
    .map(c => ({
      ...c,
      name:  (c.name  || '').trim(),
      email: (c.email || '').trim().toLowerCase(),
      phone: (c.phone || '').trim(),
    }))
    .filter(c => c.name || c.email || c.phone);
}

/**
 * The repeating agent list inside the agency modal: one expanded row at a time,
 * the rest collapsed to a scannable line.
 *
 * Position IS precedence. Row 0 is the primary, which is the contact an invoice
 * falls back to when a campaign never named an agent, so "Make primary" moves a
 * row to the top rather than setting a flag independent of the order. One
 * concept, visible on screen, instead of a hidden field that can disagree with
 * what you see.
 *
 * @param {object[]} props.contacts editor rows, each carrying a stable `_key`
 * @param {function} props.setContacts state setter for the rows
 * @param {object[]} props.contactMethods contact_methods lookup rows
 */
function AgentsEditor({ contacts, setContacts, contactMethods }) {
  // A brand-new agency opens with its only row expanded and ready to type into;
  // an existing agency opens fully collapsed, since you came to read, not edit.
  const [openKey, setOpenKey] = useState(() => (contacts.length === 1 && !contacts[0].id ? contacts[0]._key : null));
  const nextKey = useRef(0);

  function setC(key, patch) {
    setContacts(cs => cs.map(c => (c._key === key ? { ...c, ...patch } : c)));
  }
  function addAgent() {
    const key = `new-added-${nextKey.current++}`;
    setContacts(cs => [...cs, { ...blankAgent(), _key: key }]);
    setOpenKey(key);
  }
  function removeAgent(key) {
    setContacts(cs => cs.filter(c => c._key !== key));
    setOpenKey(null);
  }
  function makePrimary(key) {
    setContacts(cs => [...cs.filter(c => c._key === key), ...cs.filter(c => c._key !== key)]);
  }

  return (
    <div className="form-group">
      <div className="form-label">Agents</div>
      <div className="agent-list">
        {contacts.map((c, i) => {
          const open = c._key === openKey;
          const method = methodName(contactMethods, c.contact_method_id);
          return (
            <div key={c._key} className={`agent-row${open ? ' agent-row-open' : ''}`}>
              <button type="button" className="agent-row-head" onClick={() => setOpenKey(open ? null : c._key)}>
                <ChevronIcon size={11} className={`agent-row-caret${open ? ' agent-row-caret-open' : ''}`} />
                <span className="agent-row-name">{c.name.trim() || <span className="text-muted">New agent</span>}</span>
                {!open && c.email && <span className="agent-row-meta">{c.email}</span>}
                {!open && <MethodMark method={method} emailShown={!!c.email} />}
                {i === 0 && contacts.length > 1 && <span className="agent-row-tag">Primary</span>}
              </button>
              {open && (
                <div className="agent-row-body">
                  <div className="form-row">
                    <div className="form-group">
                      <div className="form-label">Name *</div>
                      <input aria-label="Agent name" className="form-input" value={c.name} maxLength={120} autoFocus
                        onChange={e => setC(c._key, { name: e.target.value })} placeholder="Vasily Guzhov" />
                    </div>
                    <div className="form-group">
                      <div className="form-label">Email</div>
                      <input aria-label="Agent email" className="form-input" type="email" value={c.email || ''} maxLength={254}
                        onChange={e => setC(c._key, { email: e.target.value })} />
                    </div>
                  </div>
                  <div className="form-row">
                    <div className="form-group">
                      <div className="form-label">Phone</div>
                      <input aria-label="Agent phone" className="form-input" value={c.phone || ''} maxLength={30}
                        onChange={e => setC(c._key, { phone: e.target.value })} />
                    </div>
                    <div className="form-group">
                      <div className="form-label">Preferred Contact</div>
                      <select aria-label="Preferred contact method" className="form-select" value={c.contact_method_id || ''}
                        onChange={e => setC(c._key, { contact_method_id: e.target.value })}>
                        <option value="">Select…</option>
                        {contactMethods.map(m => <option key={m.id} value={m.id}>{m.name}</option>)}
                      </select>
                    </div>
                  </div>
                  <div className="agent-row-actions">
                    {i > 0 && (
                      <button type="button" className="btn btn-ghost btn-sm"
                        onClick={() => makePrimary(c._key)}>Make primary</button>
                    )}
                    {contacts.length > 1 && (
                      <button type="button" className="btn btn-ghost btn-sm"
                        onClick={() => removeAgent(c._key)}>Remove</button>
                    )}
                  </div>
                </div>
              )}
            </div>
          );
        })}
      </div>
      <button type="button" className="btn btn-secondary btn-sm agent-add" onClick={addAgent}>+ Add agent</button>
    </div>
  );
}

/** Resolve a contact_methods id to its name, for the method glyph. */
function methodName(methods, id) {
  return methods.find(m => m.id === id)?.name || '';
}

/** True when the agency has enough address fields to appear on an invoice. */
function isInvoiceReady(a) {
  return !!(a?.street_address && a?.city && a?.postal_code);
}

/** Add/edit agency form. agency=null creates; otherwise edits in place. */
function AgencyModal({ agency, paymentTerms, agencyTypes, contactMethods, onClose, onSaved }) {
  const toast = useToast();
  const askConfirm = useConfirm();
  const [form, setForm] = useState({
    name:                 agency?.name                 || '',
    website:              agency?.website              || '',
    portal_url:           agency?.portal_url           || '',
    payment_term_id:      agency?.payment_term_id      || paymentTerms[0]?.id || '',
    agency_type_id:       agency?.agency_type_id       || '',
    notes:                agency?.notes                || '',
    billing_name:         agency?.billing_name         || '',
    billing_contact_name: agency?.billing_contact_name || '',
    street_address:       agency?.street_address       || '',
    city:                 agency?.city                 || '',
    state_province:       agency?.state_province       || '',
    postal_code:          agency?.postal_code          || '',
    country:              agency?.country              || '',
    company_reg_number:   agency?.company_reg_number   || '',
    vat_number:           agency?.vat_number           || '',
  });
  // A brand-new agency starts with one blank agent rather than an empty list:
  // every agency has at least one, and an empty list would make the first thing
  // you must do also the thing you have to discover.
  const [contacts, setContacts] = useState(() =>
    (agency?.contacts?.length ? agency.contacts : [blankAgent()]).map((c, i) => ({ ...c, _key: c.id || `new-${i}` })));
  const [billingOpen, setBillingOpen] = useState(!!(agency?.street_address));
  const [saving, setSaving] = useState(false);
  const [error, setError]   = useState('');

  function normalizeUrl(url) {
    const trimmed = url.trim();
    if (!trimmed) return null;
    const withProto = /^https?:\/\//i.test(trimmed) ? trimmed : `https://${trimmed}`;
    try {
      const parsed = new URL(withProto);
      if (!['http:', 'https:'].includes(parsed.protocol)) return null;
      return withProto;
    } catch { return null; }
  }

  /**
   * Persist the agent rows against an agency: delete what was removed, then
   * write each remaining row with its index as sort_order.
   *
   * @gotcha uniq_primary_contact_per_agency is a PARTIAL unique index, so
   *         promoting the new primary before demoting the old one collides.
   *         Every existing primary is cleared first, in its own statement.
   * @param {string} agencyId
   * @returns {Promise<object|null>} the first supabase error, or null
   */
  async function saveContacts(agencyId) {
    const rows = cleanAgents(contacts);
    const keptIds = rows.filter(r => r.id).map(r => r.id);
    const removed = (agency?.contacts || []).filter(c => !keptIds.includes(c.id)).map(c => c.id);

    if (removed.length) {
      const { error: delErr } = await supabase.from('agency_contacts').delete().in('id', removed);
      if (delErr) return delErr;
    }
    const { error: clearErr } = await supabase.from('agency_contacts')
      .update({ is_primary: false }).eq('agency_id', agencyId).eq('is_primary', true);
    if (clearErr) return clearErr;

    for (let i = 0; i < rows.length; i++) {
      const r = rows[i];
      const payload = {
        agency_id:         agencyId,
        name:              r.name,
        email:             r.email || null,
        phone:             r.phone || null,
        contact_method_id: r.contact_method_id || null,
        is_primary:        i === 0,
        sort_order:        i,
      };
      const { error: rowErr } = r.id
        ? await supabase.from('agency_contacts').update(payload).eq('id', r.id)
        : await supabase.from('agency_contacts').insert(payload);
      if (rowErr) return rowErr;
    }
    return null;
  }

  async function save() {
    const errors = [];
    if (!form.name.trim()) errors.push('Agency name is required.');
    const agents = cleanAgents(contacts);
    if (agents.some(c => !c.name)) errors.push('Every agent needs a name.');
    const badEmail = agents.find(c => c.email && !isValidEmail(c.email));
    if (badEmail) errors.push(`${badEmail.name || 'An agent'} has an invalid email address.`);
    if (errors.length) { setError(errors.join(' ')); return; }

    // Removing an agent row is a DELETE, and it looks like a local edit: the same Remove
    // discards an unsaved blank row, so the gesture reads as reversible. saveContacts then
    // destroys every stored id the list has dropped. Ask before ANY of it, the agency's own
    // columns included, or declining leaves half the form committed.
    const dropping = removedAgents(agency?.contacts, agents);
    if (dropping.length) {
      const named = dropping.map(c => c.name).filter(Boolean).join(', ');
      const ok = await askConfirm({
        title: dropping.length === 1 ? `Remove ${named || 'this agent'}?` : `Remove ${dropping.length} agents?`,
        body: `${named || 'They'} will be deleted from ${form.name.trim() || 'this agency'}. Campaigns already billed to them keep their invoices. This cannot be undone.`,
        danger: true,
        confirmLabel: 'Remove and save',
      });
      if (!ok) return;
    }

    setSaving(true);
    setError('');
    const payload = {
      ...form,
      name:                 form.name.trim(),
      notes:                form.notes.trim() || null,
      website:              normalizeUrl(form.website),
      portal_url:           normalizeUrl(form.portal_url),
      agency_type_id:       form.agency_type_id || null,
      billing_name:         form.billing_name.trim() || null,
      billing_contact_name: form.billing_contact_name.trim() || null,
      street_address:       form.street_address.trim() || null,
      city:                 form.city.trim() || null,
      state_province:       form.state_province.trim() || null,
      postal_code:          form.postal_code.trim() || null,
      country:              form.country.trim() || null,
      company_reg_number:   form.company_reg_number.trim() || null,
      vat_number:           form.vat_number.trim() || null,
    };
    let agencyId = agency?.id;
    if (agency) {
      const { error: upErr } = await supabase.from('agencies').update(payload).eq('id', agency.id);
      if (upErr) { setError(humanizeError(upErr)); setSaving(false); return; }
    } else {
      const { data, error: insErr } = await supabase.from('agencies').insert(payload).select('id').single();
      if (insErr) { setError(humanizeError(insErr)); setSaving(false); return; }
      agencyId = data.id;
    }

    const contactErr = await saveContacts(agencyId);
    if (contactErr) { setError(humanizeError(contactErr)); setSaving(false); return; }

    setSaving(false);
    toast.success(agency ? 'Agency updated' : 'Agency added');
    onSaved();
  }

  return (
    <Modal
      title={agency ? 'EDIT AGENCY' : 'NEW AGENCY'}
      /* 560, not the usual 480: a collapsed agent line carries name + email +
         method on ONE row, and 480 wrapped it into two. */
      size="md"
      onClose={onClose}
    >
        <div className="modal-body">
          {error && <Feedback value={error} style={{ marginBottom: 16 }} />}
          <Field label="Agency / Label Name *">{(id) => (<>
            <input id={id} className="form-input" value={form.name} maxLength={120} onChange={e => setForm(f => ({ ...f, name: e.target.value }))} placeholder="YTK Media" />
          </>)}</Field>
          <AgentsEditor contacts={contacts} setContacts={setContacts} contactMethods={contactMethods} />
          <div className="form-row">
            <Field label="Website">{(id) => (<>
              <input id={id} className="form-input" value={form.website} maxLength={500} onChange={e => setForm(f => ({ ...f, website: e.target.value }))} placeholder="ytkmedia.com" />
            </>)}</Field>
            <Field label="Portal URL">{(id) => (<>
              <input id={id} className="form-input" value={form.portal_url} maxLength={500} onChange={e => setForm(f => ({ ...f, portal_url: e.target.value }))} placeholder="creator-portal.agency.com" />
            </>)}</Field>
          </div>
          <div className="form-row">
            <Field label="Payment Terms">{(id) => (<>
              <select id={id} className="form-select" value={form.payment_term_id} onChange={e => setForm(f => ({ ...f, payment_term_id: e.target.value }))}>
                <option value="">Select…</option>
                {paymentTerms.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}
              </select>
            </>)}</Field>
            <Field label="Type">{(id) => (<>
              <select id={id} className="form-select" value={form.agency_type_id} onChange={e => setForm(f => ({ ...f, agency_type_id: e.target.value }))}>
                <option value="">Select…</option>
                {agencyTypes.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}
              </select>
            </>)}</Field>
          </div>
          <div style={{ borderTop: '1px solid var(--border)', marginTop: 8, paddingTop: 16 }}>
            <button
              type="button"
              style={{ display: 'flex', alignItems: 'center', gap: 8, background: 'none', border: 'none', padding: 0, cursor: 'pointer', marginBottom: billingOpen ? 16 : 0, width: '100%' }}
              onClick={() => setBillingOpen(o => !o)}
            >
              <span style={{ fontSize: 9, fontWeight: 600, textTransform: 'uppercase', letterSpacing: 2, color: 'var(--muted)' }}>Billing Details</span>
              <span style={{ fontSize: 10, color: 'var(--dim)', marginLeft: 'auto' }}>{billingOpen ? '▲' : '▼'}</span>
              {isInvoiceReady(form)
                ? <span style={{ fontSize: 9, fontWeight: 600, color: 'var(--green)', textTransform: 'uppercase', letterSpacing: 1 }}>● Invoice ready</span>
                : <span style={{ fontSize: 9, color: 'var(--orange2)', textTransform: 'uppercase', letterSpacing: 1 }}>Needs address</span>}
            </button>
            {billingOpen && (
              <>
                <Field label={<>Legal / Billing Name <span style={{ color: 'var(--dim)', fontWeight: 400 }}>(if different from display name)</span></>}>{(id) => (<>
                  <input id={id} className="form-input" value={form.billing_name} maxLength={120} onChange={e => setForm(f => ({ ...f, billing_name: e.target.value }))} placeholder="un:hurd music LTD" />
                </>)}</Field>
                <Field label={<>Billing Contact Name <span style={{ color: 'var(--dim)', fontWeight: 400 }}>(if different from contact)</span></>}>{(id) => (<>
                  <input id={id} className="form-input" value={form.billing_contact_name} maxLength={120} onChange={e => setForm(f => ({ ...f, billing_contact_name: e.target.value }))} placeholder="Danny Smith" />
                </>)}</Field>
                <Field label="Street Address">{(id) => (<>
                  <input id={id} className="form-input" value={form.street_address} maxLength={200} onChange={e => setForm(f => ({ ...f, street_address: e.target.value }))} placeholder="16 Blackfriars Street" />
                </>)}</Field>
                <div className="form-row">
                  <Field label="City">{(id) => (<>
                    <input id={id} className="form-input" value={form.city} maxLength={100} onChange={e => setForm(f => ({ ...f, city: e.target.value }))} placeholder="Manchester" />
                  </>)}</Field>
                  <Field label="State / County / Province">{(id) => (<>
                    <input id={id} className="form-input" value={form.state_province} maxLength={100} onChange={e => setForm(f => ({ ...f, state_province: e.target.value }))} placeholder="Greater Manchester" />
                  </>)}</Field>
                </div>
                <div className="form-row">
                  <Field label="Postal / ZIP Code">{(id) => (<>
                    <input id={id} className="form-input" value={form.postal_code} maxLength={20} onChange={e => setForm(f => ({ ...f, postal_code: e.target.value }))} placeholder="M3 5BQ" />
                  </>)}</Field>
                  <Field label="Country">{(id) => (<>
                    <input id={id} className="form-input" value={form.country} maxLength={100} onChange={e => setForm(f => ({ ...f, country: e.target.value }))} placeholder="United Kingdom" />
                  </>)}</Field>
                </div>
                <div className="form-row">
                  <Field label="Business Reg. No.">{(id) => (<>
                    <input id={id} className="form-input" value={form.company_reg_number} maxLength={50} onChange={e => setForm(f => ({ ...f, company_reg_number: e.target.value }))} placeholder="e.g. Company No. (UK), EIN (US), ABN (AU)" />
                  </>)}</Field>
                  <Field label="Tax / VAT / GST No.">{(id) => (<>
                    <input id={id} className="form-input" value={form.vat_number} maxLength={50} onChange={e => setForm(f => ({ ...f, vat_number: e.target.value }))} placeholder="e.g. VAT No. (UK/EU), GST No. (AU/CA)" />
                  </>)}</Field>
                </div>
              </>
            )}
          </div>

          <Field label="Notes" style={{ marginTop: 8 }}>{(id) => (<>
            <textarea id={id} className="form-textarea" value={form.notes} maxLength={2000} onChange={e => setForm(f => ({ ...f, notes: e.target.value }))} />
          </>)}</Field>
        </div>
        <div className="modal-footer">
          <ModalClose className="btn btn-ghost">Cancel</ModalClose>
          <SubmitButton saving={saving} className="btn btn-primary" onClick={save} disabled={saving || !form.name}>Save</SubmitButton>
        </div>
    </Modal>
  );
}

/**
 * Generic inline CRUD list over a small lookup table (agency_types,
 * contact_methods). Renames/deletes write straight to `tableName`.
 */
function InlineListSection({ title, emptyText, addPlaceholder, addLabel, items, tableName, onChanged, rowExtra }) {
  const toast = useToast();
  const askConfirm = useConfirm();
  const [drafts, setDrafts]   = useState({});
  const [newName, setNewName] = useState('');
  const [showAdd, setShowAdd] = useState(false);
  const addInputRef = useRef(null);

  useEffect(() => {
    if (showAdd && addInputRef.current) addInputRef.current.focus();
  }, [showAdd]);

  function getDraft(item) {
    return drafts[item.id] !== undefined ? drafts[item.id] : item.name;
  }

  async function saveItem(item) {
    const name = (drafts[item.id] ?? item.name).trim();
    if (!name || name === item.name) return;
    const { error } = await mutate(supabase.from(tableName).update({ name }).eq('id', item.id));
    if (error) { toast.error(error); return; }
    onChanged();
  }

  async function deleteItem(item) {
    if (!(await askConfirm({ title: `Delete "${item.name}"?`, body: 'This cannot be undone.', danger: true }))) return;
    const { error } = await mutate(supabase.from(tableName).delete().eq('id', item.id));
    if (error) { toast.error(error); return; }
    onChanged();
  }

  async function addItem() {
    if (!newName.trim()) return;
    const { error } = await mutate(supabase.from(tableName).insert({ name: newName.trim(), sort_order: items.length }));
    if (error) { toast.error(error); return; }
    setNewName('');
    setShowAdd(false);
    onChanged();
  }

  return (
    <div style={{ marginTop: 48, paddingTop: 24, borderTop: '1px solid var(--border)' }}>
      <div style={{ fontSize: 9, fontWeight: 600, textTransform: 'uppercase', letterSpacing: 2, color: 'var(--muted)', marginBottom: 16 }}>
        {title}
      </div>

      {items.length === 0 && !showAdd && (
        <EmptyState variant="note" text={emptyText} />
      )}

      {items.map(item => (
        <div key={item.id} className="flex items-center gap-8" style={{ marginBottom: 8 }}>
          <input
            className="form-input"
            style={{ maxWidth: 280 }}
            aria-label={`Rename ${item.name}`}
            value={getDraft(item)}
            maxLength={80}
            onChange={e => setDrafts(d => ({ ...d, [item.id]: e.target.value }))}
            onBlur={() => saveItem(item)}
            onKeyDown={e => { if (e.key === 'Enter') e.target.blur(); }}
          />
          {rowExtra && rowExtra(item)}
          <button className="btn btn-ghost btn-sm" onClick={() => deleteItem(item)} style={{ color: 'var(--red)', flexShrink: 0, marginLeft: 'auto' }}>
            Delete
          </button>
        </div>
      ))}

      {showAdd && (
        <div className="flex items-center gap-8" style={{ marginBottom: 8 }}>
          <input
            ref={addInputRef}
            className="form-input"
            style={{ maxWidth: 280 }}
            aria-label={addLabel.replace(/^\+\s*/, '')}
            value={newName}
            maxLength={80}
            placeholder={addPlaceholder}
            onChange={e => setNewName(e.target.value)}
            onKeyDown={e => {
              if (e.key === 'Enter') addItem();
              if (e.key === 'Escape') { setShowAdd(false); setNewName(''); }
            }}
          />
          <button className="btn btn-primary btn-sm" onClick={addItem} disabled={!newName.trim()}>Add</button>
          <button className="btn btn-ghost btn-sm" onClick={() => { setShowAdd(false); setNewName(''); }}>Cancel</button>
        </div>
      )}

      {!showAdd && (
        <button className="btn btn-ghost btn-sm" style={{ marginTop: 4 }} onClick={() => setShowAdd(true)}>
          {addLabel}
        </button>
      )}
    </div>
  );
}

/**
 * Whether this type of agency briefs a contracted sound.
 *
 * Follows the row grammar every other settings list in the hub already uses
 * (PaymentSetupView methods / destinations / terms, WorkflowSetupView statuses):
 * the current state as muted text, then a `btn btn-ghost btn-sm` labelled with
 * the ACTION it performs, then Delete. Same shape as Active / Deactivate.
 *
 * @gotcha The button says what will happen, not what is true. "Make optional"
 *         appears while the type still requires a sound, matching Deactivate
 *         appearing on an active row. Labelling it with the state instead reads
 *         as a status pill and gets clicked by accident.
 * @gotcha Optimistic. The write is one boolean on a three-row lookup table and
 *         waiting on a round trip to redraw two words reads as lag. A failure
 *         reverts and says so.
 */
function MusicBriefToggle({ type, onChanged }) {
  const toast = useToast();
  const [on, setOn] = useState(type.requires_music_brief !== false);
  const [busy, setBusy] = useState(false);

  // A refetch from the parent is the source of truth again.
  useEffect(() => { setOn(type.requires_music_brief !== false); }, [type.requires_music_brief]);

  async function toggle() {
    const next = !on;
    setOn(next);
    setBusy(true);
    const { error } = await supabase
      .from('agency_types').update({ requires_music_brief: next }).eq('id', type.id);
    setBusy(false);
    if (error) {
      setOn(!next);
      const h = humanizeError(error);
      toast.error({ title: h?.title || 'Could not save', body: h?.body });
      return;
    }
    onChanged();
  }

  return (
    <>
      <span style={{ fontSize: 12, color: 'var(--muted)', whiteSpace: 'nowrap', flexShrink: 0 }}>
        {on ? 'Sound required' : 'Sound optional'}
      </span>
      <button
        className="btn btn-ghost btn-sm"
        disabled={busy}
        onClick={toggle}
        style={{ flexShrink: 0 }}
        title={on
          ? 'Creators may then post without a briefed sound, but must confirm none was sent'
          : 'Creators must then supply the briefed sound before they can post'}
      >
        {on ? 'Make optional' : 'Make required'}
      </button>
    </>
  );
}

