/**
 * components/shared/PayrollTab.js: the month, and where it is settled.
 *
 * Financials -> Payroll. Opened monthly: read the gross wage per creator, type it into Gusto,
 * come back with the tax it kept, record the paycheck, and mark it paid when the money leaves.
 * Admin-only. The month is the frame; one creator's month is `PayrollPaycheck.js`, and the
 * month's own last beat, the tax Gusto pulls in a second debit, is `PayrollTaxRemittance.js`.
 *
 * A dollar belongs to the month the AGENCY's cash landed, because payroll pays the preceding
 * month's receipts. In-kind has no cash date and buckets on coalesce(invoice_date, created_at).
 * @invariant a month a creator has ALREADY been paid for is never offered for settlement. The
 *            per-invoice payouts of January to July 2026 render as the read-only register they
 *            always did, and a monthly paycheck that exists renders as itself. Only a month
 *            with neither is open. `buildPayrollMonth` decides which, from the data.
 * @invariant cash that resolves to no creator blocks the WHOLE month and no figures render.
 *            Nobody can be paid it, so any settlement built around it is short by that much.
 * @see utils/payroll.js; components/shared/PayrollPaycheck.js; docs/MONEY.md 10.0c
 */
import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { supabase } from '../../lib/supabase';
import { fmtMoney, fmtMonth } from '../../utils/format';
import { humanizeError } from '../../utils/errors';
import { lastMonth, thisMonth } from '../../utils/period';
import { PAYROLL_SPLIT_SELECT, buildPayrollMonth } from '../../utils/payroll';
import { fetchCompBases } from '../../utils/compBasis';
import { ChevronIcon, WarningIcon, ArrowRightIcon } from './Icon';
import Feedback from './Feedback';
import EmptyState from './EmptyState';
import HelpIcon from './HelpIcon';
import Skeleton from './Skeleton';
import { FigureLink, RegisterRow } from './PayrollFigures';
import PayrollBreakdown, { collectedBreakdown } from './PayrollBreakdown';
import PayrollPaycheck from './PayrollPaycheck';
import PayrollTaxRemittance from './PayrollTaxRemittance';
import { campaignLabel, rewardLabel } from '../../utils/campaignLabel';

const log = (...args) => {
  if (process.env.NODE_ENV !== 'production') console.error('[PayrollTab]', ...args);
};

/** Month arithmetic on 'YYYY-MM' strings, never Date objects (UTC off-by-one). */
function shiftMonth(ym, delta) {
  const [y, m] = ym.split('-').map(Number);
  const total = y * 12 + (m - 1) + delta;
  return `${Math.floor(total / 12)}-${String((total % 12) + 1).padStart(2, '0')}`;
}
const monthStart = (ym) => `${ym}-01`;
const monthEnd   = (ym) => `${shiftMonth(ym, 1)}-01`;

/**
 * Invoices standing between the reader and a figure, deep-linked to where they get fixed.
 * Two callers with the same shape and two different reasons, which is why the copy is theirs.
 */
function InvoiceGaps({ invoices, onOpen }) {
  return (
    <ul className="payroll-gaps">
      {invoices.map((inv) => (
        <li key={inv.id}>
          <button type="button" className="payroll-gap" onClick={() => onOpen(inv)}
                  disabled={!inv.campaign_id}>
            <span className="payroll-gap-brand">{inv.brand}</span>
            <span className="payroll-gap-ref">{inv.invoice_number || '—'}</span>
            <span className="payroll-gap-amt">{fmtMoney(inv.invoice_amount)}</span>
            {inv.campaign_id && <ArrowRightIcon size={11} />}
          </button>
        </li>
      ))}
    </ul>
  );
}

/**
 * Half her month is on the old per-invoice path and half is not, so neither shape is honest.
 * Settling would pay the unallocated half twice; the register would understate it.
 */
function MixedRow({ row, onOpenInvoice }) {
  const name = row.profile.full_name || row.profile.creator_name || 'Unnamed';
  return (
    <div className="payroll-row">
      <div className="payroll-row-head">
        <h4 className="payroll-name">{name}</h4>
      </div>
      <section className="payroll-blocked">
        <h4 className="payroll-blocked-title">
          <WarningIcon size={13} />
          Finish this month the way it was started
        </h4>
        <p className="payroll-blocked-body">
          Some of {name}&apos;s cash this month is already on a per-invoice payout and some is not.
          A monthly paycheck would pay the unallocated half a second time, so allocate what is
          left below and the month will settle the way the rest of it did.
        </p>
        <InvoiceGaps invoices={row.unallocated} onOpen={onOpenInvoice} />
      </section>
    </div>
  );
}

/**
 * A creator on a 1099 this month. Routine, not a problem, so it is the quietest thing on the
 * screen: she keeps her place in the month and her cash is accounted for, without a figure
 * competing with the gross wage that somebody actually has to retype.
 *
 * @gotcha the amount is `collected`, never the split totals a register reads. Her month may
 *         hold invoices nobody has allocated yet, and those splits do not exist to be summed.
 */
function ContractorRow({ row, month, onOpenInvoice, onOpenBreakdown }) {
  const name = row.profile.full_name || row.profile.creator_name || 'Unnamed';
  return (
    <div className="payroll-row">
      <div className="payroll-row-head">
        <h4 className="payroll-name">{name}</h4>
      </div>
      <p className="payroll-shared">
        <FigureLink
          amount={row.collected} label="cash collected"
          onClick={() => onOpenBreakdown(collectedBreakdown({
            name, month, invoices: row.invoices, total: row.collected,
          }))}
        /> collected, settled
        one invoice at a time on Payments. She is on a 1099 this month, so none of it goes into Gusto.
      </p>
      {row.unallocated.length > 0 && (
        <InvoiceGaps invoices={row.unallocated} onOpen={onOpenInvoice} />
      )}
    </div>
  );
}

/**
 * Her classification changed partway through the month, so the month is neither wages nor
 * contract work and cannot honestly be settled as either.
 *
 * @gotcha this is Kym's real December 2027, not a hypothetical: the exemption ends on her
 *         eighteenth birthday, the twelfth. A paycheck settles a whole month in ONE entry that
 *         is immutable once posted, so guessing which side to file it under is not recoverable.
 */
function SplitMonthRow({ row, month, onOpenInvoice }) {
  const name = row.profile.full_name || row.profile.creator_name || 'Unnamed';
  return (
    <div className="payroll-row">
      <div className="payroll-row-head">
        <h4 className="payroll-name">{name}</h4>
      </div>
      <section className="payroll-blocked">
        <h4 className="payroll-blocked-title">
          <WarningIcon size={13} />
          {fmtMonth(month)} changed how {name} is paid
        </h4>
        <p className="payroll-blocked-body">
          She moved between a 1099 and a W-2 partway through the month, so part of this cash is
          wages and part is not. A paycheck settles the whole month in one entry that cannot be
          edited once it posts, so there is no safe half to put it in. Settle these on Payments
          instead, or move the change to the first of a month.
        </p>
        {row.unallocated.length > 0 && (
          <InvoiceGaps invoices={row.unallocated} onOpen={onOpenInvoice} />
        )}
      </section>
    </div>
  );
}

/**
 * @param {object} props
 * @param {string} [props.initialMonth] - 'YYYY-MM', from a ledger line that resolved to a
 *        monthly paycheck. @see utils/ledgerSourceLink.js
 */
export default function PayrollTab({ initialMonth }) {
  const [month, setMonth] = useState(() => initialMonth || lastMonth());
  const [state, setState] = useState({ loading: true, error: null, data: null });
  // One panel for the whole month, held here rather than in each band: two `.detail-panel`s are
  // both fixed to the right edge and would sit on top of one another.
  const [breakdown, setBreakdown] = useState(null);
  const [isMobile, setIsMobile] = useState(() => window.matchMedia('(max-width: 768px)').matches);

  useEffect(() => {
    const mq = window.matchMedia('(max-width: 768px)');
    const onChange = (e) => setIsMobile(e.matches);
    mq.addEventListener('change', onChange);
    return () => mq.removeEventListener('change', onChange);
  }, []);

  const isOpenMonth = month >= thisMonth();

  const load = useCallback(async () => {
    setState((s) => ({ ...s, loading: true, error: null }));

    const from = monthStart(month);
    const to   = monthEnd(month);

    const OWNER = 'campaign:campaigns(id, campaign_name, display_name, creator_profile_id, agency:agencies(name)), '
                + 'reward:platform_reward_entries(id, profile_id, period_month, '
                + 'program:platform_rewards_programs(name))';

    // Four separate queries, because the four kinds are keyed by different things. Cash
    // invoices belong to the month their money LANDED. In-kind never has money, so
    // you_received stays false and payment_received_date stays null forever: filtering on
    // either drops every one of them, which is exactly what hid the in-kind line. A monthly
    // paycheck is keyed by the period alone and names no invoice at all.
    const [invRes, kindRes, creatorRes, payRes, compRes] = await Promise.all([
      supabase.from('invoices')
        .select(`id, invoice_number, invoice_amount, amount_received, payment_received_date, ${OWNER}`)
        .eq('you_received', true).eq('is_in_kind', false)
        .gte('payment_received_date', from).lt('payment_received_date', to),
      supabase.from('invoices')
        .select(`id, invoice_amount, in_kind_value, invoice_date, created_at, ${OWNER}`)
        .eq('is_in_kind', true),
      supabase.from('profiles')
        .select('id, full_name, creator_name')
        .eq('role', 'creator').order('full_name'),
      supabase.from('creator_payouts')
        .select('id, profile_id, payroll_period, withholding_amount, payout_amount, payout_date, payout_notes')
        .eq('payroll_period', from),
      // Who is on wages this month. Refused, the month cannot be built at all rather than
      // built with everyone reading as a contractor. @see utils/compBasis.js
      fetchCompBases(supabase),
    ]);

    const readErr = invRes.error || kindRes.error || creatorRes.error || payRes.error || compRes.error;
    if (readErr) {
      log('load', readErr);
      setState({ loading: false, error: humanizeError(readErr), data: null });
      return;
    }

    const creators = creatorRes.data || [];
    const nameOf = (id) => {
      const c = creators.find((x) => x.id === id);
      return c ? (c.creator_name || c.full_name || '') : '';
    };
    const cashInvoices = (invRes.data || []).map((i) => {
      const creatorId = i.campaign?.creator_profile_id || i.reward?.profile_id || null;
      return {
        id: i.id,
        invoice_number: i.invoice_number,
        invoice_amount: Number(i.invoice_amount) || 0,
        // The advance guard sums amount_received, so the settlement has to as well.
        amount_received: Number(i.amount_received) || 0,
        payment_received_date: i.payment_received_date || null,
        campaign_id: i.campaign?.id || null,
        // A reward payout links by reward_entry_id, not invoice_id. Carry it so
        // the payout lookup below can resolve those back to this invoice.
        reward_entry_id: i.reward?.id || null,
        creator_id: creatorId,
        // Branch on WHICH thing the invoice points at, never on whether the campaign label
        // came back empty: `campaignLabel` answers an em dash for a missing campaign, which is
        // truthy, so an `||` chain names every reward payment "—".
        brand: i.campaign
          ? (i.campaign.agency?.name || campaignLabel(i.campaign))
          : (rewardLabel(i.reward)
             || [nameOf(creatorId), 'platform reward'].filter(Boolean).join(' ')),
      };
    });
    // In-kind is bucketed client-side on invoice_date, falling back to the row's
    // creation date: some in-kind rows carry no invoice_date at all, and without
    // the fallback those products would never appear in any month.
    const inKindTotals = {};
    for (const i of kindRes.data || []) {
      const day = (i.invoice_date || i.created_at || '').slice(0, 10);
      if (!day || day < from || day >= to) continue;
      const pid = i.campaign?.creator_profile_id || i.reward?.profile_id;
      if (!pid) continue;
      const fmv = Number(i.in_kind_value) || Number(i.invoice_amount) || 0;
      inKindTotals[pid] = (inKindTotals[pid] || 0) + fmv;
    }

    // Payouts first, then splits by payout_id. Deliberately NOT one query
    // filtering on the embedded payout: filtering through an embed is the
    // documented silent-failure trap on this table, and getting it wrong here
    // would zero somebody's wages rather than error.
    // A campaign payout carries invoice_id; a REWARD payout carries
    // reward_entry_id and leaves invoice_id NULL. Matching on invoice_id alone
    // reported every reward invoice as unallocated and blocked every month.
    let payouts = [];
    let splits = [];
    if (cashInvoices.length) {
      const invoiceIds   = cashInvoices.map((i) => i.id);
      const rewardIds    = cashInvoices.map((i) => i.reward_entry_id).filter(Boolean);
      const invoiceByReward = new Map(
        cashInvoices.filter((i) => i.reward_entry_id).map((i) => [i.reward_entry_id, i.id])
      );

      const { data: poRows, error: poErr } = await supabase
        .from('creator_payouts')
        .select('id, invoice_id, reward_entry_id')
        .or([
          `invoice_id.in.(${invoiceIds.join(',')})`,
          rewardIds.length ? `reward_entry_id.in.(${rewardIds.join(',')})` : null,
        ].filter(Boolean).join(','));
      if (poErr) {
        log('payouts', poErr);
        setState({ loading: false, error: humanizeError(poErr), data: null });
        return;
      }

      payouts = (poRows || []).map((p) => ({
        id: p.id,
        invoice_id: p.invoice_id || invoiceByReward.get(p.reward_entry_id) || null,
      }));

      if (payouts.length) {
        const { data, error } = await supabase
          .from('payout_splits')
          .select(PAYROLL_SPLIT_SELECT)
          .in('payout_id', payouts.map((p) => p.id));
        if (error) {
          log('splits', error);
          setState({ loading: false, error: humanizeError(error), data: null });
          return;
        }
        splits = data || [];
      }
    }

    setState({
      loading: false,
      error: null,
      data: buildPayrollMonth({
        creators,
        invoices: cashInvoices,
        payouts,
        splits,
        inKindByCreator: inKindTotals,
        paychecks: payRes.data || [],
        compBases: compRes.data,
        month,
      }),
    });
  }, [month]);

  useEffect(() => { load(); }, [load]);

  // The panel quotes figures from the month it was opened over, so it cannot outlive a reload
  // or a step to another month: it would keep asserting a total nothing on screen still shows.
  useEffect(() => { setBreakdown(null); }, [state.data]);

  const openInvoice = useCallback((inv) => {
    if (!inv.campaign_id) return;
    window.dispatchEvent(new CustomEvent('nys:open-payment', { detail: { campaign_id: inv.campaign_id } }));
  }, []);

  // A creator appears when her month holds money of any kind, or when it has already been
  // settled. Everyone else would be a band of zeros, and four zeros compete with the one
  // figure that is not.
  const liveRows = useMemo(
    () => (state.data?.rows || []).filter((r) => (
      r.paycheck || r.collected > 0 || r.inKind > 0
      || r.wages > 0 || r.reimbursement > 0
    )),
    [state.data]
  );

  // A month nobody is on wages for still has a register worth reading, so it renders in full and
  // only the subtitle changes: it would otherwise promise a Gusto run that is not happening.
  const nobodyOnWages = liveRows.length > 0 && liveRows.every((r) => r.basis !== 'w2');

  return (
    <div className={`payroll${isMobile ? ' payroll-mobile' : ''}`}>
      <header className="payroll-head">
        <div className="payroll-monthpick">
          <h3 className="payroll-month">{fmtMonth(month)}</h3>
          {/* Both steppers grouped after the month: split either side, the gap
              between them changes with the length of the month's name. */}
          <div className="payroll-steps">
            <button
              type="button" className="payroll-step" onClick={() => setMonth((m) => shiftMonth(m, -1))}
              aria-label="Previous month"
            >
              <ChevronIcon size={12} style={{ transform: 'rotate(180deg)' }} />
            </button>
            <button
              type="button" className="payroll-step" onClick={() => setMonth((m) => shiftMonth(m, 1))}
              aria-label="Next month"
            >
              <ChevronIcon size={12} />
            </button>
          </div>
        </div>
        <p className="payroll-sub">
          {nobodyOnWages
            ? `Nobody was on payroll in ${fmtMonth(month)}. That pay is reported on a 1099-NEC.`
            : `What to enter in Gusto for the run that pays ${fmtMonth(month)}`}
          <HelpIcon slug="payroll-month" />
        </p>
      </header>

      {isOpenMonth && (
        <Feedback value={{
          tone: 'warn',
          title: `${fmtMonth(month)} is still open`,
          body: 'More agency cash may still land this month. Wait for it to close before settling, '
              + 'or a second run will be needed for whatever arrives after.',
        }} />
      )}

      {state.error ? (
        <Feedback value={state.error} />
      ) : state.loading ? (
        <Skeleton label="Loading payroll" />
      ) : state.data.isBlocked ? (
        <section className="payroll-blocked">
          <h4 className="payroll-blocked-title">
            <WarningIcon size={13} />
            Give {fmtMonth(month)}&apos;s cash an owner first
          </h4>
          <p className="payroll-blocked-body">
            {state.data.orphans.length === 1 ? 'One payment' : `${state.data.orphans.length} payments`} landed
            this month against no creator, so there is nobody to pay it to. Running payroll now would
            leave that money with the company, so the figures stay hidden until every payment has an owner.
          </p>
          <InvoiceGaps invoices={state.data.orphans} onOpen={openInvoice} />
        </section>
      ) : !state.data.hasAnyMoney ? (
        <EmptyState variant="note" text={`No agency payments landed in ${fmtMonth(month)}. Nothing to run.`} />
      ) : !liveRows.length ? (
        <EmptyState variant="note" text={`Money landed in ${fmtMonth(month)}, but none of it was allocated to a creator. Nothing to pay.`} />
      ) : (
        <>
          <section className="payroll-register">
            {liveRows.map((row) => {
              if (row.state === 'mixed') {
                return <MixedRow key={row.profile.id} row={row} onOpenInvoice={openInvoice} />;
              }
              if (row.state === 'split') {
                return (
                  <SplitMonthRow key={row.profile.id} row={row} month={month} onOpenInvoice={openInvoice} />
                );
              }
              if (row.state === 'contractor') {
                return (
                  <ContractorRow
                    key={row.profile.id} row={row} month={month}
                    onOpenInvoice={openInvoice} onOpenBreakdown={setBreakdown}
                  />
                );
              }
              if (row.state === 'legacy') {
                return (
                  <RegisterRow
                    key={row.profile.id} row={row} month={month} onOpenBreakdown={setBreakdown}
                  />
                );
              }
              return (
                <PayrollPaycheck
                  key={row.profile.id} row={row} month={month}
                  onSaved={load} onOpenBreakdown={setBreakdown}
                />
              );
            })}
          </section>
          {/* Only once a paycheck exists, because only a monthly paycheck ever credits 2200.
              January to July 2026 settled per invoice and withheld nothing, so a band there
              would ask about a liability that month never created. */}
          {liveRows.some((row) => row.paycheck) && (
            <PayrollTaxRemittance month={month} rows={liveRows} onSaved={load} />
          )}
        </>
      )}

      {breakdown && (
        <PayrollBreakdown breakdown={breakdown} onClose={() => setBreakdown(null)} />
      )}
    </div>
  );
}
