/**
 * components/admin/FinancialsView.js: thin admin wrapper around components/shared/LedgerPage.
 *
 * AdminDashboard passes initialFilter (set by navigateToLedger from PaymentsPage /
 * RewardsPage cross-links) and onFilterConsumed, plus onNavigateToPaymentSetup for
 * the COA to destination cross-link. All logic lives in LedgerPage. Pass-through by design.
 */
import React from 'react';
import LedgerPage from '../shared/LedgerPage';

export default function FinancialsView({ initialFilter, onFilterConsumed, onNavigateToPaymentSetup }) {
  return (
    <LedgerPage
      isAdmin
      initialFilter={initialFilter}
      onFilterConsumed={onFilterConsumed}
      onNavigateToPaymentSetup={onNavigateToPaymentSetup}
    />
  );
}
