/**
 * components/shared/MailboxSection.js: per-creator iCloud mailbox setup.
 *
 * Mounted inside the admin Edit User modal beside TaxIdSection and TaxBasisSection, because a
 * mailbox is the same kind of once-per-person credential those are. All logic lives here;
 * UsersView is a mount point.
 *
 * THE SHAPE OF THE THING, WHICH THE UI HAS TO CARRY: one Apple ID owns the mailbox and the
 * custom-domain addresses are aliases on it with no credentials of their own. So the screen
 * reads top down as "send as X, via account Y", alias as headline, Apple ID as sub-line.
 *
 * @gotcha Apple revokes every app-specific password when the Apple ID password changes. That
 *         arrives as a routine authentication failure, so without a visible auth-failed state a
 *         mailbox stops working quietly. A healthy mailbox stays deliberately uncoloured.
 * @security The password is write-only. It is handed to a vault-backed RPC and is never fetched
 *           back into the browser by any code path.
 * @see utils/mail.js, scripts/mail-worker.js
 */
import React, { useState, useEffect, useCallback } from 'react';
import { fmtDateTime } from '../../utils/format';
import { humanizeError } from '../../utils/errors';
import { useConfirm } from './ConfirmDialog';
import { useToast } from './Toast';
import { ChevronIcon, CheckIcon, WarningIcon, ExternalLinkIcon } from './Icon';
import SubmitButton from './SubmitButton';
import OutstandingList from './OutstandingList';
import Feedback from './Feedback';
import Loading from './Loading';
import ReadError from './ReadError';
import { useLoadState } from '../../hooks/useLoadState';
import Refreshing from './Refreshing';
import {
  ICLOUD_DEFAULTS, APPLE_PASSWORD_URL, fetchMailAccount, saveMailAccount,
  setMailPassword, deleteMailAccount, testMailAccount, mailStatus,
  formatAppPassword, isValidAppPassword,
} from '../../utils/mail';

/** What each status says and whether it is worth spending attention on. */
const STATUS_COPY = {
  no_password: {
    tone: 'warn',
    title: 'No password on file',
    body: 'Add the app-specific password from the Apple ID to connect.',
  },
  auth_failed: {
    tone: 'warn',
    title: 'Apple rejected the sign-in',
    body: 'App-specific passwords are revoked whenever the Apple ID password changes. Generate a new one and replace it here.',
  },
  error: {
    tone: 'warn',
    title: 'Last connection failed',
    body: null, // filled with the real error, which is the useful part
  },
};

const emptyForm = () => ({
  id: null,
  login_email: '',
  from_address: '',
  from_name: '',
  ...ICLOUD_DEFAULTS,
});

/**
 * Mailbox configuration panel for one profile.
 *
 * @param {object} props
 * @param {string} props.profileId whose mailbox this is
 * @param {string} [props.profileName] used only in confirm copy
 */
export default function MailboxSection({ profileId, profileName }) {
  const askConfirm = useConfirm();
  const toast = useToast();

  const [account, setAccount] = useState(null);
  const { loading, refreshing, begin, end } = useLoadState();
  // The third state. `account` null means two things and only one of them is "nobody has
  // connected a mailbox": a toast fades and the empty state underneath it keeps making that
  // claim. @see .claude/rules/hub-ui.md (the four data states)
  const [readError, setReadError] = useState(null);
  const [editing, setEditing] = useState(false);
  const [form, setForm]       = useState(emptyForm);
  const [password, setPassword] = useState('');
  const [showServers, setShowServers] = useState(false);
  const [busy, setBusy] = useState(false);
  const [testResult, setTestResult] = useState(null);

  const refresh = useCallback(async () => {
    begin();
    try {
      setAccount(await fetchMailAccount(profileId));
      setReadError(null);
    } catch (e) {
      if (process.env.NODE_ENV !== 'production') console.error('[MailboxSection]', e);
      // No toast: this is not a transient notice, it is the panel's state. `remove()` re-reads
      // through here too, so a refused re-read after a successful disconnect must not settle
      // on "Not connected" either, which is the same sentence whether the row went or not.
      setAccount(null);
      setReadError(e);
    } finally {
      end();
    }
  }, [profileId, begin, end]);

  useEffect(() => { refresh(); }, [refresh]);

  const status = mailStatus(account);

  function startEdit() {
    setForm(account ? { ...account, from_name: account.from_name || '' } : emptyForm());
    setPassword('');
    setTestResult(null);
    setEditing(true);
  }

  function cancelEdit() {
    setEditing(false);
    setPassword('');
    setShowServers(false);
  }

  /**
   * What is still standing between the reader and a greyed-out Connect button. Save was
   * `busy || !canSave`, and `canSave` hid three conditions behind one identifier, so the
   * button greyed for a reason nothing on the panel stated: the helper prose beside these
   * fields is about where to GET an app password, not about what is currently blocking Save.
   *
   * In the order the controls appear, per `OutstandingList`'s own contract. `busy` stays on
   * `disabled` rather than joining this list: a transient flag is not a requirement, and the
   * button label already says it.
   * @see components/shared/OutstandingList.js
   */
  const EMAIL = /^[^@\s]+@[^@\s]+\.[^@\s]+$/;
  const outstanding = [];
  if (!EMAIL.test(form.login_email)) outstanding.push({ key: 'login', label: 'Enter the address the mailbox signs in with' });
  if (!EMAIL.test(form.from_address)) outstanding.push({ key: 'from', label: 'Enter the address mail is sent from' });
  // A brand new mailbox needs a password to be worth saving. An existing one
  // may be edited without touching the password that is already stored.
  if (account?.secret_id ? (password && !isValidAppPassword(password)) : !isValidAppPassword(password)) {
    outstanding.push({
      key: 'password',
      label: account?.secret_id
        ? 'Fix the app password, or clear the field to keep the stored one'
        : 'Enter the 16 character app password',
    });
  }

  async function save() {
    setBusy(true);
    try {
      const saved = await saveMailAccount(profileId, form);
      if (password) await setMailPassword(saved.id, password);
      setPassword('');
      setEditing(false);
      setShowServers(false);
      toast.success(account ? 'Mailbox updated' : 'Mailbox connected');
      await refresh();
    } catch (e) {
      toast.error({ title: 'Could not save', body: humanizeError(e)?.body });
    } finally {
      setBusy(false);
    }
  }

  async function test() {
    setBusy(true);
    setTestResult(null);
    try {
      const res = await testMailAccount(account.id);
      setTestResult(res);
      if (res.ok) toast.success('Mailbox connected');
      await refresh();
    } catch (e) {
      setTestResult({ ok: false, imap: { ok: false, message: e.message }, smtp: { ok: false } });
      toast.error({ title: 'Test failed', body: humanizeError(e)?.body });
    } finally {
      setBusy(false);
    }
  }

  async function remove() {
    const ok = await askConfirm({
      title: 'Disconnect mailbox?',
      body: `The stored password is destroyed. ${profileName || 'This creator'} keeps the mailbox itself; we simply stop reading and sending from it.`,
      confirmLabel: 'Disconnect',
      danger: true,
    });
    if (!ok) return;
    setBusy(true);
    try {
      await deleteMailAccount(account.id);
      setTestResult(null);
      toast.success('Mailbox disconnected');
      await refresh();
    } catch (e) {
      toast.error({ title: 'Could not disconnect', body: humanizeError(e)?.body });
    } finally {
      setBusy(false);
    }
  }

  const label = (text) => (
    <div className="form-label" style={{ margin: 0 }}>{text}</div>
  );

  /**
   * A server address the mailbox is on, stated rather than offered.
   *
   * Deliberately not a disabled input: a greyed-out box reads as "this broke" and
   * still invites a click. Plain text at the same height as the port field beside
   * it keeps the row aligned and says the value is simply a fact.
   *
   * @security The two hosts are pinned by chk_mail_imap_host and chk_mail_smtp_host,
   *           and scripts/mail-worker.js refuses any other. They were free text, and
   *           an admin who repointed one made the VPS daemon hand the Vault mailbox
   *           password to a server of their choosing.
   */
  const fixedHost = (host) => (
    <div title={host} style={{
      marginTop: 6,
      padding: '9px 0',
      fontSize: 13,
      color: 'var(--muted)',
      whiteSpace: 'nowrap',
      overflow: 'hidden',
      textOverflow: 'ellipsis',
    }}>{host}</div>
  );

  return (
    <div className="form-group" style={{ marginTop: 18, paddingTop: 16, borderTop: '1px solid var(--border)' }}>
      <div style={{ display: 'flex', alignItems: 'baseline', justifyContent: 'space-between', marginBottom: 10 }}>
        {label('MAILBOX')}
        {!loading && !editing && account && (
          <div style={{ display: 'flex', gap: 4 }}>
            <button className="btn btn-ghost btn-sm" disabled={busy || !account.secret_id} onClick={test}>
              {busy ? 'Testing…' : 'Test'}
            </button>
            <button className="btn btn-ghost btn-sm" disabled={busy} onClick={startEdit}>Edit</button>
            <button className="btn btn-ghost btn-sm" disabled={busy} onClick={remove}>Disconnect</button>
          </div>
        )}
        {editing && (
          <button className="btn btn-ghost btn-sm" disabled={busy} onClick={cancelEdit}>Cancel</button>
        )}
      </div>

      <Refreshing on={refreshing} />
      {loading && <Loading style={{ fontSize: 12 }} />}

      {!loading && readError && <ReadError error={readError} onRetry={refresh} />}

      {/* ── Nothing connected ────────────────────────────────────────────── */}
      {!loading && !readError && !editing && !account && (
        <div>
          <div style={{ fontSize: 13, color: 'var(--muted)', marginBottom: 10, maxWidth: '62ch', lineHeight: 1.5 }}>
            Not connected. Needed to read agency mail and to send from a Nysterys address.
          </div>
          <button className="btn btn-primary btn-sm" onClick={startEdit}>+ Connect mailbox</button>
        </div>
      )}

      {/* ── Connected ────────────────────────────────────────────────────── */}
      {!loading && !editing && account && (
        <div>
          {/* The alias is the headline: it is the address the outside world
              sees. The Apple ID is only how we authenticate, so it sits under
              it in the muted register. */}
          <div style={{ fontSize: 15, color: 'var(--white)', letterSpacing: '-0.01em' }}>
            {account.from_name ? `${account.from_name} · ` : ''}{account.from_address}
          </div>
          <div style={{ fontSize: 11, color: 'var(--muted)', marginTop: 3 }}>
            via {account.login_email}
          </div>

          {status === 'connected' && (
            <div style={{ display: 'flex', alignItems: 'center', gap: 6, fontSize: 11, color: 'var(--dim)', marginTop: 10 }}>
              <CheckIcon size={11} />
              Connected · checked {fmtDateTime(account.last_connected_at)}
            </div>
          )}

          {status === 'untested' && (
            <div style={{ fontSize: 11, color: 'var(--dim)', marginTop: 10 }}>
              Password stored, connection not tested yet.
            </div>
          )}

          {STATUS_COPY[status] && (
            <Feedback
              style={{ marginTop: 12 }}
              value={{
                tone: STATUS_COPY[status].tone,
                title: STATUS_COPY[status].title,
                body: (
                  <>
                    {STATUS_COPY[status].body || account.last_error}
                    <div style={{ marginTop: 10 }}>
                      <button className="btn btn-ghost btn-sm" onClick={startEdit}>
                        {status === 'no_password' ? 'Add password' : 'Replace password'}
                      </button>
                    </div>
                  </>
                ),
              }}
            />
          )}

          {testResult && (
            <div style={{ marginTop: 12, display: 'grid', gap: 6 }}>
              <TestLine label="Reading mail" result={testResult.imap} extra={
                testResult.folders != null ? `${testResult.folders} folders` : null
              } />
              <TestLine label="Sending mail" result={testResult.smtp} />
            </div>
          )}
        </div>
      )}

      {/* ── Editing ──────────────────────────────────────────────────────── */}
      {editing && (
        <div style={{ display: 'grid', gap: 14 }}>
          <div>
            {label('APPLE ID')}
            <input aria-label="Apple ID"
              className="form-input"
              type="email"
              autoComplete="off"
              placeholder="name@icloud.com"
              maxLength={254}
              value={form.login_email}
              onChange={e => setForm(f => ({ ...f, login_email: e.target.value }))}
              style={{ marginTop: 6 }}
              autoFocus
            />
            <div style={{ fontSize: 11, color: 'var(--muted)', marginTop: 6, maxWidth: '62ch', lineHeight: 1.5 }}>
              The account that owns the mailbox, not the custom-domain address. Aliases have no password of their own.
            </div>
          </div>

          <div>
            {label(account?.secret_id ? 'REPLACE PASSWORD' : 'APP-SPECIFIC PASSWORD')}
            <input aria-label="App-specific password"
              className="form-input"
              type="password"
              autoComplete="new-password"
              placeholder="xxxx-xxxx-xxxx-xxxx"
              value={password}
              maxLength={19}
              onChange={e => setPassword(formatAppPassword(e.target.value))}
              style={{ marginTop: 6, fontFamily: 'var(--font-mono)', letterSpacing: 1 }}
            />
            <div style={{ fontSize: 11, color: 'var(--muted)', marginTop: 6, maxWidth: '62ch', lineHeight: 1.5 }}>
              {account?.secret_id
                ? 'Leave blank to keep the stored password. '
                : 'Not the Apple ID password. '}
              Generate one under Sign-In and Security.{' '}
              <a
                href={APPLE_PASSWORD_URL}
                target="_blank"
                rel="noopener noreferrer"
                style={{ color: 'var(--orange)', display: 'inline-flex', alignItems: 'center', gap: 4 }}
              >
                account.apple.com <ExternalLinkIcon size={10} />
              </a>
            </div>
          </div>

          <div>
            {label('SEND AS')}
            <input aria-label="Send from address"
              className="form-input"
              type="email"
              autoComplete="off"
              placeholder="name@nysterys.com"
              maxLength={254}
              value={form.from_address}
              onChange={e => setForm(f => ({ ...f, from_address: e.target.value }))}
              style={{ marginTop: 6 }}
            />
            <div style={{ fontSize: 11, color: 'var(--muted)', marginTop: 6, maxWidth: '62ch', lineHeight: 1.5 }}>
              Must be an alias iCloud already knows about, or it refuses the message.
            </div>
          </div>

          <div>
            {label('DISPLAY NAME')}
            <input aria-label="From name"
              className="form-input"
              type="text"
              placeholder="Optional"
              maxLength={120}
              value={form.from_name}
              onChange={e => setForm(f => ({ ...f, from_name: e.target.value }))}
              style={{ marginTop: 6 }}
            />
          </div>

          {/* Server details are correct out of the box for iCloud, so they stay
              folded away. Progressive disclosure, not a hidden requirement. */}
          <div>
            <button
              type="button"
              className="btn btn-ghost btn-sm"
              onClick={() => setShowServers(s => !s)}
              style={{ display: 'inline-flex', alignItems: 'center', gap: 6, paddingLeft: 0 }}
            >
              <span style={{
                display: 'inline-flex',
                transform: showServers ? 'rotate(90deg)' : 'none',
                transition: 'transform 160ms cubic-bezier(0.2,0,0,1)',
              }}>
                <ChevronIcon size={10} />
              </span>
              Server details
            </button>

            {showServers && (
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 90px', gap: 10, marginTop: 10 }}>
                <div>
                  {label('IMAP HOST')}
                  {fixedHost(ICLOUD_DEFAULTS.imap_host)}
                </div>
                <div>
                  {label('PORT')}
                  <input aria-label="IMAP port" className="form-input" type="number" min={1} max={65535} value={form.imap_port} style={{ marginTop: 6 }}
                    onChange={e => setForm(f => ({ ...f, imap_port: e.target.value }))} />
                </div>
                <div>
                  {label('SMTP HOST')}
                  {fixedHost(ICLOUD_DEFAULTS.smtp_host)}
                </div>
                <div>
                  {label('PORT')}
                  <input aria-label="SMTP port" className="form-input" type="number" min={1} max={65535} value={form.smtp_port} style={{ marginTop: 6 }}
                    onChange={e => setForm(f => ({ ...f, smtp_port: e.target.value }))} />
                </div>
                <div style={{ gridColumn: '1 / -1' }}>
                  {label('SMTP SECURITY')}
                  <select aria-label="SMTP security" className="form-input" value={form.smtp_security} style={{ marginTop: 6, maxWidth: 220 }}
                    onChange={e => setForm(f => ({ ...f, smtp_security: e.target.value }))}>
                    <option value="starttls">STARTTLS (port 587)</option>
                    <option value="tls">TLS (port 465)</option>
                  </select>
                </div>
              </div>
            )}
          </div>

          <OutstandingList items={outstanding} style={{ marginBottom: 12 }} />

          <div style={{ display: 'flex', justifyContent: 'flex-end' }}>
            <SubmitButton saving={busy} className="btn btn-primary btn-sm" disabled={busy || outstanding.length > 0} onClick={save}>{account ? 'Save' : 'Connect'}</SubmitButton>
          </div>
        </div>
      )}
    </div>
  );
}

/**
 * One line of a connection test. Reading and sending are reported apart because
 * they fail apart: iCloud can accept the password on IMAP while a blocked
 * submission port makes only sending fail.
 */
function TestLine({ label, result, extra }) {
  const ok = !!result?.ok;
  return (
    <div style={{
      display: 'flex', alignItems: 'center', gap: 8,
      fontSize: 12, color: ok ? 'var(--muted)' : 'var(--orange2)',
    }}>
      {ok ? <CheckIcon size={11} /> : <WarningIcon size={11} />}
      <span style={{ color: 'var(--white)' }}>{label}</span>
      <span>
        {ok
          ? (extra || 'working')
          : (result?.kind === 'auth' ? 'password rejected' : (result?.message || 'failed'))}
      </span>
    </div>
  );
}
