/**
 * components/admin/PaymentSetupView.js: admin Config view for the payment plumbing:
 * payment methods, payout destinations, payment terms, and account types.
 *
 * A payout destination maps to a 21xx liability account; creating/editing one feeds
 * the ledger account auto-creation triggers. The MethodLogo / InstitutionLogo sets
 * below are brand wordmarks (PayPal, Chase, etc.), not functional UI icons, so they
 * are inline SVG by design rather than entries in Icon.js. Substantial view.
 *
 * @gotcha is_deferred on a destination means cash stays parked in LLC checking;
 *         splits to it can never be marked cleared (DB trigger blocks it), and the
 *         account keeps its curated label instead of the auto "Payable..." rename.
 * @see schemas/SCHEMA.sql (payment_destinations, payment_methods, payment_terms)
 */
import React, { useState, useEffect, useRef } from 'react';
import { supabase } from '../../lib/supabase';
import HelpIcon from '../shared/HelpIcon';
import { humanizeError } from '../../utils/errors';
import Feedback from '../shared/Feedback';
import { useConfirm } from '../shared/ConfirmDialog';
import { useToast } from '../shared/Toast';
import { useCreators } from '../../hooks/useCreators';
import { mutate } from '../../utils/mutate';
import ReadError from '../shared/ReadError';
import EmptyState from '../shared/EmptyState';
import Modal, { ModalClose } from '../shared/Modal';
import Field from '../shared/Field';
import Loading from '../shared/Loading';
import SubmitButton from '../shared/SubmitButton';
import { COMP_BASIS_EDIT_SELECT } from '../../utils/compBasis';
import CreatorDestinations from './CreatorDestinations';
import { MethodLogo, InstitutionLogo } from '../shared/PaymentLogos';



// ── Section divider ────────────────────────────────────────────────────────────
function SectionHeader({ title, subtitle, first = false, action }) {
  return (
    <div style={{ marginTop: first ? 0 : 48, paddingTop: first ? 0 : 32, borderTop: first ? 'none' : '2px solid var(--border)', marginBottom: 16 }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
        <div style={{ width: 3, height: 18, background: 'var(--blue)', borderRadius: 2, flexShrink: 0 }} />
        <span style={{ fontSize: 13, fontWeight: 700, letterSpacing: '0.06em', textTransform: 'uppercase' }}>{title}</span>
        {subtitle && <span style={{ fontSize: 12, color: 'var(--muted)' }}>{subtitle}</span>}
        {action && <div style={{ marginLeft: 'auto' }}>{action}</div>}
      </div>
    </div>
  );
}

// ── Main view ─────────────────────────────────────────────────────────────────
export default function PaymentSetupView({ onNavigateToLedger }) {
  const askConfirm = useConfirm();
  const toast = useToast();
  const [methods, setMethods]             = useState([]);
  const [usageCounts, setUsageCounts]     = useState({});
  const [destinations, setDestinations]   = useState([]);
  const { creators, error: creatorsError, refresh: refreshCreators } = useCreators();
  const [terms, setTerms]                 = useState([]);
  const [termsUsage, setTermsUsage]       = useState({});
  const [accountTypes, setAccountTypes]   = useState([]);
  const [loading, setLoading]             = useState(true);
  // The third state. Four empty states render at once here, and the three usage counts below
  // are what decide whether Delete is offered: a refused count reads as "nothing references
  // this" on a payment method that every invoice names.
  const [loadError, setLoadError]         = useState(null);
  const [showMethodModal, setShowMethodModal]   = useState(false);
  const [fieldsMethod, setFieldsMethod]         = useState(null);
  const [showDestModal, setShowDestModal]       = useState(false);
  const [editingDest, setEditingDest]           = useState(null);
  const [showTermModal, setShowTermModal]       = useState(false);
  const [editingTerm, setEditingTerm]           = useState(null);
  const [compBases, setCompBases]               = useState([]);
  const [closedYears, setClosedYears]           = useState(() => new Set());
  const [basisOpenFor, setBasisOpenFor]         = useState(null);

  useEffect(() => { fetchAll(); }, []);

  async function fetchAll() {
    setLoadError(null);
    const [mRes, iRes, dRes, tRes, aRes, atRes, cbRes, lpRes] = await Promise.all([
      supabase.from('payment_methods').select('*').order('sort_order').order('name'),
      supabase.from('invoices').select('payment_method'),
      supabase.from('payment_destinations')
        // Both embeds are FK-ambiguous and MUST be disambiguated or the whole query
        // fails with PGRST201 (HTTP 300): profiles is reachable via profile_id AND
        // oop_creator_id; payout_splits via destination_id AND reimbursement_destination_id.
        // @gotcha An unqualified embed fails the WHOLE query, not just the embed. The
        //         error is bound below; unbound it renders as "No destinations configured".
        .select('*, profile:profiles!payment_destinations_profile_id_fkey(creator_name, full_name), payout_splits:payout_splits!payout_splits_destination_id_fkey(id), ledger_account:ledger_accounts(code)')
        .order('profile_id').order('sort_order'),
      supabase.from('payment_terms').select('*').order('sort_order').order('name'),
      supabase.from('agencies').select('payment_term_id'),
      supabase.from('account_types').select('*').order('sort_order').order('name'),
      supabase.from('creator_comp_basis').select(COMP_BASIS_EDIT_SELECT).order('effective_from'),
      // Which years are sealed. A classification change reaches backwards into whatever it
      // dates itself into, so a closed year refuses one the way it refuses a posted entry.
      supabase.from('ledger_periods').select('fiscal_year, status').in('status', ['closed', 'locked']),
    ]);
    const readError = mRes.error || iRes.error || dRes.error || tRes.error || aRes.error || atRes.error
      || cbRes.error || lpRes.error;
    if (readError) {
      setLoadError(readError);
      setMethods([]);
      setDestinations([]);
      setTerms([]);
      setAccountTypes([]);
      setUsageCounts({});
      setTermsUsage({});
      setCompBases([]);
      setClosedYears(new Set());
      setLoading(false);
      return;
    }
    setMethods(mRes.data || []);
    const counts = {};
    for (const inv of (iRes.data || [])) {
      if (!inv.payment_method) continue;
      counts[inv.payment_method.toLowerCase()] = (counts[inv.payment_method.toLowerCase()] || 0) + 1;
    }
    setUsageCounts(counts);
    setDestinations((dRes.data || []).map(d => ({ ...d, hasPayouts: (d.payout_splits || []).length > 0 })));
    setTerms(tRes.data || []);
    const tUsage = {};
    for (const a of (aRes.data || [])) {
      if (!a.payment_term_id) continue;
      tUsage[a.payment_term_id] = (tUsage[a.payment_term_id] || 0) + 1;
    }
    setTermsUsage(tUsage);
    setAccountTypes(atRes.data || []);
    setCompBases(cbRes.data || []);
    setClosedYears(new Set((lpRes.data || []).map(p => p.fiscal_year)));
    setLoading(false);
  }

  async function toggleMethod(m) {
    const { error } = await mutate(supabase.from('payment_methods').update({ is_active: !m.is_active }).eq('id', m.id));
    if (error) { toast.error(error); return; }
    fetchAll();
  }

  async function deleteMethod(m) {
    if (!(await askConfirm({ title: `Delete "${m.name}"?`, body: 'This cannot be undone.', danger: true }))) return;
    const { error } = await mutate(supabase.from('payment_methods').delete().eq('id', m.id));
    if (error) { toast.error(error); return; }
    fetchAll();
  }

  async function toggleDest(d) {
    const { error } = await mutate(supabase.from('payment_destinations').update({ is_active: !d.is_active }).eq('id', d.id));
    if (error) { toast.error(error); return; }
    fetchAll();
  }

  async function deleteDest(d) {
    if (!(await askConfirm({ title: `Delete "${d.name}"?`, body: 'This also removes its ledger account. Cannot be undone.', danger: true }))) return;
    // The DB trigger refuses with its own sentence when the destination has ledger lines or
    // payout splits, and humanizeError's P0001 branch already keeps it. Passing the WHOLE
    // feedback object is what carries its title across too; rebuilding the object by hand put
    // "Delete failed" over a sentence that had already named the way out.
    const { error } = await mutate(supabase.from('payment_destinations').delete().eq('id', d.id));
    if (error) { toast.error(error); return; }
    fetchAll();
  }

  async function toggleTerm(t) {
    const { error } = await mutate(supabase.from('payment_terms').update({ is_active: !t.is_active }).eq('id', t.id));
    if (error) { toast.error(error); return; }
    fetchAll();
  }

  async function deleteTerm(t) {
    if (!(await askConfirm({ title: `Delete "${t.name}"?`, body: 'This cannot be undone.', danger: true }))) return;
    const { error } = await mutate(supabase.from('payment_terms').delete().eq('id', t.id));
    if (error) { toast.error(error); return; }
    fetchAll();
  }

  if (loading) return <div className="page"><Loading /></div>;
  if (loadError) return <div className="page"><ReadError error={loadError} onRetry={fetchAll} /></div>;

  return (
    <div className="page">
      <div className="page-header">
        <div>
          <h1 className="page-title">PAYMENT SETUP<HelpIcon slug="payment-setup" /></h1>
          <div className="page-subtitle">Methods, terms, and payout destinations</div>
        </div>
        <div className="flex gap-8">
          <button className="btn btn-ghost" onClick={() => { setEditingTerm(null); setShowTermModal(true); }}>+ Add Term</button>
          <button className="btn btn-ghost" onClick={() => setShowMethodModal(true)}>+ Add Method</button>
          <button className="btn btn-primary" onClick={() => { setEditingDest(null); setShowDestModal(true); }}>+ Add Destination</button>
        </div>
      </div>

      {/* ── Payment Methods ── */}
      <SectionHeader first title="Payment Methods" subtitle="How agencies pay invoices"
        action={<button className="btn btn-ghost btn-sm" style={{ color: 'var(--white)' }} onClick={() => setShowMethodModal(true)}>+ Add Method</button>} />
      {methods.length === 0 ? (
        <EmptyState style={{ marginBottom: 32 }}
          title="No payment methods yet"
          text="Add methods like PayPal, Wire, ACH, Zelle…" />
      ) : (
        <div className="table-wrap" style={{ marginBottom: 36 }}>
          <table className="pinned-actions" style={{ width: '100%' }}>
            <thead>
              <tr><th scope="col"></th><th scope="col">Method</th><th scope="col">Usage</th><th scope="col">Status</th><th scope="col"></th><th scope="col"></th><th scope="col"></th></tr>
            </thead>
            <tbody>
              {methods.map(m => {
                const count = usageCounts[m.name.toLowerCase()] || 0;
                return (
                  <tr key={m.id} style={{ opacity: m.is_active ? 1 : 0.5 }}>
                    <td style={{ paddingRight: 0 }}><MethodLogo name={m.name} size={24} /></td>
                    <td style={{ fontWeight: 500 }}>{m.name}</td>
                    <td style={{ color: 'var(--muted)', fontSize: 12 }}>
                      {count > 0 ? `${count} invoice${count !== 1 ? 's' : ''}` : <span className="text-muted">—</span>}
                    </td>
                    <td>
                      <span className={`badge ${m.is_active ? 'badge-orange' : 'badge-red-soft'}`}>
                        {m.is_active ? 'Active' : 'Inactive'}
                      </span>
                    </td>
                    <td>
                      <button className="btn btn-ghost btn-sm" onClick={() => setFieldsMethod(m)}>
                        Fields{m.fields_schema?.length > 0 ? ` (${m.fields_schema.length})` : ''}
                      </button>
                    </td>
                    <td>
                      <button className="btn btn-ghost btn-sm" onClick={() => toggleMethod(m)}>
                        {m.is_active ? 'Deactivate' : 'Activate'}
                      </button>
                    </td>
                    <td>
                      {count === 0 && (
                        <button className="btn btn-ghost btn-sm" style={{ color: 'var(--red)' }} onClick={() => deleteMethod(m)}>
                          Delete
                        </button>
                      )}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}

      {/* ── Payout Destinations ── */}
      <SectionHeader title="Payout Destinations" subtitle="Creator bank accounts and investment accounts" />
      {/* Every destination below sits under a creator heading, so a refused creator read
          renders the section title over blank space beside a live Add. Not the empty state
          either: the destinations ARE there, they have nobody to sit under. */}
      {creatorsError ? (
        <ReadError error={creatorsError} onRetry={refreshCreators} />
      ) : destinations.length === 0 ? (
        <EmptyState
          title="No destinations configured"
          text="Add payout accounts for Kym and Mys" />
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 24 }}>
          {creators.map(creator => {
            const creatorDests = destinations.filter(d => d.profile_id === creator.id);
            if (creatorDests.length === 0) return null;
            return (
              <CreatorDestinations
                key={creator.id}
                creator={creator}
                destinations={creatorDests}
                compBases={compBases}
                closedYears={closedYears}
                basisOpen={basisOpenFor === creator.id}
                onToggleBasis={() => setBasisOpenFor(id => (id === creator.id ? null : creator.id))}
                onAdd={() => { setEditingDest(null); setShowDestModal(true); }}
                onEdit={(d) => { setEditingDest(d); setShowDestModal(true); }}
                onToggle={toggleDest}
                onDelete={deleteDest}
                onNavigateToLedger={onNavigateToLedger}
                onSaved={fetchAll}
              />
            );
          })}
        </div>
      )}

      {/* ── Payment Terms ── */}
      <SectionHeader title="Payment Terms" subtitle="Reusable net terms assigned to agencies"
        action={<button className="btn btn-ghost btn-sm" style={{ color: 'var(--white)' }} onClick={() => { setEditingTerm(null); setShowTermModal(true); }}>+ Add Term</button>} />
      {terms.length === 0 ? (
        <EmptyState
          title="No payment terms yet"
          text="Add terms like Net 30, Upon Receipt…" />
      ) : (
        <div className="table-wrap">
          <table className="pinned-actions" style={{ width: '100%' }}>
            <thead>
              <tr><th scope="col"></th><th scope="col">Term</th><th scope="col">Invoice Text</th><th scope="col">Usage</th><th scope="col">Status</th><th scope="col"></th></tr>
            </thead>
            <tbody>
              {terms.map(t => {
                const count = termsUsage[t.id] || 0;
                const preview = t.invoice_text ? t.invoice_text.replace(/\n/g, ' ').slice(0, 80) + (t.invoice_text.length > 80 ? '…' : '') : null;
                return (
                  <tr key={t.id} style={{ opacity: t.is_active ? 1 : 0.5 }}>
                    <td />
                    <td style={{ fontWeight: 500 }}>{t.name}</td>
                    <td style={{ fontSize: 12, color: 'var(--muted)', maxWidth: 320 }}>
                      {preview || <span className="text-muted">—</span>}
                    </td>
                    <td style={{ fontSize: 12, color: 'var(--muted)' }}>
                      {count > 0 ? `${count} agenc${count !== 1 ? 'ies' : 'y'}` : <span className="text-muted">—</span>}
                    </td>
                    <td>
                      <span className={`badge ${t.is_active ? 'badge-orange' : 'badge-red-soft'}`}>
                        {t.is_active ? 'Active' : 'Inactive'}
                      </span>
                    </td>
                    <td>
                      <div className="flex gap-8">
                        <button className="btn btn-ghost btn-sm" onClick={() => { setEditingTerm(t); setShowTermModal(true); }}>Edit</button>
                        <button className="btn btn-ghost btn-sm" onClick={() => toggleTerm(t)}>
                          {t.is_active ? 'Deactivate' : 'Activate'}
                        </button>
                        {count === 0 && (
                          <button className="btn btn-ghost btn-sm" style={{ color: 'var(--red)' }} onClick={() => deleteTerm(t)}>Delete</button>
                        )}
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}

      {fieldsMethod && (
        <MethodFieldsModal
          method={fieldsMethod}
          onClose={() => setFieldsMethod(null)}
          onSaved={() => { setFieldsMethod(null); fetchAll(); }}
        />
      )}
      {showMethodModal && (
        <AddMethodModal
          currentMethods={methods}
          onClose={() => setShowMethodModal(false)}
          onSaved={() => { setShowMethodModal(false); fetchAll(); }}
        />
      )}

      {showDestModal && (
        <DestinationModal
          destination={editingDest}
          creators={creators}
          accountTypes={accountTypes}
          onClose={() => setShowDestModal(false)}
          onSaved={() => { setShowDestModal(false); fetchAll(); }}
        />
      )}

      {showTermModal && (
        <PaymentTermModal
          term={editingTerm}
          onClose={() => setShowTermModal(false)}
          onSaved={() => { setShowTermModal(false); fetchAll(); }}
        />
      )}

      {/* ── Account Types ── */}
      <AccountTypesSection types={accountTypes} destinations={destinations} onChanged={fetchAll} />
    </div>
  );
}

// ── Add method modal ───────────────────────────────────────────────────────────
function AddMethodModal({ onClose, onSaved, currentMethods }) {
  const toast = useToast();
  const [name, setName]     = useState('');
  const [saving, setSaving] = useState(false);
  const [error, setError]   = useState('');

  async function save() {
    const trimmed = name.trim();
    if (!trimmed) { setError('Name is required.'); return; }
    if (currentMethods.some(m => m.name.toLowerCase() === trimmed.toLowerCase())) {
      setError('A method with this name already exists.'); return;
    }
    setSaving(true);
    const maxSort = currentMethods.reduce((m, r) => Math.max(m, r.sort_order || 0), 0);
    const { error: err } = await supabase.from('payment_methods').insert({ name: trimmed, sort_order: maxSort + 1 });
    if (err) { setError(humanizeError(err)); setSaving(false); return; }
    toast.success('Payment method added');
    onSaved();
  }

  return (
    <Modal
      title="ADD PAYMENT METHOD"
      size="sm"
      onClose={onClose}
    >
        <div className="modal-body">
          {error && <Feedback value={error} style={{ marginBottom: 16 }} />}
          {name.trim() && (
            <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 16, padding: '10px 14px', background: 'var(--surface2)', borderRadius: 8 }}>
              <MethodLogo name={name.trim()} size={36} />
              <span style={{ fontSize: 12, color: 'var(--muted)' }}>Logo preview</span>
            </div>
          )}
          <Field label="Method Name *">{(id) => (<>
            <input id={id}
              className="form-input"
              value={name}
              autoFocus
              onChange={e => { setName(e.target.value); setError(''); }}
              onKeyDown={e => e.key === 'Enter' && save()}
              placeholder="PayPal, Wire, ACH, Zelle…"
            />
            <div style={{ fontSize: 11, color: 'var(--dim)', marginTop: 6 }}>
              Logos auto-match for PayPal, Zelle, Wire, ACH, Check, Direct Deposit, Venmo, Cash
            </div>
          </>)}</Field>
        </div>
        <div className="modal-footer">
          <ModalClose className="btn btn-ghost">Cancel</ModalClose>
          <button className="btn btn-primary" onClick={save} disabled={saving || !name.trim()}>
            {saving ? 'Adding…' : 'Add Method'}
          </button>
        </div>
    </Modal>
  );
}

// ── Method fields modal ────────────────────────────────────────────────────────
function MethodFieldsModal({ method, onClose, onSaved }) {
  const toast = useToast();
  const [fields, setFields]       = useState(method.fields_schema || []);
  const [addingField, setAddingField] = useState(false);
  const [newLabel, setNewLabel]   = useState('');
  const [saving, setSaving]       = useState(false);
  const [error, setError]         = useState('');

  function deriveKey(label) {
    return label.toLowerCase().trim().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
  }

  function addField() {
    const label = newLabel.trim();
    if (!label) return;
    const key = deriveKey(label);
    if (fields.some(f => f.key === key)) { setError('A field with that key already exists.'); return; }
    setFields(f => [...f, { key, label, required: true }]);
    setNewLabel('');
    setAddingField(false);
    setError('');
  }

  function toggleRequired(key) {
    setFields(f => f.map(f => f.key === key ? { ...f, required: !f.required } : f));
  }

  async function save() {
    setSaving(true);
    const { error: err } = await supabase
      .from('payment_methods')
      .update({ fields_schema: fields.length > 0 ? fields : null })
      .eq('id', method.id);
    if (err) { setError(humanizeError(err)); setSaving(false); return; }
    toast.success('Fields saved');
    onSaved();
  }

  return (
    <Modal
      title={<>FIELDS: {method.name.toUpperCase()}</>}
      subtitle="Define what info is collected when adding a payment address for this method"
      size="sm"
      onClose={onClose}
    >
        <div className="modal-body">
          {error && <Feedback value={error} style={{ marginBottom: 12 }} />}

          {fields.length === 0 && !addingField ? (
            <div style={{ fontSize: 13, color: 'var(--muted)', marginBottom: 16 }}>
              No structured fields. Uses a single address input (email, URL, or handle).
            </div>
          ) : (
            <div style={{ marginBottom: 12 }}>
              {fields.map((f, i) => (
                <div key={f.key} style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '8px 0', borderBottom: '1px solid var(--border)' }}>
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ fontSize: 13, fontWeight: 500 }}>{f.label}</div>
                    <div style={{ fontFamily: 'var(--font-mono)', fontSize: 11, color: 'var(--muted)' }}>{f.key}</div>
                  </div>
                  <button
                    className="btn btn-ghost btn-sm"
                    style={{ fontSize: 11, color: f.required ? 'var(--orange)' : 'var(--muted)', flexShrink: 0 }}
                    onClick={() => toggleRequired(f.key)}
                  >
                    {f.required ? 'Required' : 'Optional'}
                  </button>
                  <button
                    className="btn btn-ghost btn-sm"
                    style={{ color: 'var(--red)', flexShrink: 0 }}
                    aria-label={`Remove the ${f.key} field`}
                    onClick={() => setFields(fs => fs.filter((_, j) => j !== i))}
                  >
                    ×
                  </button>
                </div>
              ))}
            </div>
          )}

          {addingField ? (
            <div style={{ display: 'flex', gap: 8, alignItems: 'flex-end' }}>
              <Field label="Field Label" style={{ margin: 0, flex: 1 }}>{(id) => (<>
                <input id={id}
                  className="form-input"
                  value={newLabel}
                  maxLength={80}
                  placeholder="e.g. Routing Number"
                  autoFocus
                  onChange={e => { setNewLabel(e.target.value); setError(''); }}
                  onKeyDown={e => { if (e.key === 'Enter') addField(); if (e.key === 'Escape') { setAddingField(false); setNewLabel(''); } }}
                />
                {newLabel.trim() && (
                  <div fontFamily="monospace" style={{ fontSize: 11, color: 'var(--muted)', marginTop: 4 }}>
                    key: {deriveKey(newLabel)}
                  </div>
                )}
              </>)}</Field>
              <button className="btn btn-primary btn-sm" onClick={addField} disabled={!newLabel.trim()}>Add</button>
              <button className="btn btn-ghost btn-sm" onClick={() => { setAddingField(false); setNewLabel(''); setError(''); }}>Cancel</button>
            </div>
          ) : (
            <button className="btn btn-ghost btn-sm" onClick={() => setAddingField(true)}>+ Add Field</button>
          )}
        </div>
        <div className="modal-footer">
          <ModalClose className="btn btn-ghost">Cancel</ModalClose>
          <SubmitButton saving={saving} className="btn btn-primary" onClick={save} disabled={saving}>Save</SubmitButton>
        </div>
    </Modal>
  );
}

// ── Destination modal ──────────────────────────────────────────────────────────
/**
 * Add/edit a payout destination. On insert the forward trigger auto-creates the
 * matching 21xx liability account.
 *
 * @gotcha is_deferred locks the destination out of split-clearing (see file header).
 */
function DestinationModal({ destination, creators, accountTypes, onClose, onSaved }) {
  const toast = useToast();
  const [form, setForm] = useState({
    profile_id:    destination?.profile_id    || '',
    name:          destination?.name          || '',
    account_type:  destination?.account_type  || '',
    account_last4: destination?.account_last4 || '',
    institution:   destination?.institution   || '',
    memo:          destination?.memo          || '',
    sort_order:    destination?.sort_order    ?? 0,
    is_deferred:   destination?.is_deferred   || false,
  });
  const [saving, setSaving] = useState(false);
  const [error, setError]   = useState('');

  async function save() {
    if (!form.profile_id || !form.name.trim()) { setError('Creator and destination name are required.'); return; }
    if (form.account_last4 && !/^\d{4}$/.test(form.account_last4)) { setError('Last 4 must be exactly 4 digits.'); return; }
    setSaving(true); setError('');
    const payload = {
      ...form,
      name:          form.name.trim(),
      account_last4: form.account_last4 || null,
      institution:   form.institution.trim() || null,
      memo:          form.memo.trim() || null,
    };
    if (destination) {
      const { error } = await mutate(supabase.from('payment_destinations').update(payload).eq('id', destination.id));
      if (error) { setSaving(false); toast.error(error); return; }
    } else {
      const { error: err } = await supabase.from('payment_destinations').insert(payload);
      if (err) { setError(humanizeError(err)); setSaving(false); return; }
    }
    setSaving(false);
    toast.success(destination ? 'Destination updated' : 'Destination added');
    onSaved();
  }

  return (
    <Modal
      title={destination ? 'EDIT DESTINATION' : 'ADD DESTINATION'}
      size="sm"
      onClose={onClose}
    >
        <div className="modal-body">
          {error && <Feedback value={error} style={{ marginBottom: 16 }} />}
          {form.institution.trim() && (
            <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 16, padding: '10px 14px', background: 'var(--surface2)', borderRadius: 8 }}>
              <InstitutionLogo institution={form.institution.trim()} size={36} />
              <span style={{ fontSize: 12, color: 'var(--muted)' }}>Logo preview</span>
            </div>
          )}
          <Field label="Creator *">{(id) => (<>
            <select id={id} className="form-select" value={form.profile_id}
              onChange={e => setForm(f => ({ ...f, profile_id: e.target.value }))}
              disabled={!!destination}>
              <option value="">Select creator…</option>
              {creators.map(c => <option key={c.id} value={c.id}>{c.creator_name || c.full_name}</option>)}
            </select>
          </>)}</Field>
          <div className="form-row">
            <Field label="Destination Name *">{(id) => (<>
              <input id={id} className="form-input" value={form.name}
                onChange={e => setForm(f => ({ ...f, name: e.target.value }))}
                placeholder="Savings, UTMA, Checking…" />
            </>)}</Field>
            <Field label="Account Type *">{(id) => (<>
              <select id={id} className="form-select" value={form.account_type}
                onChange={e => setForm(f => ({ ...f, account_type: e.target.value }))}>
                <option value="">Select…</option>
                {accountTypes.filter(t => t.is_active).map(t => <option key={t.id} value={t.name}>{t.name}</option>)}
              </select>
            </>)}</Field>
          </div>
          <div className="form-row">
            <Field label="Institution">{(id) => (<>
              <input id={id} className="form-input" value={form.institution}
                onChange={e => setForm(f => ({ ...f, institution: e.target.value }))}
                placeholder="Chase, Fidelity, Vanguard…" />
            </>)}</Field>
            <Field label="Last 4 Digits">{(id) => (<>
              <input id={id} className="form-input" value={form.account_last4}
                onChange={e => setForm(f => ({ ...f, account_last4: e.target.value.slice(0, 4) }))}
                placeholder="6789" maxLength={4} fontFamily="monospace" style={{ fontFamily: 'monospace' }} />
            </>)}</Field>
          </div>
          <Field label="Memo / Notes">{(id) => (<>
            <input id={id} className="form-input" value={form.memo}
              onChange={e => setForm(f => ({ ...f, memo: e.target.value }))}
              placeholder="Any routing notes or identifiers…" />
          </>)}</Field>
          <Field label="Display Order">{(id) => (<>
            <input id={id} className="form-input" type="number" min={0} value={form.sort_order}
              onChange={e => setForm(f => ({ ...f, sort_order: parseInt(e.target.value) || 0 }))}
              style={{ width: 80 }} />
          </>)}</Field>
          <div className="form-group">
            <label style={{ display: 'flex', alignItems: 'flex-start', gap: 10, cursor: 'pointer' }}>
              <input type="checkbox" checked={form.is_deferred}
                onChange={e => setForm(f => ({ ...f, is_deferred: e.target.checked }))}
                style={{ marginTop: 3 }} />
              <span>
                <strong style={{ display: 'block', marginBottom: 4 }}>Deferred (money stays in the LLC checking account)</strong>
                <span style={{ fontSize: 12, color: 'var(--muted)', lineHeight: 1.4 }}>
                  Use for an "earmark" where the creator has earned money but it physically stays in the business checking account (for example, to satisfy a minimum-balance requirement). Splits routed here will post the payout liability but cannot be marked cleared. When you actually transfer the cash later, uncheck this box, then mark the splits cleared.
                </span>
              </span>
            </label>
          </div>
        </div>
        <div className="modal-footer">
          <ModalClose className="btn btn-ghost">Cancel</ModalClose>
          <SubmitButton saving={saving} className="btn btn-primary" onClick={save} disabled={saving}>{destination ? 'Save' : 'Add Destination'}</SubmitButton>
        </div>
    </Modal>
  );
}

// ── Payment term modal ─────────────────────────────────────────────────────────
function PaymentTermModal({ term, onClose, onSaved }) {
  const toast = useToast();
  const [name,         setName]         = useState(term?.name         || '');
  const [invoiceText,  setInvoiceText]  = useState(term?.invoice_text || '');
  const [saving, setSaving] = useState(false);
  const [error, setError]   = useState('');

  async function save() {
    const trimmedName = name.trim();
    if (!trimmedName) { setError('Name is required.'); return; }
    setSaving(true); setError('');
    const payload = { name: trimmedName, invoice_text: invoiceText.trim() || null };
    if (term) {
      const { error: err } = await supabase.from('payment_terms').update(payload).eq('id', term.id);
      if (err) { setError(humanizeError(err)); setSaving(false); return; }
    } else {
      const { error: err } = await supabase.from('payment_terms').insert({ ...payload, sort_order: 0 });
      if (err) { setError(humanizeError(err)); setSaving(false); return; }
    }
    toast.success(term ? 'Payment term updated' : 'Payment term added');
    onSaved();
  }

  return (
    <Modal
      title={term ? 'EDIT PAYMENT TERM' : 'ADD PAYMENT TERM'}
      size="md"
      onClose={onClose}
    >
        <div className="modal-body">
          {error && <Feedback value={error} style={{ marginBottom: 16 }} />}
          <Field label="Term Name *">{(id) => (<>
            <input id={id} className="form-input" value={name} autoFocus maxLength={120}
              onChange={e => { setName(e.target.value); setError(''); }}
              onKeyDown={e => e.key === 'Enter' && save()}
              placeholder="Net 30, Upon Receipt, Net 15…" />
          </>)}</Field>
          <Field label={<>Invoice Terms Text <span style={{ color: 'var(--muted)', fontWeight: 400, textTransform: 'none', letterSpacing: 0, fontSize: 11 }}>printed on invoices for agencies using this term</span></>}>{(id) => (<>
            <textarea id={id} className="form-textarea" value={invoiceText} maxLength={2000} rows={5}
              onChange={e => setInvoiceText(e.target.value)}
              placeholder={'Full payment is due before we create or post anything.\nNothing goes live until payment clears.'} />
          </>)}</Field>
        </div>
        <div className="modal-footer">
          <ModalClose className="btn btn-ghost">Cancel</ModalClose>
          <SubmitButton saving={saving} className="btn btn-primary" onClick={save} disabled={saving || !name.trim()}>{term ? 'Save' : 'Add Term'}</SubmitButton>
        </div>
    </Modal>
  );
}

// ── Account Types section ──────────────────────────────────────────────────────
function AccountTypesSection({ types, destinations, onChanged }) {
  const toast = useToast();
  const askConfirm = useConfirm();
  const [drafts, setDrafts]   = useState({});
  const [newName, setNewName] = useState('');
  const [showAdd, setShowAdd] = useState(false);
  const addInputRef = useRef(null);

  useEffect(() => {
    if (showAdd && addInputRef.current) addInputRef.current.focus();
  }, [showAdd]);

  function getDraft(t) { return drafts[t.id] !== undefined ? drafts[t.id] : t.name; }

  async function saveType(t) {
    const name = (drafts[t.id] ?? t.name).trim();
    if (!name || name === t.name) return;
    const { error } = await mutate(supabase.from('account_types').update({ name }).eq('id', t.id));
    if (error) { toast.error(error); return; }
    onChanged();
  }

  async function toggleType(t) {
    const { error } = await mutate(supabase.from('account_types').update({ is_active: !t.is_active }).eq('id', t.id));
    if (error) { toast.error(error); return; }
    onChanged();
  }

  async function deleteType(t) {
    if (!(await askConfirm({ title: `Delete "${t.name}"?`, body: 'This cannot be undone.', danger: true }))) return;
    const { error } = await mutate(supabase.from('account_types').delete().eq('id', t.id));
    if (error) { toast.error(error); return; }
    onChanged();
  }

  async function addType() {
    if (!newName.trim()) return;
    const maxSort = types.reduce((m, t) => Math.max(m, t.sort_order || 0), 0);
    const { error } = await mutate(supabase.from('account_types').insert({ name: newName.trim(), sort_order: maxSort + 1 }));
    if (error) { toast.error(error); return; }
    setNewName('');
    setShowAdd(false);
    onChanged();
  }

  return (
    <>
      <SectionHeader title="Account Types" subtitle="Payout destination categories"
        action={<button className="btn btn-ghost btn-sm" style={{ color: 'var(--white)' }} onClick={() => setShowAdd(true)}>+ Add Type</button>} />
      {types.length === 0 && !showAdd ? (
        <EmptyState style={{ marginBottom: 32 }}
          title="No account types yet"
          text="Add types like Checking, Savings, UTMA…" />
      ) : (
        <div className="table-wrap" style={{ marginBottom: 36 }}>
          <table className="pinned-actions" style={{ width: '100%' }}>
            <thead>
              <tr><th scope="col">Type</th><th scope="col">Usage</th><th scope="col">Status</th><th scope="col"></th></tr>
            </thead>
            <tbody>
              {types.map(t => {
                const count = destinations.filter(d => d.account_type === t.name).length;
                return (
                  <tr key={t.id} style={{ opacity: t.is_active ? 1 : 0.5 }}>
                    <td>
                      <input
                        className="form-input"
                        style={{ maxWidth: 200 }}
                        aria-label={`Rename ${t.name}`}
                        value={getDraft(t)}
                        maxLength={80}
                        onChange={e => setDrafts(d => ({ ...d, [t.id]: e.target.value }))}
                        onBlur={() => saveType(t)}
                        onKeyDown={e => { if (e.key === 'Enter') e.target.blur(); }}
                      />
                    </td>
                    <td style={{ color: 'var(--muted)', fontSize: 12 }}>
                      {count > 0 ? `${count} destination${count !== 1 ? 's' : ''}` : <span className="text-muted">—</span>}
                    </td>
                    <td>
                      <span className={`badge ${t.is_active ? 'badge-orange' : 'badge-red-soft'}`}>
                        {t.is_active ? 'Active' : 'Inactive'}
                      </span>
                    </td>
                    <td>
                      <div className="flex gap-8">
                        <button className="btn btn-ghost btn-sm" onClick={() => toggleType(t)}>
                          {t.is_active ? 'Deactivate' : 'Activate'}
                        </button>
                        {count === 0 && (
                          <button className="btn btn-ghost btn-sm" style={{ color: 'var(--red)' }} onClick={() => deleteType(t)}>
                            Delete
                          </button>
                        )}
                      </div>
                    </td>
                  </tr>
                );
              })}
              {showAdd && (
                <tr>
                  <td>
                    <input
                      ref={addInputRef}
                      className="form-input"
                      style={{ maxWidth: 200 }}
                      aria-label="New payment type name"
                      value={newName}
                      maxLength={80}
                      placeholder="Type name"
                      onChange={e => setNewName(e.target.value)}
                      onKeyDown={e => {
                        if (e.key === 'Enter') addType();
                        if (e.key === 'Escape') { setShowAdd(false); setNewName(''); }
                      }}
                    />
                  </td>
                  <td colSpan={2} />
                  <td>
                    <div className="flex gap-8">
                      <button className="btn btn-primary btn-sm" onClick={addType} disabled={!newName.trim()}>Add</button>
                      <button className="btn btn-ghost btn-sm" onClick={() => { setShowAdd(false); setNewName(''); }}>Cancel</button>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      )}
    </>
  );
}

