/**
 * components/shared/ActivityTab.js: Financials -> Activity (default tab).
 *
 * Plain-language event feed grouped from posted ledger entries: one card per
 * business event (invoice / payout / partner / manual), expandable to the
 * underlying journal entries inline. The raw debit/credit view stays on the
 * General Ledger tab for accountant work.
 *
 * This file is the data-fetch + render shell; all card grouping/matching logic
 * lives in utils/ledger-activity.js.
 *
 * @see docs/MONEY.md (journal-entry patterns), docs/CODEBASE.md (ledger UI)
 */
import React, { useEffect, useMemo, useState, useCallback } from 'react';
import HelpIcon from './HelpIcon';
import { supabase } from '../../lib/supabase';
import { fmtDate, fmtMoney } from '../../utils/format';
import { buildActivityCards, matchActivityCard } from '../../utils/ledger-activity';
import { isReversalEntry } from '../../utils/journalEntry';  // not the utils/ledger re-export: that pulls in @react-pdf/renderer
import ReverseEntryModal from './ReverseEntryModal';
import { InvoiceIcon, PayoutIcon, PartnerIcon, ManualIcon, CheckIcon, HalfIcon, RingIcon, WarningIcon, ChevronIcon } from './Icon';
import { DB_DATE_MAX, DB_DATE_MIN } from '../../utils/dbLimits';
import ReadError from './ReadError';
import EmptyState from './EmptyState';
import Field from './Field';
import Loading from './Loading';
import { useLoadState } from '../../hooks/useLoadState';
import Refreshing from './Refreshing';

const log = (...args) => {
  if (process.env.NODE_ENV !== 'production') console.error('[ActivityTab]', ...args);
};

const EVENT_TYPES = [
  { id: 'all',          label: 'All',       helpSlug: null },
  { id: 'invoice',      label: 'Invoices',  helpSlug: 'campaign-and-invoice' },
  { id: 'payout',       label: 'Payouts',   helpSlug: 'payout' },
  { id: 'partner_txn',  label: 'Partners',  helpSlug: 'partner-txns' },
  { id: 'manual',       label: 'Manual',    helpSlug: 'manual-entry' },
];

const TYPE_ICON = {
  invoice:      InvoiceIcon,
  payout:       PayoutIcon,
  partner_txn:  PartnerIcon,
  manual:       ManualIcon,
};

const PILL_STATE_STYLE = {
  done:     { color: 'var(--green)',  bg: 'color-mix(in oklab, var(--green) 14%, transparent)' },
  partial:  { color: 'var(--orange)', bg: 'color-mix(in oklab, var(--orange) 16%, transparent)' },
  pending:  { color: 'var(--muted)',  bg: 'color-mix(in oklab, var(--muted) 18%, transparent)' },
  reversed: { color: 'var(--red)',    bg: 'color-mix(in oklab, var(--red) 14%, transparent)' },
};

const PAGE_SIZE = 50;

// Named because each is fetched TWICE: once by id for the visible entries, once
// by payout_id to pull in siblings. Two select strings for one shape is how the
// second one silently drops a column the first has.
const PAYOUT_COLS = 'id, profile_id, campaign_id, reward_entry_id';
const SPLIT_COLS  = 'id, payout_id, destination_id, expense_id, amount';

/**
 * The Activity feed.
 *
 * @param {object} props
 * @param {object[]} props.accounts - chart of accounts (id/code/name lookup).
 * @param {boolean} props.isAdmin - gates the in-place Reverse action.
 * @param {function} [props.onJumpToGl] - opens a JE on the General Ledger tab.
 */
export default function ActivityTab({ accounts, isAdmin, onJumpToGl }) {
  const [dateFrom,   setDateFrom]   = useState('');
  const [dateTo,     setDateTo]     = useState('');
  const [eventType,  setEventType]  = useState('all');
  const [search,     setSearch]     = useState('');
  const [pageCount,  setPageCount]  = useState(1);
  const activityFiltersDirty = !!dateFrom || !!dateTo || eventType !== 'all' || !!search.trim();
  // @invariant a reversed range is named, never answered. Both ends go straight to `.gte` and
  //            `.lte` on `entry_date`, so a To before the From returns nothing and the feed
  //            then says no activity matches, which on a ledger is a claim rather than an
  //            absence. ISO YYYY-MM-DD sorts lexically.
  const rangeReversed = !!dateFrom && !!dateTo && dateTo < dateFrom;
  function clearActivityFilters() { setDateFrom(''); setDateTo(''); setEventType('all'); setSearch(''); }
  const { loading, refreshing, begin, end } = useLoadState();
  // The third state. Both reads below only dev-logged their failure, which is stripped from
  // the production build, so a refused read said "No activity in this range" about a range
  // holding every journal entry the LLC has posted.
  const [readError,  setReadError]  = useState(null);
  const [entries,    setEntries]    = useState([]);
  const [lines,      setLines]      = useState([]);
  const [enrich,     setEnrich]     = useState({
    invoicesById: new Map(), campaignsById: new Map(), agenciesById: new Map(),
    rewardEntriesById: new Map(), programsById: new Map(),
    payoutsById: new Map(), splitsById: new Map(), destinationsById: new Map(),
    profilesById: new Map(), partnerTxnsById: new Map(),
  });
  const [expanded,   setExpanded]   = useState(null);   // card.key
  const [reverseFor, setReverseFor] = useState(null);   // { entry, lines }

  const cashAccountId = useMemo(() => (accounts || []).find((a) => a.code === '1000')?.id || null, [accounts]);
  const accountById = useMemo(() => new Map((accounts || []).map((a) => [a.id, a])), [accounts]);

  /**
   * Rows of `table` whose `col` is in `ids`, or none when `ids` is empty.
   *
   * @gotcha `col` is a PARAMETER, not always 'id': the sibling-splits round trip keys on
   *         payout_id, and hard-coding 'id' would silently narrow the cleared M-of-N pill's
   *         denominator.
   * @gotcha THROWS rather than degrading to []. It was best effort, on the argument that these
   *         reads only name things, and the gotcha above is the counterexample: the
   *         sibling-splits round trip is one of them, and a short read narrows the cleared
   *         M-of-N denominator exactly as hard-coding 'id' would. A pill reading "1 of 1
   *         cleared" over a payout with three splits is a claim about money that moved.
   */
  async function lookupByIds(table, cols, col, ids) {
    const list = [...ids];
    if (!list.length) return [];
    const { data, error } = await supabase.from(table).select(cols).in(col, list);
    if (error) throw error;
    return data || [];
  }

  /**
   * Fetch the visible posted JEs (PAGE_SIZE * pageCount, newest first) plus their
   * lines, then resolve human-readable context for each event type.
   *
   * @perf Enrichment is scoped to only the visible JEs and batched: invoices /
   *       payouts / splits / partner txns load in one parallel round, then their
   *       referenced campaigns / rewards / destinations / profiles in a second.
   *       Never one query per card.
   * @gotcha Splits pull in their parent payouts even when the payout JE is off the
   *         current page (extraPayoutIds), and all sibling splits of those payouts
   *         are loaded so the cleared M-of-N pill denominator is correct.
   */
  const fetchPage = useCallback(async () => {
    begin();
    setReadError(null);
    let q = supabase
      .from('ledger_journal_entries')
      .select('*')
      .eq('is_posted', true)
      .order('entry_date', { ascending: false })
      .order('created_at', { ascending: false })
      .limit(PAGE_SIZE * pageCount);
    if (dateFrom) q = q.gte('entry_date', dateFrom);
    if (dateTo)   q = q.lte('entry_date', dateTo);

    const { data: e, error: eErr } = await q;
    if (eErr) { log('entries', eErr); setReadError(eErr); setEntries([]); setLines([]); end(); return; }
    const ids = (e || []).map((r) => r.id);
    let l = [];
    if (ids.length) {
      const { data: lr, error: lErr } = await supabase
        .from('ledger_entry_lines').select('*').in('journal_entry_id', ids);
      // The lines carry every amount on every card. Without them the entries still render,
      // as a list of dated descriptions against $0.00, so this fails the read rather than
      // drawing the money it could not read.
      if (lErr) { log('lines', lErr); setReadError(lErr); setEntries([]); setLines([]); end(); return; }
      l = lr || [];
    }
    setEntries(e || []);
    setLines(l);

    // ── Enrichment fetches scoped to the visible JEs only ──────────────────
    // One catch for the whole block, not one per lookup: the cards are assembled from all of
    // it at once, and a card missing half its context is not a smaller card, it is a card that
    // says something different.
    try {
      const invoiceIds   = new Set();
      const payoutIds    = new Set();
      const splitIds     = new Set();
      const partnerIds   = new Set();
      for (const r of e || []) {
        if (r.source_type === 'invoice'      && r.source_id) invoiceIds.add(r.source_id);
        if (r.source_type === 'payout'       && r.source_id) payoutIds.add(r.source_id);
        if (r.source_type === 'split'        && r.source_id) splitIds.add(r.source_id);
        if (r.source_type === 'partner_txn'  && r.source_id) partnerIds.add(r.source_id);
      }

      const [invoices, payouts, splits, ptxns] = await Promise.all([
        lookupByIds('invoices', 'id, invoice_number, invoice_amount, in_kind_value, campaign_id, reward_entry_id, is_in_kind, you_received', 'id', invoiceIds),
        lookupByIds('creator_payouts', PAYOUT_COLS, 'id', payoutIds),
        lookupByIds('payout_splits', SPLIT_COLS, 'id', splitIds),
        lookupByIds('partner_transactions', '*', 'id', partnerIds),
      ]);

      // Need: payouts referenced by splits too (for the payout card grouping).
      const extraPayoutIds = new Set(splits.map((s) => s.payout_id).filter(Boolean));
      payouts.forEach((p) => extraPayoutIds.delete(p.id));
      for (const p of await lookupByIds('creator_payouts', PAYOUT_COLS, 'id', extraPayoutIds)) payouts.push(p);

      // Need: all splits attached to those payouts (for cleared M/N denominator).
      const allPayoutIds = new Set(payouts.map((p) => p.id));
      const byId = new Map(splits.map((s) => [s.id, s]));
      for (const s of await lookupByIds('payout_splits', SPLIT_COLS, 'payout_id', allPayoutIds)) byId.set(s.id, s);
      const allSplits = [...byId.values()];

      const campaignIds   = new Set();
      const rewardIds     = new Set();
      const agencyIds     = new Set();
      const destIds       = new Set();
      const profileIds    = new Set();
      invoices.forEach((i) => { if (i.campaign_id) campaignIds.add(i.campaign_id); if (i.reward_entry_id) rewardIds.add(i.reward_entry_id); });
      payouts.forEach((p) => { if (p.campaign_id) campaignIds.add(p.campaign_id); if (p.reward_entry_id) rewardIds.add(p.reward_entry_id); if (p.profile_id) profileIds.add(p.profile_id); });
      allSplits.forEach((s) => { if (s.destination_id) destIds.add(s.destination_id); });
      ptxns.forEach((t) => { if (t.profile_id) profileIds.add(t.profile_id); });

      const [campaigns, rewardEntries, destinations, profiles] = await Promise.all([
        lookupByIds('campaigns', 'id, brand_name, campaign_name, display_name, creator_profile_id, agency_id', 'id', campaignIds),
        lookupByIds('platform_reward_entries', 'id, period_month, program_id, profile_id', 'id', rewardIds),
        lookupByIds('payment_destinations', 'id, name, account_type, last4:account_last4', 'id', destIds),
        lookupByIds('profiles', 'id, full_name, creator_name', 'id', profileIds),
      ]);

      // Agencies resolved through campaigns (invoices have no direct agency_id).
      campaigns.forEach((c) => { if (c.agency_id) agencyIds.add(c.agency_id); });
      const agencies = await lookupByIds('agencies', 'id, name', 'id', agencyIds);

      const programIds = new Set(rewardEntries.map((r) => r.program_id).filter(Boolean));
      const programs = await lookupByIds('platform_rewards_programs', 'id, name', 'id', programIds);

      setEnrich({
        invoicesById:      new Map(invoices.map((x) => [x.id, x])),
        campaignsById:     new Map(campaigns.map((x) => [x.id, x])),
        agenciesById:      new Map(agencies.map((x) => [x.id, x])),
        rewardEntriesById: new Map(rewardEntries.map((x) => [x.id, x])),
        programsById:      new Map(programs.map((x) => [x.id, x])),
        payoutsById:       new Map(payouts.map((x) => [x.id, x])),
        splitsById:        new Map(allSplits.map((x) => [x.id, x])),
        destinationsById:  new Map(destinations.map((x) => [x.id, x])),
        profilesById:      new Map(profiles.map((x) => [x.id, x])),
        partnerTxnsById:   new Map(ptxns.map((x) => [x.id, x])),
      });
    } catch (err) {
      log('enrichment', err);
      setReadError(err);
      setEntries([]);
      setLines([]);
    }
    end();
  }, [dateFrom, dateTo, pageCount, begin, end]);

  useEffect(() => { fetchPage(); }, [fetchPage]);

  const cards = useMemo(() => {
    if (!entries.length) return [];
    return buildActivityCards({ entries, lines, cashAccountId, ...enrich });
  }, [entries, lines, cashAccountId, enrich]);

  const visibleCards = useMemo(
    () => cards.filter((c) => matchActivityCard(c, { search: search.trim(), eventType })),
    [cards, search, eventType]
  );

  const linesByJe = useMemo(() => {
    const m = new Map();
    for (const l of lines) {
      if (!m.has(l.journal_entry_id)) m.set(l.journal_entry_id, []);
      m.get(l.journal_entry_id).push(l);
    }
    return m;
  }, [lines]);
  const entryById = useMemo(() => new Map(entries.map((e) => [e.id, e])), [entries]);

  // Attach account code + name to each JE line for display.
  const decorate = (jeLines) => (jeLines || []).map((l) => {
    const a = accountById.get(l.account_id);
    return { ...l, account_code: a?.code, account_name: a?.name };
  });

  return (
    <div>
      {/* Filters */}
      <div className="card" style={{ marginBottom: 14 }}>
        <div style={{ display: 'grid', gridTemplateColumns: '160px 160px 1fr', gap: 16, marginBottom: 12 }}>
          <Field label="From" style={{ margin: 0 }}>{(id) => (<>
            <input id={id} className="form-input" type="date" min={DB_DATE_MIN} max={DB_DATE_MAX} value={dateFrom} onChange={(e) => setDateFrom(e.target.value)} />
          </>)}</Field>
          <Field label="To" style={{ margin: 0 }}>{(id) => (<>
            <input id={id} className="form-input" type="date" min={dateFrom || DB_DATE_MIN} max={DB_DATE_MAX} value={dateTo} onChange={(e) => setDateTo(e.target.value)} />
          </>)}</Field>
          <Field label="Search" style={{ margin: 0 }}>{(id) => (<>
            <input id={id} className="form-input" placeholder="Find by name, brand, invoice #, …" value={search} onChange={(e) => setSearch(e.target.value)} />
          </>)}</Field>
        </div>
        <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap', alignItems: 'center' }}>
          {EVENT_TYPES.map((t) => (
            <React.Fragment key={t.id}>
              <button className="btn btn-ghost btn-sm"
                onClick={() => setEventType(t.id)}
                style={{
                  border: '1px solid var(--border)',
                  background: eventType === t.id ? 'var(--orange)' : 'transparent',
                  color:      eventType === t.id ? 'var(--black)' : 'var(--muted)',
                  fontWeight: eventType === t.id ? 700 : 500,
                  borderRadius: 999,
                  padding: '4px 12px',
                }}>{t.label}</button>
              {eventType === t.id && t.helpSlug ? <HelpIcon slug={t.helpSlug} /> : null}
            </React.Fragment>
          ))}
        </div>
      </div>

      <Refreshing on={refreshing} />
      {loading ? (
        <Loading />
      ) : readError ? (
        <ReadError error={readError} onRetry={fetchPage} />
      ) : rangeReversed ? (
        <EmptyState
          title="The To date is before the From date."
          text={`Set To on or after ${fmtDate(dateFrom)} to see the activity in that range.`}
          action={<button className="btn btn-ghost btn-sm" onClick={clearActivityFilters}>Clear filters</button>} />
      ) : visibleCards.length === 0 ? (
        /* Every filter here opens unfiltered, so `activityFiltersDirty` alone IS the whole
           discriminator: nothing is dirty before the reader touches a control, which is why
           this surface needs no unfiltered array. */
        <EmptyState
          title={activityFiltersDirty ? 'No activity matches these filters' : 'No activity recorded yet'}
          text={activityFiltersDirty
            ? 'Adjust the date range or clear the search.'
            : 'Posted journal entries appear here as they happen.'}
          action={activityFiltersDirty
            ? <button className="btn btn-ghost btn-sm" onClick={clearActivityFilters}>Clear filters</button>
            : null} />
      ) : (
        <div className="card activity-list" style={{ padding: 0, overflow: 'hidden' }}>
          {visibleCards.map((c, i) => (
            <ActivityCard
              key={c.key}
              card={c}
              isLast={i === visibleCards.length - 1}
              expanded={expanded === c.key}
              onToggle={() => setExpanded((cur) => cur === c.key ? null : c.key)}
              entries={c.jeIds.map((id) => entryById.get(id)).filter(Boolean)}
              linesByJe={linesByJe}
              decorate={decorate}
              isAdmin={isAdmin}
              onReverse={(je) => setReverseFor({ entry: je, lines: decorate(linesByJe.get(je.id)) })}
              onJumpToGl={onJumpToGl}
            />
          ))}
          {entries.length === PAGE_SIZE * pageCount ? (
            <div style={{ textAlign: 'center', padding: 12 }}>
              <button className="btn btn-secondary btn-sm" onClick={() => setPageCount((n) => n + 1)}>Load more</button>
            </div>
          ) : null}
        </div>
      )}

      {reverseFor ? (
        <ReverseEntryModal
          journalEntry={reverseFor.entry}
          lines={reverseFor.lines}
          onClose={() => setReverseFor(null)}
          onReversed={() => { setReverseFor(null); setExpanded(null); fetchPage(); }}
        />
      ) : null}
    </div>
  );
}

const PILL_MARK = { done: CheckIcon, partial: HalfIcon, reversed: WarningIcon };

/** Small status pill (done / partial / pending / reversed) with its state glyph. */
function Pill({ pill }) {
  const style = PILL_STATE_STYLE[pill.state] || PILL_STATE_STYLE.pending;
  const Mark = PILL_MARK[pill.state] || RingIcon;
  return (
    <span style={{
      display: 'inline-flex', alignItems: 'center', gap: 3, flexShrink: 0,
      fontSize: 10.5, padding: '0 6px', borderRadius: 999, lineHeight: '16px',
      color: style.color, background: style.bg, whiteSpace: 'nowrap',
    }}><Mark size={8} /> {pill.label}</span>
  );
}

/**
 * One collapsible event row: headline + money + date, expanding to the per-JE
 * debit/credit tables with a per-entry Reverse (admin) and "→ GL" jump.
 * @gotcha Reverse is disabled when the JE is already reversed, IS itself a reversal, or sits
 *         in a locked period (it goes through ReverseEntryModal, never a raw edit). The middle
 *         term is the one nothing else catches: reverse_journal_entry refuses only the other
 *         two, so an offer here posts "REVERSAL: REVERSAL: ...".
 * @see docs/MONEY.md (reversals) */
function ActivityCard({ card, isLast, expanded, onToggle, entries, linesByJe, decorate, isAdmin, onReverse, onJumpToGl }) {
  const hasSub = !!card.contextLine || (card.pills && card.pills.length > 0);
  const amount = card.moneyIn ? `+${fmtMoney(card.moneyIn)}` : card.moneyOut ? `-${fmtMoney(card.moneyOut)}` : '';
  return (
    <div style={{
      borderBottom: isLast ? 'none' : '1px solid var(--border)',
      opacity: card.isReversed ? 0.55 : 1,
    }}>
      <button
        type="button"
        onClick={onToggle}
        className="activity-row"
        style={{
          all: 'unset', cursor: 'pointer', display: 'block', width: '100%',
          padding: '7px 16px', boxSizing: 'border-box',
        }}
      >
        <div className="activity-row-grid">
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'var(--muted)' }}>
            {(() => { const I = TYPE_ICON[card.type]; return I ? <I size={15} /> : <span aria-hidden="true">•</span>; })()}
          </div>
          <div style={{ minWidth: 0 }}>
            <div title={card.isReversed ? `${card.headline} (reversed)` : card.headline} style={{ fontSize: 13.5, fontWeight: 600, lineHeight: 1.25, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
              {card.headline}
              {card.isReversed ? <span style={{ marginLeft: 8, fontSize: 10, fontWeight: 600, letterSpacing: 0.5, color: 'var(--red)' }}>REVERSED</span> : null}
            </div>
            {/* Rendered whenever there is anything to put on it, INCLUDING only a date. A row
                with no context has no second line on a wide container, so `is-date-only` keeps
                it out of the layout until the container query brings it back. */}
            {hasSub || card.date ? (
              <div className={`activity-sub${hasSub ? '' : ' is-date-only'}`}>
                {card.date ? (
                  <span className="activity-date-inline">{fmtDate(card.date)}</span>
                ) : null}
                {card.contextLine ? (
                  <span title={card.contextLine} style={{ color: 'var(--dim)', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', flexShrink: card.pills && card.pills.length ? 0 : 1 }}>{card.contextLine}</span>
                ) : null}
                {(card.pills || []).map((p, i) => <Pill key={i} pill={p} />)}
              </div>
            ) : null}
          </div>
          <div style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums', fontWeight: 600, fontSize: 13, whiteSpace: 'nowrap', color: card.moneyIn ? 'var(--green)' : card.moneyOut ? 'var(--orange)' : 'transparent' }}>
            {amount}
          </div>
          <div className="activity-date-col">
            {card.date ? fmtDate(card.date) : ''}
          </div>
          <div style={{ color: 'var(--dim)', textAlign: 'right', lineHeight: 0 }}>
            <ChevronIcon size={11} style={{ transform: expanded ? 'rotate(90deg)' : 'none', transition: 'transform 0.15s' }} />
          </div>
        </div>
      </button>

      {expanded ? (
        <div style={{ padding: '4px 16px 12px 52px', background: 'rgba(255,255,255,0.015)', borderTop: '1px solid var(--border)' }}>
          <div style={{ marginTop: 10, fontSize: 11, color: 'var(--muted)', textTransform: 'uppercase', letterSpacing: 1 }}>
            {entries.length} ledger {entries.length === 1 ? 'entry' : 'entries'}
          </div>
          {entries.map((e) => {
            const ll = decorate(linesByJe.get(e.id));
            const reverseDisabled = !!e.reversed_by_je_id || isReversalEntry(e) || e.is_locked;
            return (
              <div key={e.id} style={{ marginTop: 12, padding: 12, background: 'rgba(255,255,255,0.02)', borderRadius: 6 }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', gap: 8, marginBottom: 6, flexWrap: 'wrap' }}>
                  <div style={{ fontSize: 12 }}>
                    <span style={{ color: 'var(--muted)' }}>{fmtDate(e.entry_date)} · </span>
                    {e.description}
                    {e.reversed_by_je_id ? <span style={{ marginLeft: 6, color: 'var(--red)' }}>· REVERSED</span> : null}
                  </div>
                  <div style={{ display: 'flex', gap: 6 }}>
                    {onJumpToGl ? (
                      <button className="btn btn-ghost btn-sm" onClick={() => onJumpToGl(e)}>General Ledger</button>
                    ) : null}
                    {isAdmin && !reverseDisabled ? (
                      <button className="btn btn-danger btn-sm" onClick={() => onReverse(e)}>Reverse…</button>
                    ) : null}
                    {isAdmin && reverseDisabled ? (
                      // One condition, never "or": the row knows which of the three it is,
                      // and says it in the General Ledger's own words. A `title` on a
                      // disabled control reaches neither keyboard nor touch.
                      <span style={{ fontSize: 11, color: 'var(--muted)', alignSelf: 'center' }}>
                        {e.reversed_by_je_id ? 'Already reversed' : e.is_locked ? 'Period locked' : 'This entry is itself a reversal'}
                      </span>
                    ) : null}
                  </div>
                </div>
                <table style={{ width: '100%', fontSize: 12 }}>
                  <thead>
                    <tr style={{ color: 'var(--muted)' }}>
                      <th scope="col" style={{ textAlign: 'left' }}>Account</th>
                      <th scope="col" style={{ textAlign: 'left' }}>Note</th>
                      <th scope="col" style={{ textAlign: 'right' }}>Money In</th>
                      <th scope="col" style={{ textAlign: 'right' }}>Money Out</th>
                    </tr>
                  </thead>
                  <tbody>
                    {ll.map((l) => (
                      <tr key={l.id}>
                        <td>{[l.account_code, l.account_name].filter(Boolean).join('  ')}</td>
                        <td style={{ color: 'var(--muted)' }}>{l.description || ''}</td>
                        <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>{Number(l.debit) > 0 ? fmtMoney(l.debit) : ''}</td>
                        <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>{Number(l.credit) > 0 ? fmtMoney(l.credit) : ''}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            );
          })}
        </div>
      ) : null}
    </div>
  );
}
