/**
 * hooks/useSystemHealth.js - app-wide System Health state.
 *
 * One provider runs the full check sweep (from utils/systemHealthChecks) on
 * mount, every POLL_MS, and on tab refocus, so the global beacon and the nav
 * dot reflect reality without anyone opening the System Health page. The view,
 * the beacon, and the dot all consume this one context, so they can never
 * disagree.
 *
 * Used by: AdminDashboard (wraps AdminShell), HealthBeacon, the Sidebar nav dot,
 * and SystemHealthView.
 *
 * @see utils/systemHealthChecks.js (the check registry), CLAUDE.md "System Health"
 */
import React, { createContext, useContext, useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { supabase } from '../lib/supabase';
import { CHECKS, runChecks, summarize } from '../utils/systemHealthChecks';
import { humanizeError } from '../utils/errors';

const POLL_MS = 3 * 60 * 1000; // 3 minutes

const Ctx = createContext(null);

/** Provides { results, loading, lastRefresh, refreshAll, refreshOne, ...summary }. */
export function SystemHealthProvider({ children }) {
  const [results, setResults]         = useState({});
  const [loading, setLoading]         = useState(true);
  const [lastRefresh, setLastRefresh] = useState(null);
  const runningRef                    = useRef(false);

  /**
   * Run the full sweep and replace results.
   * @gotcha guarded by runningRef so a poll, a refocus, and a manual refresh
   *         cannot overlap into concurrent sweeps.
   */
  const refreshAll = useCallback(async () => {
    if (runningRef.current) return;       // never overlap polls
    runningRef.current = true;
    setLoading(true);
    try {
      const next = await runChecks(supabase);
      setResults(next);
      setLastRefresh(new Date());
    } finally {
      setLoading(false);
      runningRef.current = false;
    }
  }, []);

  /** Re-run one check by id (action buttons update without a full sweep). */
  const refreshOne = useCallback(async (id) => {
    const check = CHECKS.find(c => c.id === id);
    if (!check) return;
    try {
      const raw = await check.fetch(supabase);
      setResults(prev => ({ ...prev, [id]: check.evaluate(raw) }));
    } catch (e) {
      setResults(prev => ({ ...prev, [id]: { status: 'failed', summary: 'Error', history: [], tip: humanizeError(e).body || 'Unknown error.' } }));
    }
  }, []);

  useEffect(() => {
    refreshAll();
    const interval = setInterval(refreshAll, POLL_MS);
    const onVisible = () => { if (document.visibilityState === 'visible') refreshAll(); };
    document.addEventListener('visibilitychange', onVisible);
    return () => {
      clearInterval(interval);
      document.removeEventListener('visibilitychange', onVisible);
    };
  }, [refreshAll]);

  const summary = useMemo(() => summarize(results), [results]);

  const value = useMemo(
    () => ({ results, loading, lastRefresh, refreshAll, refreshOne, ...summary }),
    [results, loading, lastRefresh, refreshAll, refreshOne, summary]
  );

  return <Ctx.Provider value={value}>{children}</Ctx.Provider>;
}

/** Access System Health state; throws if used outside SystemHealthProvider. */
export function useSystemHealth() {
  const ctx = useContext(Ctx);
  if (!ctx) throw new Error('useSystemHealth must be used within SystemHealthProvider');
  return ctx;
}
