/**
 * components/shared/HealthBeacon.js: global system-status indicator.
 *
 * In-flow thin row at the top of the content, right-aligned to the page gutter,
 * scrolling with the page (NOT fixed). Healthy renders a calm dot + label with
 * no chrome; degraded/failed escalates in place to a bold named pill with a
 * chevron. One click opens System Health.
 *
 * @invariant reads useSystemHealth, the same poll SystemHealthView + the nav dot
 *            read, so the three indicators never disagree. @see CLAUDE.md
 */
import React from 'react';
import { useSystemHealth } from '../../hooks/useSystemHealth';
import { ChevronIcon } from './Icon';

export default function HealthBeacon({ onOpen }) {
  const { overall, label, loading } = useSystemHealth();

  const state = loading && !overall ? 'loading' : (overall || 'loading');
  const escalated = state === 'degraded' || state === 'failed';
  const text = state === 'loading' ? 'Checking systems…'
    : state === 'healthy' ? 'All systems operational'
    : label;

  return (
    <div className="health-beacon-bar">
      <button
        type="button"
        className={`health-beacon health-beacon--${state}`}
        onClick={onOpen}
        aria-label={escalated ? `System health: ${text}. Open System Health.` : 'All systems operational. Open System Health.'}
      >
        <span className={`health-dot health-dot--${state} health-beacon-dot`} />
        <span className="health-beacon-text">{text}</span>
        {escalated && <ChevronIcon size={12} className="health-beacon-chevron" aria-hidden />}
      </button>
    </div>
  );
}
